def desktop_dir() -> Path:
    if os.name == 'nt':
        try:

            class GUID(ctypes.Structure):
                _fields_ = [('Data1', wintypes.DWORD), ('Data2', wintypes.WORD), ('Data3', wintypes.WORD), ('Data4', ctypes.c_ubyte * 8)]
            folder_id = GUID(3032468538, 56108, 16972, (ctypes.c_ubyte * 8)(176, 41, 127, 233, 154, 135, 198, 65))
            raw_path = ctypes.c_void_p()
            known_folder = ctypes.windll.shell32.SHGetKnownFolderPath
            known_folder.argtypes = [ctypes.POINTER(GUID), wintypes.DWORD, wintypes.HANDLE, ctypes.POINTER(ctypes.c_void_p)]
            known_folder.restype = ctypes.c_long
            result = known_folder(ctypes.byref(folder_id), 0, None, ctypes.byref(raw_path))
            try:
                if result == 0 and raw_path.value:
                    return Path(ctypes.wstring_at(raw_path.value))
            finally:
                if raw_path.value:
                    free_memory = ctypes.windll.ole32.CoTaskMemFree
                    free_memory.argtypes = [ctypes.c_void_p]
                    free_memory.restype = None
                    free_memory(raw_path)
        except Exception:
            pass
        try:
            buffer = ctypes.create_unicode_buffer(32768)
            result = ctypes.windll.shell32.SHGetFolderPathW(None, 16, None, 0, buffer)
            if result == 0 and buffer.value:
                return Path(buffer.value)
        except Exception:
            pass
        user_profile = os.environ.get('USERPROFILE', '').strip()
        if user_profile:
            return Path(user_profile) / 'Desktop'
    return Path.home() / 'Desktop'

def windows_build_number() -> int:
    if os.name != 'nt':
        return 0
    try:

        class RTL_OSVERSIONINFOW(ctypes.Structure):
            _fields_ = [('dwOSVersionInfoSize', wintypes.DWORD), ('dwMajorVersion', wintypes.DWORD), ('dwMinorVersion', wintypes.DWORD), ('dwBuildNumber', wintypes.DWORD), ('dwPlatformId', wintypes.DWORD), ('szCSDVersion', wintypes.WCHAR * 128)]
        version = RTL_OSVERSIONINFOW()
        version.dwOSVersionInfoSize = ctypes.sizeof(version)
        rtl_get_version = ctypes.windll.ntdll.RtlGetVersion
        rtl_get_version.argtypes = [ctypes.POINTER(RTL_OSVERSIONINFOW)]
        rtl_get_version.restype = wintypes.LONG
        if rtl_get_version(ctypes.byref(version)) == 0:
            return int(version.dwBuildNumber)
    except Exception:
        pass
    try:
        return int(sys.getwindowsversion().build)
    except Exception:
        return 0

def available_physical_memory_bytes() -> int:
    if os.name != 'nt':
        return 0
    try:

        class MEMORYSTATUSEX(ctypes.Structure):
            _fields_ = [('dwLength', wintypes.DWORD), ('dwMemoryLoad', wintypes.DWORD), ('ullTotalPhys', ctypes.c_ulonglong), ('ullAvailPhys', ctypes.c_ulonglong), ('ullTotalPageFile', ctypes.c_ulonglong), ('ullAvailPageFile', ctypes.c_ulonglong), ('ullTotalVirtual', ctypes.c_ulonglong), ('ullAvailVirtual', ctypes.c_ulonglong), ('ullAvailExtendedVirtual', ctypes.c_ulonglong)]
        status = MEMORYSTATUSEX()
        status.dwLength = ctypes.sizeof(status)
        if ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(status)):
            return max(0, int(status.ullAvailPhys))
    except Exception:
        pass
    return 0

def adaptive_training_settings(config: dict, available_memory_bytes: int | None=None, cpu_count: int | None=None) -> dict[str, int]:
    experience_limit = max(1000, int(config.get('experience_limit_per_game', 1000)))
    sample_limit = max(100, min(experience_limit, int(config.get('train_sample_limit_per_game', 100))))
    epochs = max(1, int(config.get('training_epochs', 1)))
    batch_size = max(8, int(config.get('training_batch_size', 8)))
    memory = available_physical_memory_bytes() if available_memory_bytes is None else max(0, int(available_memory_bytes))
    processors = max(1, int(os.cpu_count() or 1) if cpu_count is None else int(cpu_count))
    gib = 1024 ** 3
    if memory and memory < 768 * 1024 ** 2:
        sample_limit = min(sample_limit, 2500)
        epochs = min(epochs, 4)
        batch_size = min(batch_size, 32)
    elif memory and memory < 1536 * 1024 ** 2:
        sample_limit = min(sample_limit, 6000)
        epochs = min(epochs, 6)
        batch_size = min(batch_size, 64)
    elif memory and memory < 3 * gib:
        sample_limit = min(sample_limit, 10000)
        epochs = min(epochs, 8)
        batch_size = min(batch_size, 96)
    elif memory >= 24 * gib and processors >= 16:
        sample_limit = min(experience_limit, max(sample_limit, min(48000, sample_limit * 3)))
        epochs = max(epochs, min(20, epochs + 6))
        batch_size = max(batch_size, min(512, batch_size * 3))
    elif memory >= 12 * gib and processors >= 12:
        sample_limit = min(experience_limit, max(sample_limit, min(32000, sample_limit * 2)))
        epochs = max(epochs, min(18, epochs + 4))
        batch_size = max(batch_size, min(384, batch_size * 2))
    elif memory >= 6 * gib and processors >= 8:
        sample_limit = min(experience_limit, max(sample_limit, min(24000, sample_limit * 3 // 2)))
        epochs = max(epochs, min(14, epochs + 2))
        batch_size = max(batch_size, min(256, batch_size * 2))
    sample_limit = max(100, min(experience_limit, sample_limit))
    epochs = max(1, min(1000, epochs))
    batch_size = max(8, min(8192, batch_size))
    return {'sample_limit': sample_limit, 'epochs': epochs, 'batch_size': batch_size}

def runtime_numeric_thread_budget(available_memory_bytes: int | None=None, cpu_count: int | None=None) -> int:
    memory = available_physical_memory_bytes() if available_memory_bytes is None else max(0, int(available_memory_bytes))
    processors = max(1, int(os.cpu_count() or 1) if cpu_count is None else int(cpu_count))
    gib = 1024 ** 3
    if processors <= 2 or (memory and memory < gib):
        return 1
    if processors <= 6 or (memory and memory < 3 * gib):
        return 2
    if processors <= 10 or (memory and memory < 8 * gib):
        return 3
    return 4

def adaptive_runtime_settings(config: dict, available_memory_bytes: int | None=None, cpu_count: int | None=None, providers: tuple[str, ...] | list[str] | None=None) -> dict[str, int | float | str | bool]:
    memory = available_physical_memory_bytes() if available_memory_bytes is None else max(0, int(available_memory_bytes))
    processors = max(1, int(os.cpu_count() or 1) if cpu_count is None else int(cpu_count))
    gib = 1024 ** 3
    tier = hardware_capability_tier(memory, processors, providers)
    sample_interval = max(0.02, min(1.0, float(config.get('sample_interval_seconds', 0.07))))
    step_pause = max(0.0, min(2.0, float(config.get('step_pause_seconds', 0.025))))
    confirmation_delay = max(0.0, min(0.25, float(config.get('confirmation_delay_seconds', 0.035))))
    planning_horizon = max(4, min(WORLD_MODEL_MAX_PLANNING_HORIZON, int(config.get('planning_horizon', 8))))
    planning_refresh_steps = max(8, min(512, int(config.get('planning_refresh_steps', 48))))
    online_checkpoint_steps = max(32, min(10000, int(config.get('online_checkpoint_steps', 256))))
    translation_search_radius = max(1, min(4, int(config.get('translation_search_radius', 2))))
    if tier == 'low_numpy':
        sample_interval = max(sample_interval, 0.095)
        step_pause = max(step_pause, 0.035)
        confirmation_delay = min(confirmation_delay, 0.025)
        planning_horizon = min(planning_horizon, 8)
        planning_refresh_steps = max(planning_refresh_steps, 80)
        online_checkpoint_steps = max(online_checkpoint_steps, 512)
        translation_search_radius = min(translation_search_radius, 2)
    elif tier == 'high_directml':
        sample_interval = min(sample_interval, 0.05)
        step_pause = min(step_pause, 0.016)
        planning_horizon = max(8, planning_horizon)
        planning_refresh_steps = min(planning_refresh_steps, 28)
        online_checkpoint_steps = min(online_checkpoint_steps, 160)
        translation_search_radius = max(translation_search_radius, 3)
    else:
        sample_interval = min(sample_interval, 0.065)
        step_pause = min(step_pause, 0.023)
        planning_horizon = max(6, planning_horizon)
        planning_refresh_steps = min(planning_refresh_steps, 40)
        online_checkpoint_steps = min(online_checkpoint_steps, 224)
    if tier == 'low_numpy':
        model_hidden_size, sequence_length, burn_in_steps = (256, 96, 32)
        replay_capacity, replay_batch = (1024, 32)
        latent_horizon = max(4, min(world_planning_budget(tier)[2], planning_horizon))
    elif tier == 'high_directml':
        model_hidden_size, sequence_length, burn_in_steps = (1024, 256, 64)
        replay_capacity, replay_batch = (8192, 128)
        latent_horizon = max(4, min(WORLD_MODEL_MAX_PLANNING_HORIZON, planning_horizon))
    else:
        model_hidden_size, sequence_length, burn_in_steps = (512, 192, 64)
        replay_capacity, replay_batch = (4096, 64)
        latent_horizon = max(4, min(WORLD_MODEL_MAX_PLANNING_HORIZON, planning_horizon))
    return {'hardware_tier': tier, 'hidden_size': model_hidden_size, 'sequence_length': sequence_length, 'burn_in_steps': burn_in_steps, 'online_replay_capacity': replay_capacity, 'online_replay_batch_size': replay_batch, 'use_latent_world_model': latent_horizon > 0, 'latent_planning_horizon': latent_horizon, 'use_onnx': tier != 'low_numpy', 'sample_interval_seconds': max(0.02, min(1.0, sample_interval)), 'step_pause_seconds': max(0.0, min(2.0, step_pause)), 'confirmation_delay_seconds': max(0.0, min(0.25, confirmation_delay)), 'planning_horizon': max(4, min(WORLD_MODEL_MAX_PLANNING_HORIZON, planning_horizon)), 'planning_refresh_steps': max(8, min(512, planning_refresh_steps)), 'online_checkpoint_steps': max(32, min(10000, online_checkpoint_steps)), 'translation_search_radius': max(1, min(4, translation_search_radius)), 'low_level_control_hz': int(LOW_LEVEL_CONTROL_HZ.get(tier, 30)), 'high_level_planning_hz': int(HIGH_LEVEL_PLANNING_HZ.get(tier, 5)), 'low_level_control_period': 1.0 / max(1, int(LOW_LEVEL_CONTROL_HZ.get(tier, 30))), 'high_level_planning_period': 1.0 / max(1, int(HIGH_LEVEL_PLANNING_HZ.get(tier, 5)))}

def world_planning_budget(runtime_tier: str) -> tuple[int, int, int]:
    tier = str(runtime_tier)
    if tier == 'high_directml':
        return (32, 12, 24)
    if tier == 'mid_onnx':
        return (16, 8, 16)
    return (8, 5, 8)

def configured_teacher_hidden_size(config: dict) -> int:
    try:
        requested = int(config.get('hidden_size', TEACHER_HIDDEN_SIZE))
    except (TypeError, ValueError, OverflowError):
        requested = TEACHER_HIDDEN_SIZE
    return max(256, min(TEACHER_HIDDEN_SIZE, requested))

def adaptive_action_catalog_limit(config: dict, runtime_tier: str) -> int:
    tier_floor = {'low_numpy': 512, 'mid_onnx': 768, 'high_directml': 1024}.get(str(runtime_tier), 512)
    try:
        configured = int(config.get('max_action_count', 512))
    except (TypeError, ValueError, OverflowError):
        configured = 512
    return max(512, min(1024, max(configured, tier_floor)))

def training_vector_cache_limit(sample_count: int, available_memory_bytes: int | None=None) -> int:
    samples = max(0, int(sample_count))
    memory = available_physical_memory_bytes() if available_memory_bytes is None else max(0, int(available_memory_bytes))
    gib = 1024 ** 3
    if memory and memory < 768 * 1024 ** 2:
        hardware_limit = 96
    elif memory and memory < 1536 * 1024 ** 2:
        hardware_limit = 256
    elif memory and memory < 3 * gib:
        hardware_limit = 768
    elif memory and memory < 6 * gib:
        hardware_limit = 1536
    elif memory and memory < 12 * gib:
        hardware_limit = 3072
    elif memory:
        hardware_limit = 8192
    else:
        hardware_limit = 1024
    useful_limit = max(64, min(8192, samples // 3 if samples >= 192 else samples))
    return max(0, min(samples, hardware_limit, useful_limit))

def adaptive_global_training_settings(config: dict, profile_count: int, available_memory_bytes: int | None=None, cpu_count: int | None=None) -> dict[str, int]:
    profiles = max(1, int(profile_count))
    local = adaptive_training_settings(config, available_memory_bytes, cpu_count)
    memory = available_physical_memory_bytes() if available_memory_bytes is None else max(0, int(available_memory_bytes))
    processors = max(1, int(os.cpu_count() or 1) if cpu_count is None else int(cpu_count))
    gib = 1024 ** 3
    if memory and memory < 768 * 1024 ** 2:
        hardware_limit = 768
    elif memory and memory < 1536 * 1024 ** 2:
        hardware_limit = 1500
    elif memory and memory < 3 * gib:
        hardware_limit = 3000
    elif memory and memory < 6 * gib:
        hardware_limit = 6000
    elif memory and memory < 12 * gib:
        hardware_limit = 10000
    elif memory and memory < 24 * gib:
        hardware_limit = 18000
    elif memory:
        hardware_limit = GLOBAL_TRAINING_SAMPLE_LIMIT
    else:
        hardware_limit = 8000
    if processors <= 2:
        hardware_limit = min(hardware_limit, 2500)
    elif processors <= 4:
        hardware_limit = min(hardware_limit, 6000)
    requested = max(512, min(GLOBAL_TRAINING_SAMPLE_LIMIT, int(local['sample_limit']) * 2))
    sample_limit = max(256, min(requested, hardware_limit))
    per_profile_limit = max(GLOBAL_TRAINING_MIN_PER_PROFILE, min(int(local['sample_limit']), math.ceil(sample_limit / profiles)))
    return {'sample_limit': int(sample_limit), 'per_profile_limit': int(per_profile_limit), 'epochs': max(2, min(int(local['epochs']), max(3, int(local['epochs']) // 2))), 'batch_size': int(local['batch_size'])}
