def require_managed_path(path: Path) -> Path:
    root = APP_DIR.resolve()
    candidate = Path(path).resolve()
    if candidate != root and root not in candidate.parents:
        raise RuntimeError(f'禁止写入桌面 AnyGameAI 之外：{candidate}')
    return candidate
