def accelerated_temporal_policy_session(model: dict):
    if str(model.get('runtime_tier', 'low_numpy')) == 'low_numpy':
        return None
    try:
        revision = (int(model.get('optimizer_step', 0)), int(model.get('online_updates', 0)), str(model.get('action_hash', '')))
        cached_export = model.get('_temporal_onnx_export')
        if isinstance(cached_export, tuple) and len(cached_export) == 2 and (cached_export[0] == revision):
            payload = cached_export[1]
        else:
            payload = temporal_policy_model_bytes(model)
            model['_temporal_onnx_export'] = (revision, payload)
        key = 'temporal:' + hashlib.sha256(payload).hexdigest()
    except Exception:
        return None
    with ONNX_SESSION_LOCK:
        cached = ONNX_SESSION_CACHE.get(key)
        if cached is not None:
            return cached
        try:
            ort = import_onnxruntime(True)
            providers = list(ort.get_available_providers())
            preferred = []
            if 'DmlExecutionProvider' in providers:
                preferred.append('DmlExecutionProvider')
            if 'CPUExecutionProvider' in providers:
                preferred.append('CPUExecutionProvider')
            session = ort.InferenceSession(payload, providers=preferred or providers)
            ONNX_SESSION_CACHE[key] = session
            return session
        except Exception:
            return None

def accelerated_temporal_policy(np, model: dict, combined_steps: list, initial_hidden):
    session = accelerated_temporal_policy_session(model)
    if session is None or not 1 <= len(combined_steps) <= TEMPORAL_FRAMES:
        return None
    combined_size = int(model['frame_proj'].shape[0])
    feed = {'initial_hidden': np.asarray(initial_hidden, dtype=np.float32).reshape(1, -1)}
    for step in range(TEMPORAL_FRAMES):
        valid = step < len(combined_steps)
        feed[f'step{step}'] = np.asarray(combined_steps[step], dtype=np.float32).reshape(1, combined_size) if valid else np.zeros((1, combined_size), dtype=np.float32)
        feed[f'mask{step}'] = np.asarray([[1.0 if valid else 0.0]], dtype=np.float32)
    try:
        hidden, probabilities, adapted = session.run(['hidden', 'probabilities', 'adapted_hidden'], feed)
        hidden = hidden[0].astype(np.float32, copy=False)
        probabilities = probabilities[0].astype(np.float32, copy=False)
        adapted = adapted[0].astype(np.float32, copy=False)
        if hidden.shape != (int(model['hidden_size']),) or probabilities.shape != (len(model['action_factors']),) or (not np.isfinite(hidden).all()) or (not np.isfinite(probabilities).all()):
            return None
        cache_key = hashlib.blake2s(hidden.tobytes(), digest_size=8).digest()
        model['_accelerated_policy_cache'] = (cache_key, probabilities.copy(), adapted.copy())
        return hidden
    except Exception:
        return None

def local_onnx_probe_command(site_packages: Path, require_dml: bool) -> list[str]:
    code = 'import sys;sys.path.insert(0,' + repr(str(site_packages)) + ");import onnxruntime as o;p=o.get_available_providers();assert 'CPUExecutionProvider' in p;" + ("assert 'DmlExecutionProvider' in p;" if require_dml else '') + 'print(o.__version__,p)'
    return [sys.executable, '-I', '-c', code]

def current_runtime_model_hashes() -> dict[str, str]:
    return {
        str(name): sha256_file(Path(spec['path']))
        for name, spec in active_model_catalog().items()
    }

def runtime_models_match_state(state: dict) -> bool:
    if not isinstance(state, dict):
        return False
    expected = state.get('models')
    if not isinstance(expected, dict) or set(expected) != set(active_model_catalog()):
        return False
    try:
        actual = current_runtime_model_hashes()
    except OSError:
        return False
    return all(hmac.compare_digest(str(expected.get(name, '')), digest) for name, digest in actual.items())

def copy_runtime_model_hashes(snapshot: dict) -> dict:
    hashes = current_runtime_model_hashes()
    snapshot['models'] = hashes
    legacy_paths = {
        'student_model_sha256': 'openai-clip-vit-b32',
        'teacher_model_sha256': 'openai-clip-vit-b32',
        'text_model_sha256': 'ppocr-v4-recognizer',
        'semantic_model_sha256': 'multilingual-e5-small',
    }
    for key, name in legacy_paths.items():
        snapshot[key] = hashes.get(name, '')
    return snapshot



