def _temporal_combined_feature(np, model: dict, frame, action_value: int, duration_value: float):
    model['_perception_current_action'] = int(action_value)
    visual = perception_projection_features(np, model, frame)
    action_embedding = np.zeros(ACTION_EMBEDDING_SIZE, dtype=np.float32)
    kind_values = [0.0] * len(CONTROL_KINDS)
    has_action = 0.0
    key_density = 0.0
    button_density = 0.0
    mouse_value = 0.0
    if 0 <= int(action_value) < len(model['action_factors']):
        action_index = int(action_value)
        has_action = 1.0
        action_embedding = model['action_embedding'][action_index]
        factors = model['action_factors'][action_index]
        kind_index = int(factors[0])
        if 0 <= kind_index < len(kind_values):
            kind_values[kind_index] = 1.0
        mouse_value = int(factors[1]) / max(1, MOUSE_HEAD_SIZE - 1)
        key_density = min(1.0, float(np.count_nonzero(model['action_key_multihot'][action_index])) / 6.0)
        button_density = min(1.0, float(np.count_nonzero(model['action_button_multihot'][action_index])) / 3.0)
    duration_index = duration_bin(float(duration_value))
    context = np.concatenate((action_embedding, model['duration_embedding'][duration_index], np.asarray([has_action, *kind_values, key_density, button_density, mouse_value, max(0.0, min(1.0, float(duration_value) / 0.5))], dtype=np.float32)))
    if len(context) != MODEL_GLOBAL_FEATURES:
        raise RuntimeError('结构化动作上下文尺寸无效')
    combined = np.concatenate((visual, context)).astype(np.float32, copy=False)
    if combined.shape != (int(model['frame_proj'].shape[0]),):
        raise RuntimeError('时序模型输入尺寸无效')
    return combined

def _model_hidden_state_from_vector(np, model: dict, vector: dict, return_cache: bool=False, initial_hidden=None):
    if initial_hidden is None:
        hidden = np.zeros(int(model['hidden_size']), dtype=np.float32)
    else:
        hidden = np.asarray(initial_hidden, dtype=np.float32).reshape(-1).copy()
        if hidden.shape != (int(model['hidden_size']),) or not np.isfinite(hidden).all():
            raise ValueError('循环隐藏状态尺寸无效')
    caches = []
    actions = vector['actions']
    durations = vector['durations']
    training = bool(return_cache)
    if not return_cache and str(model.get('runtime_tier', 'low_numpy')) != 'low_numpy' and (1 <= len(vector['frames']) <= TEMPORAL_FRAMES):
        try:
            combined_steps = [_temporal_combined_feature(np, model, frame, int(actions[index]), float(durations[index])) for index, frame in enumerate(vector['frames'])]
            accelerated_hidden = accelerated_temporal_policy(np, model, combined_steps, hidden)
            if accelerated_hidden is not None:
                return accelerated_hidden
        except Exception:
            pass
    for index, frame in enumerate(vector['frames']):
        action_value = int(actions[index])
        duration_value = float(durations[index])
        model['_perception_current_action'] = action_value
        if return_cache:
            visual, conv_cache = perception_projection_features(np, model, frame, return_cache=True, training=training)
        else:
            visual = perception_projection_features(np, model, frame)
            conv_cache = None
        action_embedding = np.zeros(ACTION_EMBEDDING_SIZE, dtype=np.float32)
        kind_values = [0.0] * len(CONTROL_KINDS)
        has_action = 0.0
        key_density = 0.0
        button_density = 0.0
        mouse_value = 0.0
        if 0 <= action_value < len(model['action_factors']):
            has_action = 1.0
            action_embedding = model['action_embedding'][action_value]
            factors = model['action_factors'][action_value]
            kind_index = int(factors[0])
            if 0 <= kind_index < len(kind_values):
                kind_values[kind_index] = 1.0
            mouse_bucket = int(factors[1])
            mouse_value = mouse_bucket / max(1, MOUSE_HEAD_SIZE - 1)
            key_density = min(1.0, float(np.count_nonzero(model['action_key_multihot'][action_value])) / 6.0)
            button_density = min(1.0, float(np.count_nonzero(model['action_button_multihot'][action_value])) / 3.0)
        duration_index = duration_bin(duration_value)
        duration_embedding = model['duration_embedding'][duration_index]
        context = np.concatenate((action_embedding, duration_embedding, np.asarray([has_action, *kind_values, key_density, button_density, mouse_value, max(0.0, min(1.0, duration_value / 0.5))], dtype=np.float32)))
        if len(context) != MODEL_GLOBAL_FEATURES:
            raise RuntimeError('结构化动作上下文尺寸无效')
        combined = np.concatenate((visual, context))
        projected_pre = combined @ model['frame_proj'] + model['frame_bias']
        projected = np.tanh(projected_pre)
        previous_hidden = hidden
        update = _sigmoid(np, projected @ model['Wz'] + previous_hidden @ model['Uz'] + model['bz'])
        reset = _sigmoid(np, projected @ model['Wr'] + previous_hidden @ model['Ur'] + model['br'])
        candidate = np.tanh(projected @ model['Wh'] + reset * previous_hidden @ model['Uh'] + model['bh'])
        gru_hidden = (1.0 - update) * previous_hidden + update * candidate
        memory_width = max(8, min(int(model['hidden_size']) // 4, int(model['hidden_size']) // 2))
        source_slice = slice(0, memory_width)
        memory_slice = slice(int(model['hidden_size']) - memory_width, int(model['hidden_size']))
        thirds = np.array_split(np.arange(memory_width), 3)
        memory_decays = np.empty(memory_width, dtype=np.float32)
        for segment, decay in zip(thirds, (0.9, 0.97, 0.995)):
            memory_decays[segment] = decay
        slow_memory = memory_decays * previous_hidden[memory_slice] + (1.0 - memory_decays) * gru_hidden[source_slice]
        hidden = gru_hidden.copy()
        hidden[memory_slice] = 0.65 * gru_hidden[memory_slice] + 0.35 * slow_memory
        if return_cache:
            caches.append({'combined': combined, 'projected': projected, 'previous_hidden': previous_hidden, 'update': update, 'reset': reset, 'candidate': candidate, 'conv_cache': conv_cache, 'action_value': action_value, 'duration_index': duration_index, 'memory_width': memory_width, 'memory_decays': memory_decays})
    hidden = hidden.astype(np.float32, copy=False)
    if return_cache:
        return (hidden, caches)
    return hidden

def _accumulate_gradient(gradients: dict[str, object], key: str, value) -> None:
    if key in gradients:
        gradients[key] += value.astype(gradients[key].dtype, copy=False)

def _backprop_perception_adapter(np, model: dict, perception_cache: dict | None, visual_gradient, gradients: dict[str, object]) -> None:
    if not isinstance(perception_cache, dict):
        return
    gradient = np.asarray(visual_gradient, dtype=np.float32).reshape(-1)
    if gradient.shape != (GAME_PERCEPTION_VECTOR_DIM,):
        return
    scene = perception_cache.get('scene') or {}
    hud = perception_cache.get('hud') or {}
    scene_output = np.asarray(scene.get('global', []), dtype=np.float32)
    motion_output = np.asarray(scene.get('motion_tokens', []), dtype=np.float32)
    patch_output = np.asarray(scene.get('patch_tokens', []), dtype=np.float32)
    hud_output = np.asarray(hud.get('hud_token', []), dtype=np.float32)
    if scene_output.shape != (SCENE_GLOBAL_DIM,) or motion_output.shape != (MOTION_TOKEN_DIM,) or patch_output.shape != (PATCH_TOKEN_ROWS, PATCH_TOKEN_COLUMNS, PATCH_TOKEN_DIM) or (hud_output.shape != (HUD_TOKEN_DIM,)):
        return
    scene_start = 0
    slots_start = scene_start + SCENE_GLOBAL_DIM
    hud_start = slots_start + OBJECT_SLOT_COUNT * OBJECT_SLOT_DIM
    motion_start = hud_start + HUD_TOKEN_DIM
    patch_start = motion_start + MOTION_TOKEN_DIM
    scene_gradient = gradient[scene_start:slots_start]
    hud_gradient = gradient[hud_start:motion_start]
    motion_gradient = gradient[motion_start:patch_start].copy()
    patch_gradient = gradient[patch_start:].reshape(PATCH_TOKEN_ROWS, PATCH_TOKEN_COLUMNS, PATCH_TOKEN_DIM).copy()
    scene_input = perception_cache.get('scene_input')
    if scene_input is not None:
        scene_input = np.asarray(scene_input, dtype=np.float32)
        scene_pre_gradient = scene_gradient * (1.0 - scene_output * scene_output)
        _accumulate_gradient(gradients, 'perception_scene_w', np.outer(scene_input, scene_pre_gradient))
        _accumulate_gradient(gradients, 'perception_scene_b', scene_pre_gradient)
        input_gradient = model['perception_scene_w'] @ scene_pre_gradient
        patch_gradient += input_gradient[:PATCH_TOKEN_DIM][None, None, :] / (PATCH_TOKEN_ROWS * PATCH_TOKEN_COLUMNS)
        max_gradient = input_gradient[PATCH_TOKEN_DIM:PATCH_TOKEN_DIM * 2]
        winners = np.argmax(patch_output.reshape(-1, PATCH_TOKEN_DIM), axis=0)
        flat_patch_gradient = patch_gradient.reshape(-1, PATCH_TOKEN_DIM)
        for channel, winner in enumerate(winners):
            flat_patch_gradient[int(winner), channel] += max_gradient[channel]
        motion_gradient += input_gradient[PATCH_TOKEN_DIM * 2:]
    hud_base = perception_cache.get('hud_base')
    if hud_base is not None:
        hud_base = np.asarray(hud_base, dtype=np.float32)
        hud_pre_gradient = hud_gradient * (1.0 - hud_output * hud_output)
        _accumulate_gradient(gradients, 'perception_hud_w', np.outer(hud_base, hud_pre_gradient))
        _accumulate_gradient(gradients, 'perception_hud_b', hud_pre_gradient)
    motion_base = perception_cache.get('motion_base')
    if motion_base is not None:
        motion_base = np.asarray(motion_base, dtype=np.float32)
        motion_pre_gradient = motion_gradient * (1.0 - motion_output * motion_output)
        _accumulate_gradient(gradients, 'perception_motion_w', np.outer(motion_base, motion_pre_gradient))
        _accumulate_gradient(gradients, 'perception_motion_b', motion_pre_gradient)
    patch_statistics = perception_cache.get('patch_statistics')
    if patch_statistics is not None:
        patch_statistics = np.asarray(patch_statistics, dtype=np.float32)
        patch_pre_gradient = patch_gradient * (1.0 - patch_output * patch_output)
        _accumulate_gradient(gradients, 'perception_patch_w', np.einsum('rcf,rcd->fd', patch_statistics, patch_pre_gradient, optimize=True))
        _accumulate_gradient(gradients, 'perception_patch_b', patch_pre_gradient.sum(axis=(0, 1)))

def _backprop_temporal_encoder(np, model: dict, caches: list[dict], hidden_gradient, learning_rate: float, gradients: dict[str, object] | None=None, return_initial_gradient: bool=False) -> dict[str, object]:
    local = gradients is None
    if local:
        gradients = {key: np.zeros_like(model[key], dtype=np.float32) for key in (*_CONV_PARAMETER_KEYS, 'frame_proj', 'frame_bias', 'action_embedding', 'duration_embedding', 'Wz', 'Uz', 'bz', 'Wr', 'Ur', 'br', 'Wh', 'Uh', 'bh')}
    dh = np.asarray(hidden_gradient, dtype=np.float32)
    visual_dim = visual_encoder_output_dim()
    for cache in reversed(caches):
        combined = cache['combined']
        projected = cache['projected']
        previous_hidden = cache['previous_hidden']
        update = cache['update']
        reset = cache['reset']
        candidate = cache['candidate']
        memory_width = int(cache.get('memory_width', 0))
        direct_previous = np.zeros_like(dh, dtype=np.float32)
        if memory_width > 0:
            memory_slice = slice(len(dh) - memory_width, len(dh))
            source_slice = slice(0, memory_width)
            decays = np.asarray(cache.get('memory_decays'), dtype=np.float32)
            output_gradient = dh
            gru_gradient = output_gradient.copy()
            tail_gradient = output_gradient[memory_slice].copy()
            gru_gradient[memory_slice] = 0.65 * tail_gradient
            gru_gradient[source_slice] += 0.35 * (1.0 - decays) * tail_gradient
            direct_previous[memory_slice] += 0.35 * decays * tail_gradient
            dh = gru_gradient
        d_previous = dh * (1.0 - update) + direct_previous
        d_update = dh * (candidate - previous_hidden)
        d_candidate = dh * update
        candidate_pre_gradient = d_candidate * (1.0 - candidate * candidate)
        _accumulate_gradient(gradients, 'Wh', np.outer(projected, candidate_pre_gradient))
        _accumulate_gradient(gradients, 'Uh', np.outer(reset * previous_hidden, candidate_pre_gradient))
        _accumulate_gradient(gradients, 'bh', candidate_pre_gradient)
        d_projected = candidate_pre_gradient @ model['Wh'].T
        d_reset_previous = candidate_pre_gradient @ model['Uh'].T
        d_reset = d_reset_previous * previous_hidden
        d_previous += d_reset_previous * reset
        reset_pre_gradient = d_reset * reset * (1.0 - reset)
        _accumulate_gradient(gradients, 'Wr', np.outer(projected, reset_pre_gradient))
        _accumulate_gradient(gradients, 'Ur', np.outer(previous_hidden, reset_pre_gradient))
        _accumulate_gradient(gradients, 'br', reset_pre_gradient)
        d_projected += reset_pre_gradient @ model['Wr'].T
        d_previous += reset_pre_gradient @ model['Ur'].T
        update_pre_gradient = d_update * update * (1.0 - update)
        _accumulate_gradient(gradients, 'Wz', np.outer(projected, update_pre_gradient))
        _accumulate_gradient(gradients, 'Uz', np.outer(previous_hidden, update_pre_gradient))
        _accumulate_gradient(gradients, 'bz', update_pre_gradient)
        d_projected += update_pre_gradient @ model['Wz'].T
        d_previous += update_pre_gradient @ model['Uz'].T
        projected_pre_gradient = d_projected * (1.0 - projected * projected)
        _accumulate_gradient(gradients, 'frame_proj', np.outer(combined, projected_pre_gradient))
        _accumulate_gradient(gradients, 'frame_bias', projected_pre_gradient)
        combined_gradient = projected_pre_gradient @ model['frame_proj'].T
        _backprop_perception_adapter(np, model, cache.get('conv_cache'), combined_gradient[:visual_dim], gradients)
        context_gradient = combined_gradient[visual_dim:]
        action_value = int(cache.get('action_value', -1))
        if 'action_embedding' in gradients and 0 <= action_value < len(model['action_embedding']):
            gradients['action_embedding'][action_value] += context_gradient[:ACTION_EMBEDDING_SIZE]
        duration_index = int(cache.get('duration_index', 0))
        if 'duration_embedding' in gradients and 0 <= duration_index < DURATION_HEAD_SIZE:
            start = ACTION_EMBEDDING_SIZE
            gradients['duration_embedding'][duration_index] += context_gradient[start:start + DURATION_EMBEDDING_SIZE]
        dh = d_previous
    if local:
        trainable = [gradient for gradient in gradients.values()]
        clip_gradients_by_global_norm(np, trainable, 8.0)
        step = max(0.0, min(0.02, float(learning_rate)))
        for key, gradient in gradients.items():
            model[key] -= step * gradient
        _synchronize_quantized_conv_weights(np, model)
    if return_initial_gradient:
        return (gradients, dh.astype(np.float32, copy=False))
    return gradients

def _model_hidden_state(np, model: dict, feature: bytes):
    return _latest_temporal_hidden(np, model, feature)

def recurrent_model_step(np, model: dict, feature: bytes, previous_hidden, previous_action: int=-1, previous_duration: float=0.0, return_cache: bool=False):
    frame = normalize_feature_bytes(feature)
    vector = {'frames': [_perception_frame_input(np, frame)], 'actions': np.asarray([int(previous_action)], dtype=np.int32), 'durations': np.asarray([float(previous_duration)], dtype=np.float32)}
    return _model_hidden_state_from_vector(np, model, vector, return_cache=return_cache, initial_hidden=previous_hidden)

def pretrain_visual_encoder(np, model: dict, records: list[dict], learning_rate: float, stop_event: threading.Event | None=None, maximum_steps: int=64, target_model: dict | None=None) -> dict[str, float]:
    parts = [part for part in _continuous_trajectory_parts(records) if len(part) >= 3]
    if not parts:
        return {'steps': 0.0, 'loss': 0.0, 'action_prediction_steps': 0.0, 'inverse_action_steps': 0.0, 'multistep_prediction_steps': 0.0, 'occlusion_reconstruction_steps': 0.0, 'hud_prediction_steps': 0.0}

    def last_frame(record: dict) -> bytes:
        frames, _, _ = decode_temporal_state(record['state'])
        return frames[-1]

    def frame_luminance(record: dict):
        frame = normalize_feature_bytes(last_frame(record))
        pixels = FEATURE_WIDTH * FEATURE_HEIGHT
        return np.frombuffer(frame[:pixels], dtype=np.uint8).astype(np.float32)

    def reliable_adjacent(anchor: dict, positive: dict) -> bool:
        if bool(anchor.get('done')) or anchor.get('next_state') is None:
            return False
        if int(anchor.get('outcome_type', OUTCOME_NONE)) in (OUTCOME_DEATH, OUTCOME_VICTORY, OUTCOME_LEVEL):
            return False
        try:
            anchor_frame = last_frame(anchor)
            positive_frame = last_frame(positive)
            left = frame_luminance(anchor)
            right = frame_luminance(positive)
            left_mean = float(left.mean())
            right_mean = float(right.mean())
            if left_mean < 8.0 or right_mean < 8.0:
                return False
            pixels = FEATURE_WIDTH * FEATURE_HEIGHT
            motion, changed, flicker = visual_change_metrics(anchor_frame[:pixels], positive_frame[:pixels])
            fade = max(0.0, min(1.0, (left_mean - right_mean) / 255.0))
            return flicker <= 0.12 and fade <= 0.18 and (changed <= 0.42) and (motion <= 0.55)
        except Exception:
            return False
    hashes: dict[int, str] = {}

    def record_hash(record: dict) -> str:
        key = id(record)
        value = hashes.get(key)
        if value is None:
            value = _temporal_frame_hash(record['state'])
            hashes[key] = value
        return value
    examples: list[tuple[dict, dict | None, dict, int]] = []
    action_pairs: list[tuple[dict, dict]] = []
    rollout_starts: list[tuple[list[dict], int]] = []
    for part_index, part in enumerate(parts):
        raise_if_cancelled(stop_event)
        for position, anchor in enumerate(part):
            raise_if_cancelled(stop_event)
            negative = None
            offsets = list(range(8, 33))
            for offset in offsets:
                raise_if_cancelled(stop_event)
                candidate_position = position + offset
                if candidate_position >= len(part):
                    break
                candidate = part[candidate_position]
                if _perceptual_hash_similarity(record_hash(anchor), record_hash(candidate)) <= 0.7:
                    negative = candidate
                    break
            if negative is None:
                for other_index in range(1, len(parts)):
                    raise_if_cancelled(stop_event)
                    other = parts[(part_index + other_index) % len(parts)]
                    candidate = other[(position * 7 + other_index) % len(other)]
                    if _perceptual_hash_similarity(record_hash(anchor), record_hash(candidate)) <= 0.65:
                        negative = candidate
                        break
            if negative is None:
                continue
            examples.append((anchor, None, negative, position + part_index * 131))
            if position + 1 < len(part) and reliable_adjacent(anchor, part[position + 1]):
                examples.append((anchor, part[position + 1], negative, -1))
                action_pairs.append((anchor, part[position + 1]))
        if len(part) >= WORLD_MODEL_OVERSHOOT_MIN_STEPS + 1:
            stride = max(1, len(part) // 24)
            for position in range(0, len(part) - WORLD_MODEL_OVERSHOOT_MIN_STEPS, stride):
                raise_if_cancelled(stop_event)
                rollout_starts.append((part, position))
    if not examples:
        return {'steps': 0.0, 'loss': 0.0, 'action_prediction_steps': 0.0, 'inverse_action_steps': 0.0, 'multistep_prediction_steps': 0.0, 'occlusion_reconstruction_steps': 0.0, 'hud_prediction_steps': 0.0}
    rng = np.random.default_rng(VISUAL_INITIALIZATION_SEED + int(model.get('visual_pretraining_steps', 0)))
    rng.shuffle(examples)
    rng.shuffle(action_pairs)
    limit = max(1, min(int(maximum_steps), len(examples)))
    step_size = max(1e-06, min(0.002, float(learning_rate) * 0.2))
    loss_total = 0.0
    trained = 0
    occlusion_steps = 0
    adjacent_steps = 0
    batch_gradients = {key: np.zeros_like(model[key], dtype=np.float32) for key in _CONV_PARAMETER_KEYS}
    batch_count = 0

    def encoded_record(record: dict):
        channels = _perception_frame_input(np, last_frame(record))
        return perception_projection_features(np, model, channels, return_cache=True, training=True)

    def encoded_augmentation(record: dict, seed: int):
        channels = _perception_frame_input(np, last_frame(record))
        base = np.asarray(channels['base'], dtype=np.float32).copy()
        local = np.random.default_rng(VISUAL_INITIALIZATION_SEED ^ int(seed))
        shift_y = int(local.integers(-2, 3))
        shift_x = int(local.integers(-3, 4))
        base = np.roll(base, (shift_y, shift_x), axis=(1, 2))
        brightness = float(local.uniform(0.92, 1.08))
        base[:3] = np.clip(base[:3] * brightness, -1.0, 1.0)
        if float(local.random()) < 0.75:
            height = int(local.integers(3, max(4, FEATURE_HEIGHT // 6)))
            width = int(local.integers(4, max(5, FEATURE_WIDTH // 8)))
            top = int(local.integers(0, max(1, FEATURE_HEIGHT - height + 1)))
            left = int(local.integers(0, max(1, FEATURE_WIDTH - width + 1)))
            base[:, top:top + height, left:left + width] = 0.0
        augmented = {'base': base, 'spatial': channels['spatial']}
        return perception_projection_features(np, model, augmented, return_cache=True, training=True)

    def apply_contrastive_batch() -> None:
        nonlocal batch_count
        if batch_count <= 0:
            return
        for gradient in batch_gradients.values():
            raise_if_cancelled(stop_event)
            gradient /= batch_count
        clip_gradients_by_global_norm(np, list(batch_gradients.values()), 4.0)
        for key, gradient in batch_gradients.items():
            raise_if_cancelled(stop_event)
            model[key] -= step_size * gradient
            gradient.fill(0.0)
        _synchronize_quantized_conv_weights(np, model)
        batch_count = 0
    for anchor_record, positive_record, negative_record, augmentation_seed in examples[:limit]:
        raise_if_cancelled(stop_event)
        anchor, anchor_cache = encoded_record(anchor_record)
        if positive_record is None:
            positive, positive_cache = encoded_augmentation(anchor_record, augmentation_seed)
            occlusion_steps += 1
        else:
            positive, positive_cache = encoded_record(positive_record)
            adjacent_steps += 1
        negative, negative_cache = encoded_record(negative_record)
        anchor_code = np.tanh(anchor)
        positive_code = np.tanh(positive)
        negative_code = np.tanh(negative)
        dimension = max(1, len(anchor_code))
        positive_delta = anchor_code - positive_code
        negative_delta = anchor_code - negative_code
        positive_loss = float(np.mean(positive_delta * positive_delta))
        negative_distance = float(np.mean(negative_delta * negative_delta))
        margin = 0.1
        hinge_active = negative_distance < margin
        loss_total += positive_loss + max(0.0, margin - negative_distance)
        anchor_gradient = 2.0 * positive_delta / dimension
        positive_gradient = -2.0 * positive_delta / dimension
        negative_gradient = np.zeros_like(negative_delta)
        if hinge_active:
            anchor_gradient -= 2.0 * negative_delta / dimension
            negative_gradient += 2.0 * negative_delta / dimension
        anchor_gradient *= 1.0 - anchor_code * anchor_code
        positive_gradient *= 1.0 - positive_code * positive_code
        negative_gradient *= 1.0 - negative_code * negative_code
        _backprop_perception_adapter(np, model, anchor_cache, anchor_gradient, batch_gradients)
        _backprop_perception_adapter(np, model, positive_cache, positive_gradient, batch_gradients)
        _backprop_perception_adapter(np, model, negative_cache, negative_gradient, batch_gradients)
        batch_count += 1
        trained += 1
        if batch_count >= 4:
            apply_contrastive_batch()
    apply_contrastive_batch()
    action_steps = 0
    inverse_action_steps = 0
    hud_prediction_steps = 0
    action_loss = 0.0
    inverse_action_loss = 0.0
    visual_objective_totals = {name: 0.0 for name in _runtime_module('training').VISUAL_LOSS_WEIGHTS}
    visual_objective_steps = 0
    action_limit = min(max(8, limit // 3), len(action_pairs), max(64, min(256, limit // 2)))
    frozen_target = target_model if target_model is not None else clone_target_model(np, model)
    for anchor_record, positive_record in action_pairs[:action_limit]:
        raise_if_cancelled(stop_event)
        if anchor_record.get('next_state') is None:
            continue
        try:
            current_payload = _perception_frame_input(np, last_frame(anchor_record))
            next_frames_for_loss, _, _ = decode_temporal_state(anchor_record['next_state'])
            next_payload = _perception_frame_input(np, normalize_feature_bytes(next_frames_for_loss[-1]))
            current_scene, current_tracks, current_hud = game_perception_features(np, model, current_payload, None)
            next_scene, next_tracks, next_hud = game_perception_features(np, model, next_payload, {'slots': current_tracks['slots'], 'patch_tokens': current_scene['patch_tokens'], 'histories': current_tracks.get('histories', {}), 'action_history': current_tracks.get('action_history', []), 'current_action': int(anchor_record['action'])})
            objective_losses = _runtime_module('training').visual_pretraining_losses(np, {'scene': current_scene, 'tracks': current_tracks, 'hud': current_hud}, {'scene': next_scene, 'tracks': next_tracks, 'hud': next_hud}, int(anchor_record['action']), int(anchor_record.get('previous_action', -1)))
            for objective_name in visual_objective_totals:
                raise_if_cancelled(stop_event)
                visual_objective_totals[objective_name] += float(objective_losses.get(objective_name, 0.0))
            visual_objective_steps += 1
        except Exception:
            pass
        current_hidden, current_caches = _latest_temporal_hidden(np, model, anchor_record['state'], return_cache=True)
        next_hidden, next_caches = _latest_temporal_hidden(np, model, anchor_record['next_state'], return_cache=True)
        target_next_hidden = _latest_temporal_hidden(np, frozen_target, anchor_record['next_state'])
        gradients = _training_gradient_buffer(np, model)
        transition_loss, current_hidden_gradient = train_world_model_transition(np, model, current_hidden, next_hidden, int(anchor_record['action']), (smooth_reward(float(anchor_record.get('task_reward', 0.0))), max(0.0, min(1.0, float(anchor_record.get('exploration_reward', 0.0)))), max(0.0, min(2.0, float(anchor_record.get('safety_penalty', 0.0))))), bool(anchor_record.get('done', False)), 0.25, gradients, target_model=frozen_target, target_next_hidden=target_next_hidden, duration_index=_record_duration_index(anchor_record), action_payload=anchor_record.get('action_payload'), structured_target=structured_world_target_from_state(np, model, anchor_record.get('next_state') or anchor_record.get('state')))
        transition_hidden = np.tanh(np.asarray(next_hidden, dtype=np.float32) - np.asarray(current_hidden, dtype=np.float32)).astype(np.float32)
        inverse_probabilities, _, _ = factorized_action_outputs_from_hidden(np, model, transition_hidden)
        inverse_loss, inverse_gradient = _train_factor_policy(np, model, transition_hidden, model['action_factors'][int(anchor_record['action'])], step_size, 0.08, action_id=int(anchor_record['action']), gradients=gradients, probabilities=inverse_probabilities, duration_index=_record_duration_index(anchor_record), action_payload=anchor_record.get('action_payload'))
        inverse_transition_gradient = inverse_gradient * (1.0 - transition_hidden * transition_hidden)
        current_hidden_gradient -= inverse_transition_gradient
        next_hidden_gradient = inverse_transition_gradient.copy()
        hud_prediction_steps = visual_objective_steps
        _backprop_temporal_encoder(np, model, current_caches, current_hidden_gradient, step_size, gradients)
        _backprop_temporal_encoder(np, model, next_caches, next_hidden_gradient, step_size, gradients)
        active = [gradient for gradient in gradients.values() if np.any(gradient)]
        if active:
            clip_gradients_by_global_norm(np, active, 4.0)
            for key, gradient in gradients.items():
                raise_if_cancelled(stop_event)
                model[key] -= step_size * 0.5 * gradient
            _synchronize_quantized_conv_weights(np, model)
        action_loss += transition_loss
        inverse_action_loss += inverse_loss
        action_steps += 1
        inverse_action_steps += 1
    multistep_steps = 0
    multistep_loss = 0.0
    rng.shuffle(rollout_starts)
    overshoot_limit = min(len(rollout_starts), max(8, min(128, limit // 8)))
    for part, position in rollout_starts[:overshoot_limit]:
        raise_if_cancelled(stop_event)
        anchor_record = part[position]
        start_hidden, start_caches = _latest_temporal_hidden(np, model, anchor_record['state'], return_cache=True)
        rollout = []
        expected_step = int(anchor_record['step'])
        for record in part[position:position + WORLD_MODEL_OVERSHOOT_MAX_STEPS]:
            raise_if_cancelled(stop_event)
            if int(record['step']) != expected_step:
                break
            expected_step += 1
            if bool(record.get('done', False)):
                rollout.append((record, None))
                break
            if record.get('next_state') is None:
                break
            target_next_hidden = _latest_temporal_hidden(np, frozen_target, record['next_state'])
            rollout.append((record, target_next_hidden))
        if len(rollout) < WORLD_MODEL_OVERSHOOT_MIN_STEPS:
            continue
        gradients = _training_gradient_buffer(np, model)
        rollout_loss, start_gradient = train_world_model_overshooting(np, model, start_hidden, rollout, 0.2, gradients, frozen_target)
        _backprop_temporal_encoder(np, model, start_caches, start_gradient, step_size, gradients)
        active = [gradient for gradient in gradients.values() if np.any(gradient)]
        if active:
            clip_gradients_by_global_norm(np, active, 4.0)
            for key, gradient in gradients.items():
                raise_if_cancelled(stop_event)
                model[key] -= step_size * 0.35 * gradient
            _synchronize_quantized_conv_weights(np, model)
        multistep_loss += rollout_loss
        multistep_steps += 1
    model['visual_pretraining_steps'] = int(model.get('visual_pretraining_steps', 0)) + trained
    total_steps = trained + action_steps + inverse_action_steps + multistep_steps
    averaged_objectives = {name: value / max(1, visual_objective_steps) for name, value in visual_objective_totals.items()}
    weighted_visual_loss = sum((float(_runtime_module('training').VISUAL_LOSS_WEIGHTS[name]) * float(averaged_objectives[name]) for name in averaged_objectives))
    return {'steps': float(trained), 'loss': float(weighted_visual_loss), 'total_loss': float(weighted_visual_loss), **{name: float(value) for name, value in averaged_objectives.items()}, 'action_prediction_steps': float(action_steps), 'inverse_action_steps': float(inverse_action_steps), 'multistep_prediction_steps': float(multistep_steps), 'occlusion_reconstruction_steps': float(occlusion_steps), 'adjacent_contrastive_steps': float(adjacent_steps), 'hud_prediction_steps': float(hud_prediction_steps)}

def _model_head_outputs(np, model: dict, hidden):
    policy = (hidden @ model['policy_control_w'] + model['policy_control_b'], hidden @ model['policy_key_w'] + model['policy_key_b'], hidden @ model['policy_mouse_w'] + model['policy_mouse_b'], hidden @ model['policy_button_w'] + model['policy_button_b'], hidden @ model['policy_duration_w'] + model['policy_duration_b'])
    q_twins = (np.einsum('h,tvhc->tvc', hidden, model['q_control_w']) + model['q_control_b'], np.einsum('h,tvhk->tvk', hidden, model['q_key_w']) + model['q_key_b'], np.einsum('h,tvhm->tvm', hidden, model['q_mouse_w']) + model['q_mouse_b'], np.einsum('h,tvhb->tvb', hidden, model['q_button_w']) + model['q_button_b'], np.einsum('h,tvhd->tvd', hidden, model['q_duration_w']) + model['q_duration_b'])
    q = tuple((np.minimum(values[0], values[1]) for values in q_twins))
    return (policy, q)

def critic_weight_vector(np, weights: dict | tuple[float, float, float] | None=None):
    if isinstance(weights, dict):
        values = (float(weights.get('task_reward_weight', 1.0)), float(weights.get('exploration_reward_weight', 0.18)), -float(weights.get('safety_penalty_weight', 0.7)))
    elif weights is not None:
        values = tuple((float(value) for value in weights))
    else:
        values = (1.0, 0.18, -0.7)
    if len(values) != VALUE_HEAD_COUNT or not all((math.isfinite(value) for value in values)):
        raise ValueError('critic 组合权重无效')
    return np.asarray(values, dtype=np.float32)

def combined_critic_values(np, q_values, weights: dict | tuple[float, float, float] | None=None):
    critics = np.asarray(q_values, dtype=np.float32)
    if critics.shape[0] != VALUE_HEAD_COUNT:
        raise ValueError('critic 输出尺寸无效')
    return np.tensordot(critic_weight_vector(np, weights), critics, axes=(0, 0)).astype(np.float32)

def critic_bootstrap_values(np, model: dict, hidden, weights=None, target_model: dict | None=None, target_hidden=None):
    probabilities, online_critics, _ = factorized_action_outputs_from_hidden(np, model, hidden)
    combined = combined_critic_values(np, online_critics, weights)
    action = int(np.argmax(combined + 0.05 * np.log(np.maximum(probabilities, 1e-09))))
    evaluator = target_model if target_model is not None else model
    evaluator_hidden = hidden if target_hidden is None else target_hidden
    _, target_critics, _ = factorized_action_outputs_from_hidden(np, evaluator, evaluator_hidden)
    return target_critics[:, action].astype(np.float32, copy=False)

def predict_safety_probability(np, model: dict, hidden) -> float:
    logit = np.asarray(hidden, dtype=np.float32) @ model['safety_w'] + model['safety_b']
    return float(_sigmoid(np, logit)[0])

def world_model_latent(np, model: dict, hidden):
    hidden_value = np.asarray(hidden, dtype=np.float32).reshape(-1)
    return np.tanh(np.einsum('h,mhl->ml', hidden_value, model['world_encoder_w']) + model['world_encoder_b']).astype(np.float32)

def world_stochastic_sample(np, action_id: int, duration_index: int, token: int):
    seed = (1369948382 ^ max(0, int(action_id)) * 2654435761 ^ max(0, int(duration_index)) * 2246822519 ^ max(0, int(token)) * 3266489917) & 18446744073709551615
    rng = np.random.default_rng(seed)
    return rng.standard_normal((WORLD_MODEL_MEMBERS, WORLD_STOCHASTIC_SIZE)).astype(np.float32)

def _rssm_distribution(np, parameters):
    values = np.asarray(parameters, dtype=np.float32).reshape(WORLD_MODEL_MEMBERS, 2 * WORLD_STOCHASTIC_SIZE)
    mean = np.clip(values[:, :WORLD_STOCHASTIC_SIZE], -6.0, 6.0)
    log_std = np.clip(values[:, WORLD_STOCHASTIC_SIZE:], RSSM_MIN_LOG_STD, RSSM_MAX_LOG_STD)
    std = np.exp(log_std).astype(np.float32)
    return (mean.astype(np.float32), std, log_std.astype(np.float32))

def rssm_deterministic_transition(np, model: dict, latent, action_id: int, duration_index: int, action_payload=None):
    action = max(0, min(len(model['action_embedding']) - 1, int(action_id)))
    duration = max(0, min(DURATION_HEAD_SIZE - 1, int(duration_index)))
    action_embedding = structured_action_embedding(np, model, action, action_payload)
    latent_value = np.asarray(latent, dtype=np.float32).reshape(WORLD_MODEL_MEMBERS, model_world_latent_size(model))
    return np.tanh(np.einsum('ml,mlk->mk', latent_value, model['world_dynamics_w'], optimize=True) + np.einsum('a,mak->mk', action_embedding, model['world_dynamics_action_w'], optimize=True) + np.einsum('d,mdk->mk', model['duration_embedding'][duration], model['world_dynamics_duration_w'], optimize=True) + model['world_dynamics_b']).astype(np.float32)

def rssm_prior(np, model: dict, deterministic_state, action_id: int, duration_index: int, action_payload=None):
    action = max(0, min(len(model['action_embedding']) - 1, int(action_id)))
    duration = max(0, min(DURATION_HEAD_SIZE - 1, int(duration_index)))
    action_embedding = structured_action_embedding(np, model, action, action_payload)
    deterministic = np.asarray(deterministic_state, dtype=np.float32).reshape(WORLD_MODEL_MEMBERS, model_world_latent_size(model))
    parameters = np.einsum('ml,mlz->mz', deterministic, model['world_prior_state_w'], optimize=True) + np.einsum('a,maz->mz', action_embedding, model['world_prior_action_w'], optimize=True) + np.einsum('d,mdz->mz', model['duration_embedding'][duration], model['world_prior_duration_w'], optimize=True) + model['world_prior_b']
    return _rssm_distribution(np, parameters)

def rssm_latent_from_state(np, model: dict, deterministic_state, stochastic_state):
    deterministic = np.asarray(deterministic_state, dtype=np.float32).reshape(WORLD_MODEL_MEMBERS, model_world_latent_size(model))
    stochastic = np.asarray(stochastic_state, dtype=np.float32).reshape(WORLD_MODEL_MEMBERS, WORLD_STOCHASTIC_SIZE)
    return np.tanh(deterministic + np.einsum('ms,msl->ml', stochastic, model['world_stochastic_w'], optimize=True)).astype(np.float32)

def latent_world_model_step(np, model: dict, latent, action_id: int, duration_index: int=DURATION_HEAD_SIZE // 2, stochastic_token: int | None=None, action_payload=None):
    action = max(0, min(len(model['action_embedding']) - 1, int(action_id)))
    duration = max(0, min(DURATION_HEAD_SIZE - 1, int(duration_index)))
    action_embedding = structured_action_embedding(np, model, action, action_payload)
    duration_embedding = model['duration_embedding'][duration]
    deterministic_state = rssm_deterministic_transition(np, model, latent, action, duration, action_payload)
    prior_mean, prior_std, _ = rssm_prior(np, model, deterministic_state, action, duration, action_payload)
    stochastic = prior_mean
    if stochastic_token is not None:
        stochastic = prior_mean + prior_std * world_stochastic_sample(np, action, duration, stochastic_token)
    next_latents = rssm_latent_from_state(np, model, deterministic_state, stochastic)
    member_rewards = (np.einsum('ml,mlv->mv', next_latents, model['world_reward_w']) + np.einsum('a,mav->mv', action_embedding, model['world_reward_action_w']) + np.einsum('d,mdv->mv', duration_embedding, model['world_reward_duration_w']) + model['world_reward_b']).astype(np.float32)
    member_rewards[:, TASK_CRITIC] = np.clip(member_rewards[:, TASK_CRITIC], -1.0, 1.0)
    member_rewards[:, EXPLORATION_CRITIC] = np.clip(member_rewards[:, EXPLORATION_CRITIC], 0.0, 1.0)
    member_rewards[:, SAFETY_CRITIC] = np.clip(member_rewards[:, SAFETY_CRITIC], 0.0, 2.0)
    continuation_probabilities = _sigmoid(np, np.einsum('ml,mlq->mq', next_latents, model['world_continuation_w']) + model['world_continuation_b'])[:, 0]
    return (next_latents, member_rewards.mean(axis=0).astype(np.float32), float(1.0 - continuation_probabilities.mean()))

def world_model_planning_confidence(model: dict, world_steps: int, minimum_steps: int) -> float:
    full_confidence_steps = max(minimum_steps + 1, WORLD_MODEL_FULL_CONFIDENCE_STEPS)
    step_confidence = max(0.0, min(1.0, (int(world_steps) - int(minimum_steps)) / max(1, full_confidence_steps - int(minimum_steps))))
    try:
        reward_mae = float(model.get('world_validation_reward_mae', -1.0))
        done_brier = float(model.get('world_validation_done_brier', -1.0))
        latent_error = float(model.get('world_validation_latent_error', -1.0))
        multistep_error = float(model.get('world_validation_multistep_error', -1.0))
    except (TypeError, ValueError, OverflowError):
        return 0.0
    if not all((math.isfinite(value) for value in (reward_mae, done_brier, latent_error, multistep_error))) or reward_mae < 0.0 or done_brier < 0.0 or (latent_error < 0.0) or (multistep_error < 0.0):
        return 0.0
    quality_confidence = math.exp(-2.0 * max(0.0, reward_mae) - 2.0 * max(0.0, done_brier) - 1.5 * max(0.0, latent_error) - 2.0 * max(0.0, multistep_error))
    try:
        structured_quality = 1.0 - float(_runtime_module('world_model').structured_confidence_penalty(model))
    except Exception:
        structured_quality = 0.65
    return max(0.0, min(1.0, step_confidence * quality_confidence * structured_quality))

def effective_human_memory_weight(model: dict) -> float:
    rounds = max(0, int(model.get('training_rounds', 0)))
    world_confidence = world_model_planning_confidence(model, int(model.get('world_training_steps', 0)), WORLD_MODEL_MIN_TRAINING_STEPS)
    return HUMAN_ACTION_MEMORY_WEIGHT * math.exp(-rounds / 4.0) * max(0.05, 1.0 - world_confidence)

def adaptive_human_memory_weight(model: dict, *, stuck: bool=False, high_uncertainty: bool=False, near_success_demo: bool=False, safety_risk: float=0.0) -> float:
    base = effective_human_memory_weight(model)
    multiplier = 1.0
    if int(model.get('training_rounds', 0)) <= 0:
        multiplier *= 1.8
    if stuck:
        multiplier *= 1.65
    if high_uncertainty:
        multiplier *= 1.45
    if near_success_demo:
        multiplier *= 1.35
    multiplier *= 1.0 + 0.75 * max(0.0, min(1.0, float(safety_risk)))
    return max(0.0, min(HUMAN_ACTION_MEMORY_WEIGHT, base * multiplier))

def latent_world_model_duration_values(np, model: dict, hidden, action_id: int, critic_weights: dict | tuple[float, float, float] | None=None):
    result = np.zeros(DURATION_HEAD_SIZE, dtype=np.float64)
    world_steps = max(0, int(model.get('world_training_steps', 0)))
    minimum_steps = max(WORLD_MODEL_MIN_TRAINING_STEPS, len(model['action_factors']) * 8)
    if world_steps < minimum_steps or not 0 <= int(action_id) < len(model['action_embedding']):
        return result
    action = int(action_id)
    latent = world_model_latent(np, model, hidden)
    action_embedding = model['action_embedding'][action]
    duration_embeddings = model['duration_embedding']
    next_latent_values = []
    for duration_index, duration_embedding in enumerate(duration_embeddings):
        deterministic = np.tanh(np.einsum('ml,mlk->mk', latent, model['world_dynamics_w']) + np.einsum('a,mak->mk', action_embedding, model['world_dynamics_action_w']) + np.einsum('d,mdk->mk', duration_embedding, model['world_dynamics_duration_w']) + model['world_dynamics_b']).astype(np.float32)
        prior_mean, _, _ = rssm_prior(np, model, deterministic, action, duration_index)
        next_latent_values.append(rssm_latent_from_state(np, model, deterministic, prior_mean))
    next_latents = np.stack(next_latent_values, axis=0)
    member_rewards = np.einsum('dml,mlv->dmv', next_latents, model['world_reward_w'], optimize=True) + np.einsum('a,mav->mv', action_embedding, model['world_reward_action_w'])[None, :, :] + np.einsum('da,mav->dmv', duration_embeddings, model['world_reward_duration_w'], optimize=True) + model['world_reward_b'][None, :, :]
    member_rewards[:, :, TASK_CRITIC] = np.clip(member_rewards[:, :, TASK_CRITIC], -1.0, 1.0)
    member_rewards[:, :, EXPLORATION_CRITIC] = np.clip(member_rewards[:, :, EXPLORATION_CRITIC], 0.0, 1.0)
    member_rewards[:, :, SAFETY_CRITIC] = np.clip(member_rewards[:, :, SAFETY_CRITIC], 0.0, 2.0)
    weights = critic_weight_vector(np, critic_weights)
    member_combined = np.einsum('dmv,v->dm', member_rewards, weights, optimize=True)
    uncertainty_weight = max(0.0, min(2.0, float(critic_weights.get('world_uncertainty_penalty', 0.18)))) if isinstance(critic_weights, dict) else 0.18
    continuation_probabilities = _sigmoid(np, np.einsum('dml,mlq->dmq', next_latents, model['world_continuation_w'], optimize=True) + model['world_continuation_b'][None, :, :])[:, :, 0].mean(axis=1)
    conservative = member_combined.mean(axis=1) - uncertainty_weight * member_combined.std(axis=1)
    confidence = world_model_planning_confidence(model, world_steps, minimum_steps)
    result = conservative * np.maximum(0.0, continuation_probabilities) * confidence
    return np.clip(result, -4.0, 4.0)

def adaptive_world_model_horizon(confidence: float, requested_horizon: int, hierarchical_low_level: bool=False) -> int:
    quality = max(0.0, min(1.0, float(confidence)))
    if hierarchical_low_level:
        minimum, maximum = (1, 6)
    else:
        minimum, maximum = (4, WORLD_MODEL_MAX_PLANNING_HORIZON)
    quality_target = minimum + quality * (maximum - minimum)
    requested = max(minimum, min(maximum, int(requested_horizon)))
    return max(minimum, min(maximum, int(round(0.75 * quality_target + 0.25 * requested))))

def forced_world_model_actions(profile: dict, allowed_actions: list[int], current_state_key: str, state_action_visits: dict[tuple[str, int], int], human_bias, model_disagreement, recovery_action: int | None=None, contextual_probe: int | None=None) -> list[int]:
    allowed = [int(action) for action in allowed_actions]
    allowed_set = set(allowed)
    actions = profile.get('actions', [])
    ordered: list[int] = []

    def add(action: int | None) -> None:
        if action is None:
            return
        value = int(action)
        if value in allowed_set and value not in ordered:
            ordered.append(value)
    for action in sorted(allowed, key=lambda value: (int(state_action_visits.get((current_state_key, value), 0)), value))[:4]:
        add(action)
    try:
        for action in sorted(allowed, key=lambda value: float(human_bias[value]), reverse=True)[:4]:
            add(action)
    except Exception:
        pass
    try:
        for action in sorted(allowed, key=lambda value: float(model_disagreement[value]), reverse=True)[:4]:
            add(action)
    except Exception:
        pass
    add(recovery_action)
    add(contextual_probe)
    for kind in ('keyboard', 'pointer', 'click', 'wheel', 'mixed'):
        candidates = [action for action in allowed if 0 <= action < len(actions) and action_kind(actions[action]) == kind]
        if not candidates:
            continue
        candidate = min(candidates, key=lambda value: (int(state_action_visits.get((current_state_key, value), 0)), -float(human_bias[value]) if value < len(human_bias) else 0.0, -float(model_disagreement[value]) if value < len(model_disagreement) else 0.0, value))
        add(candidate)
    return ordered

def risk_sensitive_return(np, returns, cvar_fraction: float=0.35, cvar_weight: float=0.7) -> float:
    values = np.asarray(returns, dtype=np.float64).reshape(-1)
    values = values[np.isfinite(values)]
    if values.size == 0:
        return 0.0
    fraction = max(0.1, min(0.5, float(cvar_fraction)))
    weight = max(0.0, min(1.0, float(cvar_weight)))
    ordered = np.sort(values)
    tail_count = max(1, int(math.ceil(ordered.size * fraction)))
    lower_tail = float(ordered[:tail_count].mean())
    overall_mean = float(ordered.mean())
    return weight * lower_tail + (1.0 - weight) * overall_mean

def state_relevant_actions(profile: dict, allowed_actions: list[int], current_state_key: str, state_action_visits: dict[tuple[str, int], int], human_bias, reward_guidance, effect_guidance, risk_guidance, model_disagreement, forced_actions: list[int] | tuple[int, ...]=(), recovery_action: int | None=None, contextual_probe: int | None=None, runtime_tier: str='mid_onnx', config: dict | None=None, belief=None, causal_model=None) -> list[int]:
    settings = config if isinstance(config, dict) else DEFAULT_CONFIG
    actions = profile.get('actions', [])
    allowed = []
    seen_allowed: set[int] = set()
    for raw_action in allowed_actions:
        try:
            action = int(raw_action)
        except (TypeError, ValueError, OverflowError):
            continue
        if 0 <= action < len(actions) and action not in seen_allowed:
            seen_allowed.add(action)
            allowed.append(action)
    if not allowed:
        return []
    allowed_set = set(allowed)
    tier_cap = {'low_numpy': 24, 'mid_onnx': 32, 'high_directml': 48}.get(str(runtime_tier), 32)
    try:
        configured_limit = int(settings.get('state_action_candidate_limit', 48))
    except (TypeError, ValueError, OverflowError):
        configured_limit = 48
    limit = max(8, min(len(allowed), tier_cap, configured_limit))

    def configured_int(name: str, default: int, maximum: int) -> int:
        try:
            value = int(settings.get(name, default))
        except (TypeError, ValueError, OverflowError):
            value = default
        return max(1, min(maximum, value))
    human_limit = min(configured_int('state_action_human_limit', 12, 48), max(2, limit // 4))
    effective_limit = min(configured_int('state_action_effective_limit', 12, 48), max(2, limit // 4))
    forced_limit = min(configured_int('state_action_forced_limit', 12, 32), max(2, limit // 5))
    exploration_per_kind = min(configured_int('state_action_exploration_per_kind', 2, 6), 1 if limit < 36 else 2)

    def value_at(values, action: int, default: float=0.0) -> float:
        try:
            value = float(values[action])
        except (TypeError, ValueError, OverflowError, IndexError, KeyError):
            return default
        return value if math.isfinite(value) else default
    selected: list[int] = []

    def add(action: int | None) -> None:
        if action is None or len(selected) >= limit:
            return
        try:
            value = int(action)
        except (TypeError, ValueError, OverflowError):
            return
        if value in allowed_set and value not in selected:
            selected.append(value)
    add(recovery_action)
    add(contextual_probe)
    if belief is not None and causal_model is not None:
        candidate_actions = [actions[action] for action in allowed]
        candidate_risks = [value_at(risk_guidance, action, 1.0) for action in allowed]
        try:
            probe_offset = causal_model.choose_intervention(belief, candidate_actions, candidate_risks, max(0.0, min(1.0, float(settings.get('causal_probe_max_risk', 0.35)))))
        except Exception:
            probe_offset = None
        if probe_offset is not None and 0 <= int(probe_offset) < len(allowed):
            add(allowed[int(probe_offset)])
    for action in list(forced_actions)[:forced_limit]:
        add(action)
    for kind in CONTROL_KINDS:
        candidates = [action for action in allowed if action not in selected and action_kind(actions[action]) == kind]
        candidates.sort(key=lambda action: (int(state_action_visits.get((current_state_key, action), 0)), -value_at(model_disagreement, action), value_at(risk_guidance, action), -value_at(human_bias, action), action))
        for action in candidates[:exploration_per_kind]:
            add(action)
    human_candidates = [action for action in allowed if action not in selected and value_at(human_bias, action) > 0.0001]
    human_candidates.sort(key=lambda action: (value_at(human_bias, action), -value_at(risk_guidance, action), -int(state_action_visits.get((current_state_key, action), 0))), reverse=True)
    for action in human_candidates[:human_limit]:
        add(action)
    effect_counts = profile.get('action_effect_counts', [])
    effect_values = profile.get('action_effect_ema', [])
    minimum_tests = max(1, int(settings.get('action_freeze_min_tests', 12)))
    effect_threshold = max(0.0, min(0.25, float(settings.get('action_freeze_effect_threshold', 0.006))))
    effective_candidates: list[int] = []
    for action in allowed:
        if action in selected:
            continue
        try:
            count = max(0, int(effect_counts[action]))
        except (TypeError, ValueError, OverflowError, IndexError):
            count = 0
        empirical_effect = value_at(effect_values, action)
        guided_effect = value_at(effect_guidance, action)
        verified = count >= minimum_tests and empirical_effect >= max(effect_threshold * 1.5, 0.004) or guided_effect >= 0.08
        if verified:
            effective_candidates.append(action)
    effective_candidates.sort(key=lambda action: (0.65 * value_at(effect_guidance, action) + 0.35 * max(0.0, value_at(reward_guidance, action)) - 0.5 * value_at(risk_guidance, action), value_at(human_bias, action)), reverse=True)
    for action in effective_candidates[:effective_limit]:
        add(action)
    remaining = [action for action in allowed if action not in selected]
    remaining.sort(key=lambda action: 0.7 * value_at(human_bias, action) + 0.55 * value_at(effect_guidance, action) + 0.35 * value_at(reward_guidance, action) + 0.18 * value_at(model_disagreement, action) - 0.6 * value_at(risk_guidance, action) - 0.05 * math.log1p(max(0, int(state_action_visits.get((current_state_key, action), 0)))), reverse=True)
    for action in remaining:
        add(action)
    return selected

def latent_world_model_plan_values(np, model: dict, hidden, probabilities, base_values, horizon: int, discount: float, critic_weights: dict | tuple[float, float, float] | None=None, allowed_actions: list[int] | None=None, forced_actions: list[int] | None=None, runtime_tier: str | None=None, hierarchical_low_level: bool=False, belief=None, goal=None, skill_library=None, causal_model=None):
    action_count = len(model['action_factors'])
    result = np.zeros(action_count, dtype=np.float64)
    if belief is not None and goal is not None and (skill_library is not None):
        try:
            semantic_plan = plan_with_understanding(belief, goal, skill_library, causal_model, _runtime_module('world_model'), None, max(1, min(64, len(skill_library) if hasattr(skill_library, '__len__') else 32)))
            model['_latest_understanding_plan'] = semantic_plan
            if semantic_plan is not None:
                score, semantic_skill, _ = semantic_plan
                semantic_weight = max(0.0, min(4.0, float(critic_weights.get('semantic_skill_planning_weight', 1.0)))) if isinstance(critic_weights, dict) else 1.0
                for action, _ in _runtime_module('planner').low_level_actions(semantic_skill):
                    if 0 <= action < action_count:
                        result[action] += semantic_weight * float(score)
        except Exception:
            model['_latest_understanding_plan'] = None
    world_steps = max(0, int(model.get('world_training_steps', 0)))
    minimum_steps = max(WORLD_MODEL_MIN_TRAINING_STEPS, action_count * 8)
    if world_steps < minimum_steps or horizon <= 0:
        return result
    planning_confidence = world_model_planning_confidence(model, world_steps, minimum_steps)
    if planning_confidence <= 0.0:
        return result
    root_probabilities = np.asarray(probabilities, dtype=np.float64)
    root_values = np.asarray(base_values, dtype=np.float64)
    if root_probabilities.shape != (action_count,) or root_values.shape != (action_count,) or (not np.isfinite(root_probabilities).all()) or (not np.isfinite(root_values).all()):
        return result
    allowed = [int(action) for action in (allowed_actions if allowed_actions is not None else range(action_count)) if 0 <= int(action) < action_count]
    if not allowed:
        return result
    gamma = max(0.1, min(0.98, float(discount)))
    beam_width, branch_factor, horizon_cap = world_planning_budget(str(runtime_tier or model.get('runtime_tier', 'mid_onnx')))
    horizon_value = min(horizon_cap, adaptive_world_model_horizon(planning_confidence, int(horizon), hierarchical_low_level))
    weights = critic_weight_vector(np, critic_weights)
    uncertainty_weight = max(0.0, min(2.0, float(critic_weights.get('world_uncertainty_penalty', 0.18)))) if isinstance(critic_weights, dict) else 0.18

    def projected_hidden(latents):
        member_hidden = np.tanh(np.einsum('ml,mlh->mh', np.asarray(latents, dtype=np.float32), model['world_latent_to_hidden_w'], optimize=True) + model['world_latent_to_hidden_b'])
        return member_hidden.mean(axis=0).astype(np.float32, copy=False)

    def candidate_actions(state_hidden, state_probabilities=None, state_values=None, limit=branch_factor):
        if state_probabilities is None or state_values is None:
            state_probabilities, state_q, _ = factorized_action_outputs_from_hidden(np, model, state_hidden)
            state_values = combined_critic_values(np, state_q, critic_weights)
        state_probabilities = np.asarray(state_probabilities, dtype=np.float64)
        state_values = np.asarray(state_values, dtype=np.float64)
        allowed_values = state_values[np.asarray(allowed, dtype=np.int64)]
        center = float(np.median(allowed_values))
        scale = max(0.25, float(np.std(allowed_values)))
        ranked = sorted(allowed, key=lambda action: math.log(max(1e-09, float(state_probabilities[action]))) + 0.65 * math.tanh((float(state_values[action]) - center) / scale), reverse=True)
        return ranked[:min(len(ranked), max(1, int(limit)))]
    transition_cache: dict[tuple[bytes, int, int], tuple] = {}

    def predict_transition(latents, action: int, duration: int):
        quantized_latent = np.clip(np.rint(np.asarray(latents, dtype=np.float32) * 64.0), -127, 127).astype(np.int8)
        digest = hashlib.blake2s(quantized_latent.tobytes(), digest_size=8).digest()
        cache_key = (digest, int(action), int(duration))
        cached = transition_cache.get(cache_key)
        if cached is not None:
            return cached
        action_embedding = model['action_embedding'][action]
        duration_embedding = model['duration_embedding'][duration]
        deterministic = rssm_deterministic_transition(np, model, latents, action, duration)
        prior_mean, prior_std, _ = rssm_prior(np, model, deterministic, action, duration)
        epsilon = world_stochastic_sample(np, action, duration, int.from_bytes(digest[:4], 'little'))
        next_latents = rssm_latent_from_state(np, model, deterministic, prior_mean + prior_std * epsilon)
        member_rewards = (np.einsum('ml,mlv->mv', next_latents, model['world_reward_w'], optimize=True) + np.einsum('a,mav->mv', action_embedding, model['world_reward_action_w'], optimize=True) + np.einsum('d,mdv->mv', duration_embedding, model['world_reward_duration_w'], optimize=True) + model['world_reward_b']).astype(np.float32)
        member_rewards[:, TASK_CRITIC] = np.clip(member_rewards[:, TASK_CRITIC], -1.0, 1.0)
        member_rewards[:, EXPLORATION_CRITIC] = np.clip(member_rewards[:, EXPLORATION_CRITIC], 0.0, 1.0)
        member_rewards[:, SAFETY_CRITIC] = np.clip(member_rewards[:, SAFETY_CRITIC], 0.0, 2.0)
        try:
            structured_adjustment, structured_diagnostics = _runtime_module('world_model').structured_planning_adjustment(np, model, next_latents, latents)
            member_rewards[:, TASK_CRITIC] += np.asarray(structured_adjustment, dtype=np.float32)
        except Exception:
            structured_diagnostics = {}
        continuation_probability = float(_sigmoid(np, np.einsum('ml,mlq->mq', next_latents, model['world_continuation_w'], optimize=True) + model['world_continuation_b'])[:, 0].mean())
        done_probability = 1.0 - continuation_probability
        member_combined = member_rewards @ weights
        latent_disagreement = float(np.mean(np.std(next_latents, axis=0)))
        branch_uncertainty = float(member_combined.std()) + latent_disagreement
        answer = (next_latents, member_combined, done_probability, branch_uncertainty)
        transition_cache[cache_key] = answer
        return answer
    initial_latents = world_model_latent(np, model, hidden)
    root_candidates = candidate_actions(np.asarray(hidden, dtype=np.float32), root_probabilities, root_values, max(beam_width, branch_factor * 2))
    for action in forced_actions or ():
        action = int(action)
        if action in allowed and action not in root_candidates:
            root_candidates.append(action)
    cvar_fraction = max(0.1, min(0.5, float(critic_weights.get('planning_cvar_fraction', 0.35)))) if isinstance(critic_weights, dict) else 0.35
    cvar_weight = max(0.0, min(1.0, float(critic_weights.get('planning_cvar_weight', 0.7)))) if isinstance(critic_weights, dict) else 0.7
    beams = [(0.0, 1.0, -1, initial_latents, np.zeros(WORLD_MODEL_MEMBERS, dtype=np.float64))]
    returns_by_initial: dict[int, list[float]] = {action: [] for action in root_candidates}
    completed_depth = 0
    for depth in range(horizon_value):
        expanded = []
        for _, beam_survival, first_action, beam_latents, beam_member_returns in beams:
            state_hidden = np.asarray(hidden, dtype=np.float32) if depth == 0 else projected_hidden(beam_latents)
            actions = root_candidates if depth == 0 else candidate_actions(state_hidden, limit=branch_factor)
            for action in actions:
                kind = int(model['action_factors'][action, 0])
                duration_probabilities, duration_q = conditional_duration_outputs(np, model, state_hidden, kind)
                duration_scores = np.log(np.maximum(duration_probabilities, 1e-09)) + 0.25 * combined_critic_values(np, duration_q, critic_weights) + 0.3 * latent_world_model_duration_values(np, model, state_hidden, action, critic_weights)
                durations = [int(value) for value in np.argsort(duration_scores)[::-1][:2]]
                for duration in durations:
                    next_latents, member_combined, done_probability, branch_uncertainty = predict_transition(beam_latents, action, duration)
                    new_initial = action if first_action < 0 else first_action
                    uncertainty_adjustment = 0.35 * uncertainty_weight * branch_uncertainty
                    adjusted_member_rewards = np.asarray(member_combined, dtype=np.float64) - uncertainty_adjustment
                    new_member_returns = beam_member_returns + gamma ** depth * beam_survival * adjusted_member_rewards
                    new_risk_score = risk_sensitive_return(np, new_member_returns, cvar_fraction, cvar_weight)
                    new_survival = beam_survival * max(0.0, 1.0 - done_probability)
                    uncertainty_limit = 0.55 + 0.65 * planning_confidence
                    if branch_uncertainty <= uncertainty_limit and new_survival >= 0.02:
                        expanded.append((new_risk_score, new_survival, new_initial, next_latents, new_member_returns))
                    else:
                        returns_by_initial.setdefault(new_initial, []).append(new_risk_score)
        if not expanded:
            break
        expanded.sort(key=lambda item: item[0], reverse=True)
        for pruned in expanded[beam_width:]:
            returns_by_initial.setdefault(pruned[2], []).append(float(pruned[0]))
        beams = expanded[:beam_width]
        completed_depth = depth + 1
        if max((item[1] for item in beams)) < 0.02:
            break
    for _, beam_survival, first_action, beam_latents, member_returns in beams:
        if first_action < 0:
            continue
        leaf_hidden = projected_hidden(beam_latents)
        terminal_value = float(leaf_hidden @ model['value_w'][:, 0] + model['value_b'][0])
        terminal_member_returns = member_returns + gamma ** max(1, completed_depth) * beam_survival * terminal_value
        terminal_score = risk_sensitive_return(np, terminal_member_returns, cvar_fraction, cvar_weight)
        returns_by_initial.setdefault(first_action, []).append(terminal_score)
    for action, imagined_returns in returns_by_initial.items():
        if imagined_returns:
            result[action] = risk_sensitive_return(np, imagined_returns, cvar_fraction, cvar_weight)
    return np.clip(result * planning_confidence, -4.0, 4.0)

def recurrent_ensemble_outputs(np, model: dict, target_model: dict, online_hidden, target_hidden, target_weight: float, critic_weights=None):
    online_probability, online_q, _ = factorized_action_outputs_from_hidden(np, model, online_hidden)
    target_probability, target_q, _ = factorized_action_outputs_from_hidden(np, target_model, target_hidden)
    weight = max(0.0, min(0.5, float(target_weight)))
    probabilities = online_probability * (1.0 - weight) + target_probability * weight
    probabilities /= max(1e-12, float(probabilities.sum()))
    online_values = combined_critic_values(np, online_q, critic_weights)
    target_values = combined_critic_values(np, target_q, critic_weights)
    values = online_values * (1.0 - weight) + target_values * weight
    disagreement = np.abs(online_values - target_values)
    uncertainty = disagreement * (0.5 + weight)
    return (probabilities.astype(np.float32), np.clip(values, -4.0, 4.0), np.clip(uncertainty, 0.0, 4.0), np.clip(disagreement, 0.0, 4.0))

def clone_target_model(np, model: dict) -> dict:
    clone = {}
    for key, value in model.items():
        clone[key] = value.copy() if isinstance(value, np.ndarray) else list(value) if isinstance(value, list) else value
    return clone

def soft_update_target_model(np, target: dict, source: dict, rate: float) -> None:
    tau = max(0.0, min(1.0, float(rate)))
    for key, source_value in source.items():
        if key.startswith('optimizer_'):
            continue
        target_value = target.get(key)
        if isinstance(source_value, np.ndarray) and isinstance(target_value, np.ndarray) and (source_value.shape == target_value.shape):
            if np.issubdtype(source_value.dtype, np.floating):
                target_value *= 1.0 - tau
                target_value += source_value * tau
            else:
                target[key] = source_value.copy()
        elif key in ('trained_samples', 'training_rounds', 'online_updates', 'visual_pretraining_steps', 'world_training_steps', 'reward_model_training_steps', 'action_hash', 'action_signatures', 'critic_names', 'q_twin_count', 'world_model_members', 'world_latent_size', 'runtime_tier', 'validation_score', 'world_validation_reward_mae', 'world_validation_done_brier', 'world_validation_latent_error', 'world_validation_multistep_error'):
            target[key] = list(source_value) if isinstance(source_value, list) else source_value
    for cache_key in ('_vision_onnx_export', '_temporal_onnx_export', '_accelerated_policy_cache'):
        target.pop(cache_key, None)

def online_update_reliability(persistence: float, flicker: float, fade_score: float, global_shift: float, next_black: bool) -> float:
    persistence_value = max(0.0, min(1.0, float(persistence)))
    flicker_value = max(0.0, min(1.0, float(flicker)))
    fade_value = max(0.0, min(1.0, float(fade_score)))
    shift_value = max(0.0, min(1.0, float(global_shift)))
    stability = 0.2 + 0.8 * persistence_value
    stability *= 1.0 - 0.82 * flicker_value
    stability *= 1.0 - 0.52 * fade_value
    stability *= 1.0 - 0.36 * shift_value
    if next_black:
        stability *= 0.45
    return max(0.05, min(1.0, stability))

def _latest_temporal_hidden(np, model: dict, state: bytes, return_cache: bool=False):
    frames, actions, durations, valid_length = decode_temporal_state_with_length(state)
    start = len(frames) - valid_length
    vector = {'frames': [_perception_frame_input(np, frame) for frame in frames[start:]], 'actions': np.asarray(actions[start:], dtype=np.int32), 'durations': np.asarray(durations[start:], dtype=np.float32)}
    previous_tracks = model.pop('_perception_tracks', None)
    previous_latest = model.pop('_latest_perception', None)
    try:
        return _model_hidden_state_from_vector(np, model, vector, return_cache=return_cache)
    finally:
        model.pop('_perception_tracks', None)
        model.pop('_latest_perception', None)
        if previous_tracks is not None:
            model['_perception_tracks'] = previous_tracks
        if previous_latest is not None:
            model['_latest_perception'] = previous_latest

def temporal_critic_targets(np, model: dict, rewards, next_feature: bytes | None=None, discount: float=0.0, terminal: bool=False, target_model: dict | None=None, critic_weights=None, online_next_hidden=None, target_next_hidden=None):
    immediate = np.asarray(rewards, dtype=np.float32).reshape(-1)
    if immediate.size == 1:
        scalar = float(immediate[0])
        immediate = np.asarray((scalar, max(0.0, scalar), max(0.0, -scalar)), dtype=np.float32)
    if immediate.shape != (VALUE_HEAD_COUNT,) or not np.isfinite(immediate).all():
        raise ValueError('在线 critic 回报无效')
    immediate[TASK_CRITIC] = np.clip(immediate[TASK_CRITIC], -3.0, 3.0)
    immediate[EXPLORATION_CRITIC] = np.clip(immediate[EXPLORATION_CRITIC], 0.0, 3.0)
    immediate[SAFETY_CRITIC] = np.clip(immediate[SAFETY_CRITIC], 0.0, 4.0)
    if terminal or next_feature is None:
        return immediate
    evaluator = target_model if target_model is not None else model
    online_hidden = _latest_temporal_hidden(np, model, next_feature) if online_next_hidden is None else np.asarray(online_next_hidden, dtype=np.float32)
    evaluator_hidden = _latest_temporal_hidden(np, evaluator, next_feature) if target_next_hidden is None else np.asarray(target_next_hidden, dtype=np.float32)
    if online_hidden.shape != (int(model['hidden_size']),):
        raise ValueError('在线回放隐藏状态尺寸无效')
    if evaluator_hidden.shape != (int(evaluator['hidden_size']),):
        raise ValueError('目标回放隐藏状态尺寸无效')
    result = immediate + max(0.0, min(0.99, float(discount))) * critic_bootstrap_values(np, model, online_hidden, critic_weights, evaluator, evaluator_hidden)
    result[TASK_CRITIC] = np.clip(result[TASK_CRITIC], -3.0, 3.0)
    result[EXPLORATION_CRITIC] = np.clip(result[EXPLORATION_CRITIC], 0.0, 3.0)
    result[SAFETY_CRITIC] = np.clip(result[SAFETY_CRITIC], 0.0, 4.0)
    return result.astype(np.float32)

def reconcile_online_world_plans(np, online_plan, world_plan, online_confidence: float, world_confidence: float, disagreement_penalty: float):
    online = np.asarray(online_plan, dtype=np.float64)
    world = np.asarray(world_plan, dtype=np.float64)
    if online.shape != world.shape:
        raise ValueError('联合规划尺寸无效')
    online_scale = max(0.0, min(1.0, float(online_confidence)))
    world_scale = max(0.0, min(1.0, float(world_confidence)))
    total_scale = online_scale + world_scale
    if total_scale <= 1e-09:
        return (np.zeros_like(online), np.zeros_like(online))
    combined = (online_scale * online + world_scale * world) / total_scale
    disagreement = np.abs(online - world)
    penalty = max(0.0, min(2.0, float(disagreement_penalty)))
    confidence_overlap = min(online_scale, world_scale)
    combined -= penalty * confidence_overlap * disagreement
    return (np.clip(combined, -4.0, 4.0), disagreement)

def online_model_update(np, model: dict, feature: bytes, action_index: int, reward: float, learning_rate: float, next_feature: bytes | None=None, discount: float=0.0, terminal: bool=False, target_model: dict | None=None, critic_rewards=None, critic_weights=None, world_rewards=None, world_next_feature: bytes | None=None, world_terminal: bool | None=None, duration_index: int | None=None, action_payload: object | None=None, hidden_state=None, target_hidden_state=None, next_hidden_state=None, target_next_hidden_state=None) -> bool:
    if not 0 <= int(action_index) < len(model['action_factors']):
        return False
    lr = max(0.0, min(0.02, float(learning_rate)))
    if lr <= 0.0:
        return False
    hidden = _latest_temporal_hidden(np, model, feature) if hidden_state is None else np.asarray(hidden_state, dtype=np.float32)
    if hidden.shape != (int(model['hidden_size']),) or not np.isfinite(hidden).all():
        return False
    adapted_hidden, adapter_cache = online_adapter_hidden(np, model, hidden, return_cache=True)
    probabilities, q_values, _ = factorized_action_outputs_from_hidden(np, model, hidden)
    value = float(adapted_hidden @ model['value_w'][:, 0] + model['value_b'][0])
    reward_components = critic_rewards if critic_rewards is not None else (reward, max(0.0, reward), max(0.0, -reward))
    targets = temporal_critic_targets(np, model, reward_components, next_feature, discount, terminal, target_model, critic_weights, next_hidden_state, target_next_hidden_state)
    del target_hidden_state
    executed_duration = DURATION_HEAD_SIZE // 2
    if duration_index is not None:
        executed_duration = max(0, min(DURATION_HEAD_SIZE - 1, int(duration_index)))
    else:
        try:
            duration_state = world_next_feature or next_feature or feature
            _, _, duration_values = decode_temporal_state(duration_state)
            executed_duration = duration_bin(float(duration_values[-1]))
        except Exception:
            pass
    q_data = float(combined_critic_values(np, q_values[:, int(action_index), None], critic_weights)[0])
    gradients = _training_gradient_buffer(np, model)
    _, value_hidden_gradient = _train_value_head(np, model, adapted_hidden, q_data, value, 0.7, 1.0, gradients)
    _, q_hidden_gradient = _train_factor_q(np, model, adapted_hidden, int(action_index), targets, lr, 1.0, gradients=gradients, q_values=q_values, cql_weight=0.005, duration_index=executed_duration, action_payload=action_payload, hidden_is_adapted=True)
    del world_rewards, world_next_feature, world_terminal
    advantage = q_data - value
    policy_hidden_gradient = np.zeros_like(hidden)
    if advantage > -0.25:
        actor_weight = min(12.0, math.exp(min(3.0, advantage / 2.5)))
        _, policy_hidden_gradient = _train_factor_policy(np, model, adapted_hidden, model['action_factors'][int(action_index)], lr, 0.15 * actor_weight, action_id=int(action_index), gradients=gradients, probabilities=probabilities, duration_index=executed_duration, action_payload=action_payload)
    hidden_gradient = value_hidden_gradient + q_hidden_gradient + policy_hidden_gradient
    adapter_input, adapter_residual = adapter_cache
    adapter_gradient = np.asarray(hidden_gradient, dtype=np.float32) * ONLINE_ADAPTER_SCALE * (1.0 - adapter_residual * adapter_residual)
    gradients['online_adapter_w'] += adapter_input * adapter_gradient
    gradients['online_adapter_b'] += adapter_gradient
    for key, gradient in gradients.items():
        if key not in ONLINE_TRAINABLE_KEYS:
            gradient.fill(0.0)
    active_gradients = [gradients[key] for key in ONLINE_TRAINABLE_KEYS if np.any(gradients[key])]
    if not active_gradients:
        return False
    clip_gradients_by_global_norm(np, active_gradients, 3.5)
    _adam_apply(np, model, gradients, lr)
    model['online_updates'] = int(model.get('online_updates', 0)) + 1
    return True

def calibrated_policy_confidence(np, probabilities, values) -> float:
    probabilities = np.asarray(probabilities, dtype=np.float64)
    values = np.asarray(values, dtype=np.float64)
    action_count = len(probabilities)
    if action_count <= 1:
        return 1.0
    if values.shape != probabilities.shape or not np.isfinite(probabilities).all() or (not np.isfinite(values).all()):
        return 0.0
    probability_total = float(probabilities.sum())
    if probability_total <= 1e-12:
        return 0.0
    probabilities = np.maximum(probabilities / probability_total, 1e-12)
    probabilities /= float(probabilities.sum())
    entropy = float(-(probabilities * np.log(probabilities)).sum())
    entropy_confidence = max(0.0, min(1.0, 1.0 - entropy / math.log(action_count)))
    ordered = np.sort(probabilities)
    probability_margin = float(ordered[-1] - ordered[-2]) if action_count > 1 else 1.0
    policy_action = int(np.argmax(probabilities))
    value_action = int(np.argmax(values))
    value_spread = float(values.max() - values.min())
    value_margin = 0.0
    if value_spread > 1e-08:
        ordered_values = np.sort(values)
        value_margin = max(0.0, min(1.0, float(ordered_values[-1] - ordered_values[-2]) / value_spread))
    agreement = 1.0 if policy_action == value_action else 0.0
    confidence = entropy_confidence * 0.52 + max(0.0, min(1.0, probability_margin * 2.5)) * 0.2 + value_margin * 0.12 + agreement * 0.16
    return max(0.0, min(1.0, confidence))

def signed_policy_objective(np, probabilities, labels, signed_weights, with_gradient: bool=False):
    probabilities = np.asarray(probabilities)
    labels = np.asarray(labels, dtype=np.int64)
    signed_weights = np.asarray(signed_weights, dtype=np.float64)
    if probabilities.ndim != 2 or len(labels) != len(probabilities) or len(signed_weights) != len(probabilities):
        raise ValueError('策略训练批次尺寸无效')
    row_count, action_count = probabilities.shape
    if row_count == 0 or action_count <= 0 or np.any(labels < 0) or np.any(labels >= action_count):
        raise ValueError('策略训练标签无效')
    rows = np.arange(row_count)
    chosen = np.clip(probabilities[rows, labels], 1e-08, 1.0 - 1e-08)
    positive_weights = np.maximum(signed_weights, 0.0)
    avoidance_weights = np.maximum(-signed_weights, 0.0)
    positive_total = float(positive_weights.sum())
    avoidance_total = float(avoidance_weights.sum())
    loss = 0.0
    gradient = np.zeros_like(probabilities) if with_gradient else None
    if positive_total > 1e-08:
        label_smoothing = 0.015 if action_count > 1 else 0.0
        if label_smoothing:
            log_probabilities = np.log(np.clip(probabilities, 1e-08, 1.0))
            positive_losses = -(1.0 - label_smoothing) * np.log(chosen) - label_smoothing * log_probabilities.mean(axis=1)
        else:
            positive_losses = -np.log(chosen)
        loss += float((positive_losses * positive_weights).sum() / positive_total)
        if with_gradient:
            positive_gradient = probabilities.copy()
            if label_smoothing:
                positive_gradient -= label_smoothing / action_count
                positive_gradient[rows, labels] -= 1.0 - label_smoothing
            else:
                positive_gradient[rows, labels] -= 1.0
            positive_gradient *= (positive_weights / positive_total)[:, None]
            gradient += positive_gradient
    if avoidance_total > 1e-08 and action_count > 1:
        avoidance_loss = float((-np.log1p(-chosen) * avoidance_weights).sum() / avoidance_total)
        loss += POLICY_AVOIDANCE_WEIGHT * avoidance_loss
        if with_gradient:
            factor = chosen / np.maximum(1e-08, 1.0 - chosen)
            avoidance_gradient = -probabilities * factor[:, None]
            avoidance_gradient[rows, labels] += factor
            avoidance_gradient *= (avoidance_weights / avoidance_total)[:, None]
            gradient += POLICY_AVOIDANCE_WEIGHT * avoidance_gradient
    return (loss, gradient)

def temporal_policy_blend(np, probabilities, values, previous_probabilities, previous_values, scene_motion: float, static_streak: int):
    current_probabilities = np.asarray(probabilities, dtype=np.float64)
    current_values = np.asarray(values, dtype=np.float64)
    if previous_probabilities is None or previous_values is None or len(previous_probabilities) != len(current_probabilities) or (len(previous_values) != len(current_values)):
        normalized = current_probabilities.copy()
        normalized /= max(1e-12, float(normalized.sum()))
        return (normalized, current_values.copy(), 0.0)
    previous_probabilities = np.asarray(previous_probabilities, dtype=np.float64)
    previous_values = np.asarray(previous_values, dtype=np.float64)
    drift = 0.5 * float(np.abs(current_probabilities - previous_probabilities).sum())
    abrupt_transition = scene_motion >= 0.11 or drift >= 0.58
    if abrupt_transition:
        current_weight = 1.0
    else:
        motion_weight = min(0.34, max(0.0, scene_motion) * 4.5)
        drift_weight = min(0.24, drift * 0.55)
        recovery_weight = min(0.16, max(0, int(static_streak) - 2) * 0.025)
        current_weight = min(0.92, 0.48 + motion_weight + drift_weight + recovery_weight)
    blended_probabilities = current_weight * current_probabilities + (1.0 - current_weight) * previous_probabilities
    blended_probabilities /= max(1e-12, float(blended_probabilities.sum()))
    blended_values = current_weight * current_values + (1.0 - current_weight) * previous_values
    return (blended_probabilities, blended_values, drift)

def adaptive_exploration_rate(base_exploration: float, confidence: float, state_familiarity: float, policy_drift: float, recent_reward: float, reward_observations: int) -> float:

    def finite_unit(value: float, default: float=0.0) -> float:
        try:
            result = float(value)
        except (TypeError, ValueError, OverflowError):
            result = default
        if not math.isfinite(result):
            result = default
        return max(0.0, min(1.0, result))
    base = finite_unit(base_exploration)
    confidence_value = finite_unit(confidence)
    familiarity = finite_unit(state_familiarity)
    drift = finite_unit(policy_drift)
    try:
        reward_value = float(recent_reward)
    except (TypeError, ValueError, OverflowError):
        reward_value = 0.0
    if not math.isfinite(reward_value):
        reward_value = 0.0
    reward_value = max(-1.0, min(1.0, reward_value))
    try:
        observation_count = max(0, int(reward_observations))
    except (TypeError, ValueError, OverflowError):
        observation_count = 0
    reward_confidence = min(1.0, observation_count / 8.0)
    reward_pressure = max(-0.04, min(0.12, (0.1 - reward_value) * 0.2))
    rate = base + (1.0 - confidence_value) * 0.14 - confidence_value * 0.025 + (0.5 - familiarity) * 0.06 + min(0.08, drift * 0.12) + reward_pressure * reward_confidence
    return max(0.0, min(0.75, rate))

def choose_policy_action(np, probabilities, values, exploration: float, allowed_actions: list[int] | None=None, uncertainty=None, planning_values=None, uncertainty_weight: float=0.22, planning_weight: float=0.55) -> int:
    probabilities = np.asarray(probabilities, dtype=np.float64)
    values = np.asarray(values, dtype=np.float64)
    candidates = np.arange(len(probabilities), dtype=np.int64) if allowed_actions is None else np.asarray(allowed_actions, dtype=np.int64)
    candidates = candidates[(candidates >= 0) & (candidates < len(probabilities))]
    if len(candidates) == 0:
        return 0
    if random.random() < max(0.0, min(0.8, float(exploration))):
        policy_weights = np.maximum(probabilities[candidates], 0.0)
        policy_total = float(policy_weights.sum())
        if policy_total > 1e-12:
            policy_weights /= policy_total
        else:
            policy_weights.fill(1.0 / len(candidates))
        weights = 0.55 * policy_weights + 0.2 / len(candidates)
        if uncertainty is not None:
            information = np.asarray(uncertainty, dtype=np.float64)[candidates]
            information = np.nan_to_num(information, nan=0.0, posinf=0.0, neginf=0.0)
            information = np.maximum(information, 0.0)
            information_total = float(information.sum())
            if information_total > 1e-12:
                weights += 0.2 * information / information_total
        if planning_values is not None:
            planned = np.asarray(planning_values, dtype=np.float64)[candidates]
            planned = np.nan_to_num(planned, nan=0.0, posinf=0.0, neginf=0.0)
            planned = np.maximum(planned - float(planned.min(initial=0.0)), 0.0)
            planned_total = float(planned.sum())
            if planned_total > 1e-12:
                weights += 0.05 * planned / planned_total
        weights = np.maximum(weights, 1e-12)
        weights /= float(weights.sum())
        return int(np.random.choice(candidates, p=weights))
    scores = np.log(np.maximum(probabilities[candidates], 1e-09)) + 0.85 * values[candidates]
    if planning_values is not None:
        scores += max(0.0, min(1.0, float(planning_weight))) * np.asarray(planning_values, dtype=np.float64)[candidates]
    if uncertainty is not None:
        scores -= max(0.0, min(0.5, float(uncertainty_weight))) * np.asarray(uncertainty, dtype=np.float64)[candidates]
    return int(candidates[int(np.argmax(scores))])

def human_training_signal(reward: float, explicit_failure: bool=False, episode_quality: float=0.5) -> tuple[float, float, float]:
    value = max(-1.0, min(1.0, float(reward)))
    quality = max(0.0, min(1.0, float(episode_quality)))
    if explicit_failure:
        return (0.1 + 0.2 * quality, value, 0.25 + 0.3 * quality)
    return (0.15 + 0.85 * quality, value, 0.3 + 0.7 * quality)

def human_record_has_explicit_failure(record: dict) -> bool:
    if bool(record.get('explicit_human_failure', False)):
        return True
    outcome_type = int(record.get('outcome_type', OUTCOME_NONE))
    confidence = max(0.0, min(1.0, float(record.get('outcome_confidence', 0.0))))
    if outcome_type == OUTCOME_DEATH and confidence >= 0.5:
        return True
    return outcome_type == OUTCOME_SCORE and confidence >= 0.6 and (float(record.get('score_delta', 0.0)) < 0.0)

def explicit_outcome_event(record: dict) -> float:
    outcome_type = int(record.get('outcome_type', OUTCOME_NONE))
    confidence = max(0.0, min(1.0, float(record.get('outcome_confidence', 0.0))))
    if outcome_type == OUTCOME_VICTORY:
        return 1.0 * confidence
    if outcome_type == OUTCOME_LEVEL:
        return 0.7 * confidence
    if outcome_type == OUTCOME_DEATH:
        return -1.0 * confidence
    if outcome_type == OUTCOME_SCORE:
        delta = float(record.get('score_delta', 0.0))
        return math.tanh(delta / 3.0) * confidence
    return 0.0

def apply_outcome_credit(records: list[dict], gamma: float=0.985) -> None:
    future_outcome = 0.0
    discount = max(0.0, min(1.0, float(gamma)))
    for record in reversed(records):
        event = explicit_outcome_event(record)
        future_outcome = event + discount * future_outcome
        future_outcome = max(-1.0, min(1.0, future_outcome))
        old_task = float(record.get('task_reward', 0.0))
        if abs(future_outcome) > 1e-06:
            record['task_reward'] = max(-4.0, min(4.0, 0.3 * old_task + 0.7 * future_outcome))

def empirical_action_guidance(np, reward_values, reward_counts, effect_values, effect_counts, risk_values, risk_counts, cold_start: bool):
    arrays = [np.asarray(reward_values, dtype=np.float64), np.asarray(reward_counts, dtype=np.float64), np.asarray(effect_values, dtype=np.float64), np.asarray(effect_counts, dtype=np.float64), np.asarray(risk_values, dtype=np.float64), np.asarray(risk_counts, dtype=np.float64)]
    if not arrays or any((value.shape != arrays[0].shape for value in arrays)):
        size = len(arrays[0]) if arrays else 0
        zero = np.zeros(size, dtype=np.float64)
        return (zero, zero.copy(), zero.copy(), zero.copy())
    if any((not np.isfinite(value).all() for value in arrays)):
        size = len(arrays[0])
        zero = np.zeros(size, dtype=np.float64)
        return (zero, zero.copy(), zero.copy(), zero.copy())
    reward_values, reward_counts, effect_values, effect_counts, risk_values, risk_counts = arrays
    reward_counts = np.maximum(0.0, reward_counts)
    effect_counts = np.maximum(0.0, effect_counts)
    risk_counts = np.maximum(0.0, risk_counts)
    reward_confidence = np.minimum(1.0, np.log1p(reward_counts) / math.log(33.0))
    effect_confidence = np.minimum(1.0, np.log1p(effect_counts) / math.log(25.0))
    risk_confidence = np.minimum(1.0, np.log1p(risk_counts) / math.log(25.0))
    reward_guidance = np.clip(reward_values, -1.0, 1.0) * reward_confidence
    effect_guidance = np.clip(effect_values, 0.0, 1.0) * effect_confidence
    risk_guidance = np.clip(risk_values, 0.0, 1.0) * risk_confidence
    uncertainty_scale = 0.09 if cold_start else 0.14
    uncertainty_bonus = uncertainty_scale * (1.0 - reward_confidence) / np.sqrt(reward_counts + 1.0)
    if len(uncertainty_bonus):
        uncertainty_bonus[0] = 0.0
    return (reward_guidance, effect_guidance, risk_guidance, uncertainty_bonus)

def _continuous_trajectory_parts(records: list[dict]) -> list[list[dict]]:
    episodes: dict[tuple[str, str, str], list[dict]] = {}
    for record in records:
        run_id = str(record.get('run_id', record['episode_id']))
        episode_id = str(record['episode_id'])
        sequence_id = str(record.get('_sequence_id', episode_id))
        episodes.setdefault((run_id, episode_id, sequence_id), []).append(record)
    parts: list[list[dict]] = []
    for episode in episodes.values():
        episode.sort(key=lambda item: int(item['step']))
        part: list[dict] = []
        for record in episode:
            if part and int(record['step']) != int(part[-1]['step']) + 1:
                parts.append(part)
                part = []
            part.append(record)
        if part:
            parts.append(part)
    return parts

def _success_rate_bucket(value: float) -> str:
    score = max(0.0, min(1.0, float(value)))
    if score >= 0.72:
        return 'high'
    if score >= 0.42:
        return 'medium'
    return 'low'

def _novelty_bucket(value: float) -> str:
    score = max(0.0, min(1.0, float(value)))
    if score >= 0.68:
        return 'high'
    if score >= 0.34:
        return 'medium'
    return 'low'

def _classify_failure_type(done: bool, task_total: float, safety_total: float, reward_mean: float, exploration_mean: float) -> str:
    if bool(done) and safety_total > max(0.35, abs(task_total) * 0.65):
        return 'terminal_safety'
    if bool(done) and (task_total < -0.1 or reward_mean < -0.03):
        return 'terminal_regression'
    if safety_total > max(0.5, abs(task_total)):
        return 'unsafe'
    if reward_mean < -0.08 or task_total < -0.2:
        return 'negative_reward'
    if exploration_mean < 0.012 and abs(task_total) < 0.08:
        return 'stagnation'
    return 'none'

def _bounded_episode_success_rate(task_total: float, exploration_total: float, safety_total: float, reward_mean: float, done: bool, failure_type: str, step_count: int) -> float:
    scale = max(1.0, math.sqrt(max(1, int(step_count))))
    score = 0.5 + 0.32 * math.tanh(float(task_total) / scale * 2.0) + 0.1 * math.tanh(float(exploration_total) / scale) + 0.12 * math.tanh(float(reward_mean) * 3.0) - 0.38 * math.tanh(float(safety_total) / scale)
    if bool(done) and failure_type == 'none' and (task_total > 0.0):
        score += 0.12
    elif failure_type != 'none':
        score -= 0.12
    return max(0.0, min(1.0, score))

def _episode_novelty_score(records: list[dict]) -> float:
    if not records:
        return 0.0
    sample_limit = min(64, len(records))
    stride = max(1, len(records) // sample_limit)
    hashes: set[str] = set()
    sampled = 0
    for record in records[::stride][:sample_limit]:
        try:
            hashes.add(_temporal_frame_hash(record['state']))
            sampled += 1
        except Exception:
            continue
    uniqueness = len(hashes) / max(1, sampled)
    exploration = sum((max(0.0, min(1.0, float(item.get('exploration_reward', 0.0)))) for item in records)) / len(records)
    priority = sum((max(0.05, float(item.get('priority', 0.05))) for item in records)) / len(records)
    return max(0.0, min(1.0, 0.62 * uniqueness + 0.26 * min(1.0, exploration * 2.5) + 0.12 * min(1.0, math.log1p(priority) / math.log(6.0))))

def _human_episode_quality(records: list[dict], victory_confidence: float, death_confidence: float, level_confidence: float, explicit_score_delta: float) -> tuple[float, str, bool, dict[str, float]]:
    if not records:
        return (0.0, 'human_empty', False, {'loop_ratio': 1.0, 'action_effect': 0.0, 'late_progress': -1.0})
    count = len(records)
    hashes: list[str] = []
    effects: list[float] = []
    for record in records:
        try:
            current_hash = _temporal_frame_hash(record['state'])
            hashes.append(current_hash)
            next_state = record.get('next_state')
            if next_state is not None:
                next_hash = _temporal_frame_hash(next_state)
                change = 1.0 - _perceptual_hash_similarity(current_hash, next_hash)
                effects.append(max(0.0, min(1.0, change * 8.0)))
        except Exception:
            continue
    uniqueness = len(set(hashes)) / max(1, len(hashes))
    immediate_repeats = sum((1 for index in range(1, len(hashes)) if hashes[index] == hashes[index - 1])) / max(1, len(hashes) - 1)
    loop_ratio = max(0.0, min(1.0, 0.65 * (1.0 - uniqueness) + 0.35 * immediate_repeats))
    action_effect = sum(effects) / len(effects) if effects else max(0.0, min(1.0, sum((float(item.get('exploration_reward', 0.0)) for item in records)) / max(1, count) * 2.5))
    split = max(1, count // 2)
    early = records[:split]
    late = records[split:] or records[-1:]

    def mean(items: list[dict], key: str) -> float:
        return sum((float(item.get(key, 0.0)) for item in items)) / max(1, len(items))
    early_task = mean(early, 'task_reward')
    late_task = mean(late, 'task_reward')
    early_exploration = mean(early, 'exploration_reward')
    late_exploration = mean(late, 'exploration_reward')
    late_safety = mean(late, 'safety_penalty')
    first_hashes = set(hashes[:split])
    late_hashes = hashes[split:] or hashes[-1:]
    late_new_fraction = sum((1 for value in late_hashes if value not in first_hashes)) / max(1, len(late_hashes))
    late_progress = max(-1.0, min(1.0, 0.45 * math.tanh((late_task - early_task) * 4.0) + 0.25 * math.tanh((late_exploration - early_exploration) * 3.0) + 0.35 * (late_new_fraction - 0.25) - 0.35 * math.tanh(late_safety * 2.0)))
    task_total = sum((float(item.get('task_reward', 0.0)) for item in records))
    exploration_mean = mean(records, 'exploration_reward')
    safety_total = sum((float(item.get('safety_penalty', 0.0)) for item in records))
    scale = max(1.0, math.sqrt(count))
    victory = max(0.0, min(1.0, float(victory_confidence)))
    death = max(0.0, min(1.0, float(death_confidence)))
    level = max(0.0, min(1.0, float(level_confidence)))
    score = float(explicit_score_delta)
    has_explicit_success = victory > death and victory > 0.0 or level > 0.0 or score > 0.0
    has_explicit_failure = death >= max(victory, 0.35) or score < 0.0
    quality = 0.4 + 0.5 * victory + 0.28 * level + 0.2 * math.tanh(max(0.0, score) / 3.0) - 0.5 * death - 0.28 * math.tanh(max(0.0, -score) / 3.0) + 0.14 * math.tanh(task_total / scale * 2.0) + 0.08 * math.tanh(exploration_mean * 3.0) + 0.14 * (action_effect - 0.25) + 0.16 * late_progress - 0.3 * loop_ratio - 0.28 * math.tanh(safety_total / scale)
    quality = max(0.02, min(1.0, quality))
    if victory > death and victory >= 0.5:
        quality = max(quality, 0.78)
    elif level >= 0.5:
        quality = max(quality, 0.68)
    if death >= 0.5:
        quality = min(quality, 0.18)
    elif score < 0.0:
        quality = min(quality, 0.35)
    if not has_explicit_success and (not has_explicit_failure):
        quality = min(quality, 0.82)
    if not has_explicit_success and loop_ratio >= 0.62 and (action_effect < 0.2):
        quality = min(quality, 0.28)
    if count < 4 and (not has_explicit_success):
        quality = min(quality, 0.6)
    if death >= 0.35:
        failure_type = 'explicit_death'
    elif score < 0.0:
        failure_type = 'explicit_score_loss'
    elif has_explicit_success:
        failure_type = 'none'
    elif loop_ratio >= 0.62 and action_effect < 0.2:
        failure_type = 'human_loop'
    elif safety_total / scale > 0.35:
        failure_type = 'human_unsafe'
    elif action_effect < 0.08 and late_progress < -0.1:
        failure_type = 'human_stagnation'
    else:
        failure_type = 'none'
    explicit_failure = bool(death >= 0.5 or score < 0.0)
    diagnostics = {'loop_ratio': float(loop_ratio), 'action_effect': float(action_effect), 'late_progress': float(late_progress)}
    return (float(quality), failure_type, explicit_failure, diagnostics)

def _sampling_stratum(record: dict) -> str:
    source = 'human' if record.get('source') == 'human' else 'ai'
    return '|'.join((source, _success_rate_bucket(float(record.get('episode_success_rate', 0.5))), str(record.get('failure_type', 'none')), _novelty_bucket(float(record.get('novelty_score', 0.0)))))

def _select_episode_ids_stratified(candidates: list[dict], row_limit: int, rng) -> list[tuple[str, str]]:
    if not candidates:
        return []
    buckets: dict[str, deque] = {}
    for candidate in candidates:
        buckets.setdefault(str(candidate['stratum']), deque()).append(candidate)
    for key, values in list(buckets.items()):
        ordered = sorted(values, key=lambda item: (float(item.get('priority', 0.0)), float(item.get('novelty', 0.0)), int(item.get('last_row', 0))), reverse=True)
        buckets[key] = deque(ordered)
    strata = list(buckets)
    rng.shuffle(strata)
    selected: list[tuple[str, str]] = []
    total = 0
    maximum = max(32, int(row_limit))
    while strata:
        progressed = False
        next_strata: list[str] = []
        for key in strata:
            values = buckets[key]
            if not values:
                continue
            candidate = values.popleft()
            selected.append((str(candidate['run_id']), str(candidate['episode_id'])))
            total += max(1, int(candidate.get('count', 1)))
            progressed = True
            if values:
                next_strata.append(key)
            if total >= maximum and len(selected) >= min(4, len(candidates)):
                return selected
        if not progressed:
            break
        strata = next_strata
    return selected

def contiguous_trajectory_records(records: list[dict], limit: int, sequence_length: int, burn_in_steps: int, n_step_horizon: int, rng) -> list[dict]:
    maximum = max(1, int(limit))
    chunk_length = max(32, int(sequence_length) + int(burn_in_steps) + int(n_step_horizon))
    chunks: list[list[dict]] = []
    for part in _continuous_trajectory_parts(records):
        if len(part) <= chunk_length:
            chunks.append(part)
            continue
        stride = max(16, int(sequence_length) // 2)
        for start in range(0, len(part), stride):
            chunk = part[start:start + chunk_length]
            if len(chunk) >= 8:
                chunks.append(chunk)

    def chunk_priority(chunk: list[dict]) -> float:
        first = chunk[0]
        human_bonus = 2.5 if first.get('source') == 'human' else 0.0
        success_bonus = 1.5 if first.get('trajectory_class') == 'successful_ai' else 0.0
        failure_bonus = 0.9 if str(first.get('failure_type', 'none')) != 'none' else 0.0
        novelty_bonus = 1.8 * float(first.get('novelty_score', 0.0))
        priority = sum((max(0.05, float(item.get('priority', 0.05))) for item in chunk)) / max(1, len(chunk))
        return human_bonus + success_bonus + failure_bonus + novelty_bonus + priority
    strata: dict[str, dict[tuple[str, str], deque]] = {}
    for chunk in chunks:
        stratum = _sampling_stratum(chunk[0])
        episode_key = (str(chunk[0].get('run_id', chunk[0]['episode_id'])), str(chunk[0]['episode_id']))
        strata.setdefault(stratum, {}).setdefault(episode_key, deque()).append(chunk)
    for episode_map in strata.values():
        for episode_key, values in list(episode_map.items()):
            episode_map[episode_key] = deque(sorted(values, key=chunk_priority, reverse=True))
    stratum_order = list(strata)
    rng.shuffle(stratum_order)
    episode_orders: dict[str, list[tuple[str, str]]] = {}
    episode_offsets: dict[str, int] = {}
    for stratum in stratum_order:
        order = list(strata[stratum])
        rng.shuffle(order)
        order.sort(key=lambda episode_key: chunk_priority(strata[stratum][episode_key][0]), reverse=True)
        episode_orders[stratum] = order
        episode_offsets[stratum] = 0
    selected: list[dict] = []
    chunk_index = 0
    while len(selected) < maximum and stratum_order:
        progressed = False
        active_strata: list[str] = []
        for stratum in stratum_order:
            order = episode_orders[stratum]
            if not order:
                continue
            chosen_episode = None
            for _ in range(len(order)):
                offset = episode_offsets[stratum] % len(order)
                episode_offsets[stratum] += 1
                candidate_episode = order[offset]
                if strata[stratum][candidate_episode]:
                    chosen_episode = candidate_episode
                    break
            if chosen_episode is None:
                continue
            chunk = strata[stratum][chosen_episode].popleft()
            remaining = maximum - len(selected)
            chosen = chunk if len(chunk) <= remaining else chunk[:remaining] if remaining >= 8 else []
            if chosen:
                sequence_id = f"{chosen[0].get('run_id', chosen[0]['episode_id'])}:{chosen[0]['episode_id']}:{int(chosen[0]['step'])}:{int(chosen[-1]['step'])}:{chunk_index}"
                selected.extend(({**item, '_sequence_id': sequence_id} for item in chosen))
                chunk_index += 1
                progressed = True
            if any((strata[stratum][episode_id] for episode_id in order)):
                active_strata.append(stratum)
            if len(selected) >= maximum:
                break
        if not progressed:
            break
        stratum_order = active_strata
    return selected

def load_training_data(np, db_path: Path, action_catalog: int | list[dict], sample_limit: int, stop_event: threading.Event | None, n_step_horizon: int=N_STEP_HORIZON_DEFAULT, validation_fraction: float=VALIDATION_EPISODE_FRACTION, reward_config: dict | None=None):
    ensure_database(db_path)
    if isinstance(action_catalog, list):
        catalog_actions = [normalized_action(action) for action in action_catalog]
        action_count = len(catalog_actions)
    else:
        action_count = max(1, int(action_catalog))
        catalog_actions = []
    catalog_signature_to_id = {action_signature(action): index for index, action in enumerate(catalog_actions)}
    maximum_action = action_space_size(action_count)
    horizon = max(10, min(20, int(n_step_horizon)))
    validation_fraction = max(0.05, min(0.35, float(validation_fraction)))
    reward_config = reward_config or DEFAULT_CONFIG
    limit = max(32, int(sample_limit))
    rng = np.random.default_rng(2657)
    connection = sqlite3.connect(db_path, timeout=60)
    install_sqlite_cancel_handler(connection, stop_event)
    invalid = 0
    try:
        surprise_weight = max(0.0, min(2.0, float(reward_config.get('human_surprise_training_weight', 0.65))))
        episode_rows = connection.execute('SELECT t.run_id,t.episode_id,COUNT(*),SUM(t.priority+?*MIN(4.0,COALESCE(h.human_action_surprise,0.0))),MAX(t.rowid),MIN(t.source),SUM(t.task_reward),SUM(t.exploration_reward),SUM(t.safety_penalty),AVG(t.reward),MAX(t.terminated),MAX(CASE WHEN t.outcome_type=2 THEN t.outcome_confidence ELSE 0 END),MAX(CASE WHEN t.outcome_type=1 THEN t.outcome_confidence ELSE 0 END),MAX(CASE WHEN t.outcome_type=4 THEN t.outcome_confidence ELSE 0 END),SUM(CASE WHEN t.outcome_type=3 THEN t.score_delta*t.outcome_confidence ELSE 0 END) FROM transitions AS t LEFT JOIN human_decisions AS h ON h.episode_id=t.episode_id AND h.step=t.step WHERE t.capture_failed=0 GROUP BY t.run_id,t.episode_id', (surprise_weight,)).fetchall()
        candidates: list[dict] = []
        for run_id, episode_id, count, priority_sum, last_row, source, task_total, exploration_total, safety_total, reward_mean, done, victory_confidence, death_confidence, level_confidence, explicit_score_delta in episode_rows:
            raise_if_cancelled(stop_event)
            count_value = max(1, int(count))
            task_value = float(task_total or 0.0)
            exploration_value = float(exploration_total or 0.0)
            safety_value = float(safety_total or 0.0)
            reward_value = float(reward_mean or 0.0)
            exploration_mean = exploration_value / count_value
            victory_value = max(0.0, min(1.0, float(victory_confidence or 0.0)))
            death_value = max(0.0, min(1.0, float(death_confidence or 0.0)))
            level_value = max(0.0, min(1.0, float(level_confidence or 0.0)))
            explicit_score_value = float(explicit_score_delta or 0.0)
            if victory_value > death_value and victory_value > 0.0:
                failure_type = 'none'
                success_rate = max(0.85, victory_value)
            elif death_value >= victory_value and death_value > 0.0:
                failure_type = 'explicit_death'
                success_rate = max(0.0, 0.15 * (1.0 - death_value))
            elif level_value > 0.0:
                failure_type = 'none'
                success_rate = max(0.7, 0.7 + 0.25 * level_value)
            elif explicit_score_value > 0.0:
                failure_type = 'none'
                success_rate = max(0.6, min(0.9, 0.65 + 0.2 * math.tanh(explicit_score_value / 3.0)))
            elif explicit_score_value < 0.0:
                failure_type = 'explicit_score_loss'
                success_rate = max(0.05, 0.3 - 0.2 * math.tanh(abs(explicit_score_value) / 3.0))
            else:
                failure_type = _classify_failure_type(bool(done), task_value, safety_value, reward_value, exploration_mean)
                success_rate = _bounded_episode_success_rate(task_value, exploration_value, safety_value, reward_value, bool(done), failure_type, count_value)
            average_priority = float(priority_sum or 0.0) / count_value
            novelty_proxy = max(0.0, min(1.0, 0.58 * min(1.0, exploration_mean * 2.5) + 0.42 * min(1.0, math.log1p(max(0.0, average_priority)) / math.log(6.0))))
            source_group = 'human' if str(source) == 'human' else 'ai'
            stratum = '|'.join((source_group, _success_rate_bucket(success_rate), failure_type, _novelty_bucket(novelty_proxy)))
            candidates.append({'run_id': str(run_id), 'episode_id': str(episode_id), 'count': count_value, 'priority': float(priority_sum or 0.0), 'last_row': int(last_row or 0), 'novelty': novelty_proxy, 'stratum': stratum})
        selected = _select_episode_ids_stratified(candidates, max(limit * 3, limit + 128), rng)
        if not selected:
            return None
        connection.execute('CREATE TEMP TABLE selected_episodes(run_id TEXT NOT NULL,episode_id TEXT NOT NULL,PRIMARY KEY(run_id,episode_id)) WITHOUT ROWID')
        connection.executemany('INSERT OR IGNORE INTO selected_episodes(run_id,episode_id) VALUES(?,?)', selected)
        rows = connection.execute("SELECT t.rowid,t.run_id,t.episode_id,t.step,t.source,t.state,t.action,t.reward,t.next_state,t.done,t.priority,t.task_reward,t.exploration_reward,t.safety_penalty,t.outcome_type,t.outcome_confidence,t.score_delta,t.terminated,t.truncated,t.capture_failed,t.action_payload,COALESCE(h.human_action_surprise,0.0),COALESCE(h.prediction_error,0.0),COALESCE(h.candidate_subgoal,''),COALESCE(h.goal_progress_delta,0.0) FROM transitions AS t INNER JOIN selected_episodes AS s ON s.run_id=t.run_id AND s.episode_id=t.episode_id LEFT JOIN human_decisions AS h ON h.episode_id=t.episode_id AND h.step=t.step ORDER BY t.run_id,t.episode_id,t.step").fetchall()
    except sqlite3.DatabaseError as error:
        raise_if_sqlite_cancelled(error, stop_event)
        raise
    finally:
        connection.close()
    episodes: dict[tuple[str, str], list[dict]] = {}
    for rowid, run_id, episode_id, step, source, state, action, reward, next_state, done, priority, task_reward, exploration_reward, safety_penalty, outcome_type, outcome_confidence, score_delta, terminated, truncated, capture_failed, action_payload, human_action_surprise, prediction_error, candidate_subgoal, goal_progress_delta in rows:
        raise_if_cancelled(stop_event)
        try:
            if bool(int(capture_failed)):
                continue
            action_id = int(action)
            stored_reward = float(reward)
            terminated_value = bool(int(terminated))
            truncated_value = bool(int(truncated))
            boundary_value = terminated_value or truncated_value
            done_value = terminated_value
            raw_task = float(task_reward)
            raw_exploration = float(exploration_reward)
            raw_safety = float(safety_penalty)
            outcome_value = int(outcome_type)
            outcome_confidence_value = float(outcome_confidence)
            score_delta_value = float(score_delta)
            surprise_value = max(0.0, min(24.0, float(human_action_surprise)))
            prediction_error_value = max(0.0, min(4.0, float(prediction_error)))
            goal_progress_delta_value = max(-1.0, min(1.0, float(goal_progress_delta)))
            if not all((math.isfinite(value) for value in (stored_reward, raw_task, raw_exploration, raw_safety, outcome_confidence_value, score_delta_value, surprise_value, prediction_error_value, goal_progress_delta_value))):
                raise ValueError
            if outcome_value not in OUTCOME_TYPES or not 0.0 <= outcome_confidence_value <= 1.0:
                raise ValueError
            task_value = max(-4.0, min(4.0, raw_task))
            exploration_value = max(0.0, min(1.0, raw_exploration))
            safety_value = max(0.0, min(2.0, raw_safety))
            reward_value = compose_reward({'task_reward': task_value, 'exploration_reward': exploration_value, 'safety_penalty': safety_value}, reward_config)
            if action_id >= action_count and action_id < action_count * DURATION_HEAD_SIZE:
                action_id //= DURATION_HEAD_SIZE
            fallback_action = catalog_actions[action_id] if 0 <= action_id < len(catalog_actions) else {}
            decoded_payload = decode_action_payload(action_payload, fallback_action=fallback_action)
            exact_catalog_id = catalog_signature_to_id.get(action_signature(decoded_payload))
            if exact_catalog_id is not None:
                action_id = int(exact_catalog_id)
            if source not in ('human', 'ai') or not 0 <= action_id < maximum_action:
                raise ValueError
            state_blob = _normalize_temporal_action_schema(bytes(state), action_count)
            decode_temporal_state(state_blob)
            next_blob = _normalize_temporal_action_schema(bytes(next_state), action_count) if next_state is not None else None
            if next_blob is not None:
                decode_temporal_state(next_blob)
            if not boundary_value and next_blob is None:
                raise ValueError
            episodes.setdefault((str(run_id), str(episode_id)), []).append({'rowid': int(rowid), 'run_id': str(run_id), 'episode_id': str(episode_id), 'step': int(step), 'source': str(source), 'state': state_blob, 'action': action_id, 'action_payload': decoded_payload, 'reward': max(-1.0, min(1.0, reward_value)), 'next_state': next_blob, 'done': done_value, 'terminated': terminated_value, 'truncated': truncated_value, 'capture_failed': False, 'episode_end': boundary_value, 'priority': max(0.05, min(20.0, float(priority) + surprise_weight * min(4.0, surprise_value))), 'task_reward': task_value, 'exploration_reward': exploration_value, 'safety_penalty': safety_value, 'outcome_type': outcome_value, 'outcome_confidence': outcome_confidence_value, 'score_delta': score_delta_value, 'human_action_surprise': surprise_value, 'prediction_error': prediction_error_value, 'candidate_subgoal': str(candidate_subgoal), 'goal_progress_delta': goal_progress_delta_value})
        except Exception:
            invalid += 1
    for records in episodes.values():
        raise_if_cancelled(stop_event)
        records.sort(key=lambda item: int(item['step']))
        human_episode = bool(records and records[0]['source'] == 'human')
        task_total = sum((float(record['task_reward']) for record in records))
        exploration_total = sum((float(record['exploration_reward']) for record in records))
        safety_total = sum((float(record['safety_penalty']) for record in records))
        reward_mean = sum((float(record['reward']) for record in records)) / max(1, len(records))
        exploration_mean = exploration_total / max(1, len(records))
        terminal = bool(records and records[-1].get('done'))
        victory_confidence = max((float(record.get('outcome_confidence', 0.0)) for record in records if int(record.get('outcome_type', OUTCOME_NONE)) == OUTCOME_VICTORY), default=0.0)
        death_confidence = max((float(record.get('outcome_confidence', 0.0)) for record in records if int(record.get('outcome_type', OUTCOME_NONE)) == OUTCOME_DEATH), default=0.0)
        level_confidence = max((float(record.get('outcome_confidence', 0.0)) for record in records if int(record.get('outcome_type', OUTCOME_NONE)) == OUTCOME_LEVEL), default=0.0)
        explicit_score_delta = sum((float(record.get('score_delta', 0.0)) * float(record.get('outcome_confidence', 0.0)) for record in records if int(record.get('outcome_type', OUTCOME_NONE)) == OUTCOME_SCORE))
        has_explicit_outcome = any((int(record.get('outcome_type', OUTCOME_NONE)) != OUTCOME_NONE and float(record.get('outcome_confidence', 0.0)) > 0.0 for record in records))
        quality_diagnostics = {'loop_ratio': 0.0, 'action_effect': 0.0, 'late_progress': 0.0}
        explicit_human_failure = False
        episode_quality = 0.5
        if human_episode:
            episode_quality, failure_type, explicit_human_failure, quality_diagnostics = _human_episode_quality(records, victory_confidence, death_confidence, level_confidence, explicit_score_delta)
            success_rate = episode_quality
        elif victory_confidence > death_confidence and victory_confidence > 0.0:
            failure_type = 'none'
            success_rate = max(0.85, victory_confidence)
        elif death_confidence >= victory_confidence and death_confidence > 0.0:
            failure_type = 'explicit_death'
            success_rate = max(0.0, 0.15 * (1.0 - death_confidence))
        elif level_confidence > 0.0:
            failure_type = 'none'
            success_rate = max(0.7, 0.7 + 0.25 * level_confidence)
        elif explicit_score_delta > 0.0:
            failure_type = 'none'
            success_rate = max(0.6, min(0.9, 0.65 + 0.2 * math.tanh(explicit_score_delta / 3.0)))
        elif explicit_score_delta < 0.0:
            failure_type = 'explicit_score_loss'
            success_rate = max(0.05, 0.3 - 0.2 * math.tanh(abs(explicit_score_delta) / 3.0))
        else:
            failure_type = _classify_failure_type(terminal, task_total, safety_total, reward_mean, exploration_mean)
            success_rate = _bounded_episode_success_rate(task_total, exploration_total, safety_total, reward_mean, terminal, failure_type, len(records))
        novelty_score = _episode_novelty_score(records)
        trajectory_class = 'human' if human_episode else 'successful_ai' if victory_confidence > death_confidence or level_confidence > 0.0 or explicit_score_delta > 0.0 or (not has_explicit_outcome and success_rate >= 0.65 and (failure_type == 'none')) else 'failed_ai' if death_confidence >= max(victory_confidence, 1e-09) or explicit_score_delta < 0.0 or (not has_explicit_outcome and failure_type != 'none' and (success_rate < 0.45)) else 'ordinary_ai'
        if not human_episode:
            if trajectory_class == 'successful_ai':
                episode_quality = max(0.7, success_rate)
            elif trajectory_class == 'failed_ai':
                episode_quality = max(0.03, success_rate * 0.2)
            else:
                episode_quality = max(0.2, min(0.6, success_rate))
        for record in records:
            raise_if_cancelled(stop_event)
            record['trajectory_class'] = trajectory_class
            record['episode_quality'] = float(episode_quality)
            record['explicit_human_failure'] = explicit_human_failure
            record['episode_success_rate'] = float(success_rate)
            record['failure_type'] = failure_type
            record['episode_loop_ratio'] = float(quality_diagnostics['loop_ratio'])
            record['episode_action_effect'] = float(quality_diagnostics['action_effect'])
            record['episode_late_progress'] = float(quality_diagnostics['late_progress'])
            record['novelty_score'] = float(novelty_score)
            record['novelty_bucket'] = _novelty_bucket(novelty_score)
            record['sampling_stratum'] = _sampling_stratum(record)
    for records in episodes.values():
        raise_if_cancelled(stop_event)
        apply_outcome_credit(records)
        for record in records:
            raise_if_cancelled(stop_event)
            record['reward'] = max(-1.0, min(1.0, compose_reward({'task_reward': float(record['task_reward']), 'exploration_reward': float(record['exploration_reward']), 'safety_penalty': float(record['safety_penalty'])}, reward_config)))
    train_records: list[dict] = []
    validation_records: list[dict] = []
    discount = 0.96
    run_ids = {str(record.get('run_id', record['episode_id'])) for records in episodes.values() for record in records[:1]}
    for (run_id, episode_id), records in episodes.items():
        raise_if_cancelled(stop_event)
        run_id = str(run_id)
        validation_bucket = int.from_bytes(hashlib.sha256(run_id.encode('utf-8')).digest()[:4], 'little') / 2 ** 32
        target = validation_records if len(run_ids) > 1 and validation_bucket < validation_fraction else train_records
        for index, record in enumerate(records):
            raise_if_cancelled(stop_event)
            total = 0.0
            task_total = 0.0
            exploration_total = 0.0
            safety_total = 0.0
            multiplier = 1.0
            n_next = record['next_state']
            n_done = record['done']
            steps_used = 1
            for offset in range(horizon):
                raise_if_cancelled(stop_event)
                position = index + offset
                if position >= len(records):
                    break
                item = records[position]
                if int(item['step']) != int(record['step']) + offset:
                    break
                total += multiplier * float(item['reward'])
                task_total += multiplier * float(item['task_reward'])
                exploration_total += multiplier * float(item['exploration_reward'])
                safety_total += multiplier * float(item['safety_penalty'])
                steps_used = offset + 1
                n_next = item['next_state']
                n_done = bool(item['done'])
                if bool(item.get('episode_end', n_done)):
                    break
                multiplier *= discount
            enriched = dict(record)
            enriched.update({'n_return': max(-3.0, min(3.0, total)), 'n_task_return': max(-3.0, min(3.0, task_total)), 'n_exploration_return': max(0.0, min(3.0, exploration_total)), 'n_safety_return': max(0.0, min(4.0, safety_total)), 'n_next_state': n_next, 'n_done': n_done, 'discount_power': 0.0 if n_done or n_next is None else discount ** steps_used, 'n_steps': steps_used})
            target.append(enriched)
    if not validation_records and len(run_ids) > 1:
        one_run = sorted(run_ids)[0]
        moved = [record for record in train_records if record['run_id'] == one_run]
        train_records = [record for record in train_records if record['run_id'] != one_run]
        validation_records.extend(moved)
    if not train_records and len(run_ids) > 1 and validation_records:
        one_run = str(validation_records[0]['run_id'])
        moved = [record for record in validation_records if record['run_id'] == one_run]
        validation_records = [record for record in validation_records if record['run_id'] != one_run]
        train_records.extend(moved)
    train_records = contiguous_trajectory_records(train_records, sample_limit, int(reward_config.get('sequence_length', TRAIN_SEQUENCE_LENGTH)), int(reward_config.get('burn_in_steps', TRAIN_BURN_IN_STEPS)), horizon, rng)
    validation_limit = max(64, min(4096, sample_limit // 4))
    if len(validation_records) > validation_limit:
        validation_records = contiguous_trajectory_records(validation_records, validation_limit, int(reward_config.get('sequence_length', TRAIN_SEQUENCE_LENGTH)), int(reward_config.get('burn_in_steps', TRAIN_BURN_IN_STEPS)), horizon, rng)
    strata = {str(record.get('sampling_stratum', '')) for record in train_records if record.get('sampling_stratum')}
    return {'train': train_records, 'validation': validation_records, 'invalid': invalid, 'episodes': len(episodes), 'runs': len(run_ids), 'horizon': horizon, 'strata': len(strata), 'db_path': str(db_path)}

def refresh_transition_priorities(np, model: dict, target_model: dict, records: list[dict], db_path: str | Path | None, stop_event: threading.Event | None=None) -> int:
    if not db_path:
        return 0
    path = Path(db_path)
    if not path.is_file() or path.is_symlink():
        return 0
    unique: dict[int, dict] = {}
    for record in records:
        raise_if_cancelled(stop_event)
        try:
            rowid = int(record.get('rowid', 0))
        except (TypeError, ValueError, OverflowError):
            continue
        if rowid > 0:
            unique[rowid] = record
    priority_updates: list[tuple[float, int]] = []
    for rowid, record in unique.items():
        raise_if_cancelled(stop_event)
        try:
            hidden = _latest_temporal_hidden(np, model, record['state'])
            _, q_values, _ = factorized_action_outputs_from_hidden(np, model, hidden)
            action = int(record['action'])
            task_td_error = abs(float(q_values[TASK_CRITIC, action]) - float(record.get('n_task_return', record.get('task_reward', 0.0))))
            exploration_td_error = abs(float(q_values[EXPLORATION_CRITIC, action]) - float(record.get('n_exploration_return', record.get('exploration_reward', 0.0))))
            safety_td_error = abs(float(q_values[SAFETY_CRITIC, action]) - float(record.get('n_safety_return', record.get('safety_penalty', 0.0))))
            world_latent_error = 0.0
            if record.get('next_state') is not None and (not bool(record.get('done', False))):
                latent = world_model_latent(np, model, hidden)
                predicted_latent, _, _ = latent_world_model_step(np, model, latent, action, _record_duration_index(record), action_payload=record.get('action_payload'))
                target_hidden = _latest_temporal_hidden(np, target_model, record['next_state'])
                target_latent = world_model_latent(np, target_model, target_hidden)
                world_latent_error = float(np.sqrt(np.mean((predicted_latent - target_latent) ** 2)))
            outcome_confidence = max(0.0, min(1.0, float(record.get('outcome_confidence', 0.0))))
            novelty = max(0.0, min(1.0, float(record.get('novelty_score', 0.0))))
            new_priority = 0.25 + 1.5 * min(4.0, task_td_error) + 0.6 * min(3.0, exploration_td_error) + 0.8 * min(4.0, safety_td_error) + 0.8 * min(4.0, world_latent_error) + 1.2 * outcome_confidence + 0.3 * novelty
            if math.isfinite(new_priority):
                priority_updates.append((max(0.05, min(20.0, new_priority)), rowid))
        except Exception:
            continue
    if not priority_updates:
        return 0
    connection = sqlite3.connect(path, timeout=60)
    install_sqlite_cancel_handler(connection, stop_event)
    try:
        with connection:
            connection.executemany('UPDATE transitions SET priority=? WHERE rowid=?', priority_updates)
    except sqlite3.DatabaseError as error:
        raise_if_sqlite_cancelled(error, stop_event)
        raise
    finally:
        connection.close()
    return len(priority_updates)

def predict_progress(np, model: dict, hidden) -> float:
    value = float(np.asarray(hidden, dtype=np.float32) @ model['progress_w'][:, 0] + model['progress_b'][0])
    return max(-4.0, min(4.0, value))

def _record_progress_stability(record: dict) -> float:
    try:
        frames, _, _ = decode_temporal_state(record['state'])
        motion = feature_motion(frames[-1])
    except Exception:
        motion = 1.0
    safety = max(0.0, min(2.0, float(record.get('safety_penalty', 0.0))))
    excessive_motion = max(0.0, min(1.0, (motion - 0.18) / 0.45))
    terminal_penalty = 0.35 if bool(record.get('done', False)) and safety > 0.25 else 0.0
    return max(0.1, min(1.0, 1.0 - 0.55 * excessive_motion - 0.3 * safety - terminal_penalty))

def _ordered_progress_positions(window: list[dict], earlier_position: int, later_position: int) -> tuple[int, int, float] | None:
    earlier = window[earlier_position]
    later = window[later_position]
    source = str(earlier.get('source', ''))
    trajectory_class = str(earlier.get('trajectory_class', ''))
    stability = 0.5 * (_record_progress_stability(earlier) + _record_progress_stability(later))
    if source == 'human':
        episode_quality = max(0.0, min(1.0, float(earlier.get('episode_quality', 0.5))))
        return_difference = float(later.get('n_task_return', 0.0)) - float(earlier.get('n_task_return', 0.0))
        later_safety = float(later.get('n_safety_return', later.get('safety_penalty', 0.0)))
        if bool(later.get('done', False)) and (episode_quality < 0.3 or later_safety > 0.5):
            return (later_position, earlier_position, max(0.15, stability * 0.6))
        if abs(return_difference) > 0.08:
            if return_difference > 0.0:
                return (earlier_position, later_position, max(0.18, stability * episode_quality))
            return (later_position, earlier_position, max(0.18, stability * episode_quality))
        if episode_quality >= 0.65 and later_safety < 0.25:
            return (earlier_position, later_position, max(0.2, stability * episode_quality))
        return None
    if trajectory_class == 'successful_ai':
        return (earlier_position, later_position, max(0.2, stability))
    if trajectory_class == 'failed_ai' and (bool(later.get('done', False)) or float(later.get('safety_penalty', 0.0)) > 0.35):
        return (later_position, earlier_position, max(0.2, stability))
    return_difference = float(later.get('n_task_return', 0.0)) - float(earlier.get('n_task_return', 0.0))
    if abs(return_difference) <= 0.1:
        return None
    if return_difference > 0.0:
        return (earlier_position, later_position, max(0.15, stability * 0.75))
    return (later_position, earlier_position, max(0.15, stability * 0.75))

def _record_duration_index(record: dict) -> int:
    try:
        payload = record.get('action_payload')
        if payload:
            return int(decode_action_payload(payload).get('duration_index', DURATION_HEAD_SIZE // 2))
    except Exception:
        pass
    try:
        state_blob = record.get('next_state') or record.get('state')
        _, _, durations = decode_temporal_state(state_blob)
        return duration_bin(float(durations[-1]))
    except Exception:
        return DURATION_HEAD_SIZE // 2

def _convert_legacy_temporal_action_schema(state: bytes) -> bytes:
    frames, actions, durations, valid_length = decode_temporal_state_with_length(state)
    start = len(frames) - valid_length
    frames = frames[start:]
    actions = actions[start:]
    durations = durations[start:]
    normalized_actions = [max(0, int(value)) // DURATION_HEAD_SIZE for value in actions]
    return build_temporal_state(frames, normalized_actions, durations)

def _normalize_temporal_action_schema(state: bytes, action_count: int) -> bytes:
    frames, actions, durations, valid_length = decode_temporal_state_with_length(state)
    start = len(frames) - valid_length
    frames = frames[start:]
    actions = actions[start:]
    durations = durations[start:]
    changed = False
    normalized_actions = []
    for value in actions:
        action_id = int(value)
        if action_id >= int(action_count) and action_id < int(action_count) * DURATION_HEAD_SIZE:
            action_id //= DURATION_HEAD_SIZE
            changed = True
        normalized_actions.append(action_id)
    normalized_state = build_temporal_state(frames, normalized_actions, durations)
    return normalized_state if changed or normalized_state != state else state

def extract_human_skills(records: list[dict], config: dict) -> list[dict]:
    minimum = max(SKILL_MIN_STEPS, min(16, int(config.get('skill_min_steps', SKILL_MIN_STEPS))))
    maximum = max(minimum, min(SKILL_MAX_STEPS, int(config.get('skill_max_steps', SKILL_MAX_STEPS))))
    limit = max(8, min(SKILL_HEAD_SIZE, int(config.get('skill_limit', SKILL_HEAD_SIZE))))
    episodes = _continuous_trajectory_parts([record for record in records if record.get('source') == 'human'])
    candidates: dict[tuple[tuple[int, int], ...], list[tuple[float, float, str]]] = {}
    lengths = sorted({minimum, min(maximum, 8), min(maximum, 16), maximum})
    for episode in episodes:
        sequence = [(int(item['action']), _record_duration_index(item), float(item.get('task_reward', 0.0)), float(item.get('human_action_surprise', 0.0)), str(item.get('candidate_subgoal', ''))) for item in episode]
        for length in lengths:
            if length < minimum or len(sequence) < length:
                continue
            stride = max(1, length // 2)
            for start in range(0, len(sequence) - length + 1, stride):
                segment = sequence[start:start + length]
                signature = tuple(((action, duration) for action, duration, *_ in segment))
                quality = sum((reward for _, _, reward, _, _ in segment)) / length
                surprise = sum((value for _, _, _, value, _ in segment)) / length
                named_goals = [goal for _, _, _, _, goal in segment if goal]
                goal = max(set(named_goals), key=named_goals.count) if named_goals else ''
                candidates.setdefault(signature, []).append((quality, surprise, goal))
    ranked = []
    surprise_weight = max(0.0, min(4.0, float(config.get('human_surprise_training_weight', 1.25))))
    for signature, evidence in candidates.items():
        count = len(evidence)
        if count < 2 and len(signature) < 8:
            continue
        quality = sum((item[0] for item in evidence)) / max(1, count)
        surprise = sum((item[1] for item in evidence)) / max(1, count)
        named_goals = [item[2] for item in evidence if item[2]]
        goal = max(set(named_goals), key=named_goals.count) if named_goals else ''
        diversity = len(set((action for action, _ in signature))) / max(1, len(signature))
        score = math.log1p(count) * math.sqrt(len(signature)) + 0.8 * quality + 0.25 * diversity + surprise_weight * math.log1p(max(0.0, surprise))
        ranked.append((score, signature, count, quality, surprise, goal))
    ranked.sort(key=lambda item: item[0], reverse=True)
    result = []
    for _, signature, count, quality, surprise, goal in ranked[:limit]:
        result.append({'actions': [action for action, _ in signature], 'durations': [duration for _, duration in signature], 'count': int(count), 'quality': max(-1.0, min(1.0, float(quality))), 'human_action_surprise': max(0.0, min(24.0, float(surprise))), 'goal_condition': goal})
    return result

def persist_semantic_skills(path: Path, skills: list[dict]) -> int:
    connection = _runtime_module('memory').open_semantic_database(path)
    memory_module = _runtime_module('memory')
    understanding_module = _runtime_module('understanding')
    causal_module = _runtime_module('causal_model')
    saved = 0
    try:
        for skill in skills:
            actions = [int(value) for value in skill.get('actions', ())]
            durations = [int(value) for value in skill.get('durations', ())]
            if not actions:
                continue
            goal_condition = str(skill.get('goal_condition', ''))
            preconditions: tuple[str, ...] = ()
            row = connection.execute('SELECT belief_state_before FROM human_decisions WHERE candidate_subgoal=? ORDER BY human_action_surprise DESC LIMIT 1', (goal_condition,)).fetchone()
            if row is not None:
                try:
                    belief = understanding_module.belief_from_dict(json.loads(str(row[0])))
                    preconditions = causal_module.semantic_facts(belief)[:16]
                except (TypeError, ValueError, json.JSONDecodeError):
                    preconditions = ()
            policy = json.dumps({'actions': actions, 'durations': durations}, ensure_ascii=False, sort_keys=True, separators=(',', ':')).encode('utf-8')
            identifier = 'skill:' + hashlib.blake2b(goal_condition.encode('utf-8') + b'\x00' + policy, digest_size=12).hexdigest()
            memory_module.save_learned_skill(connection, memory_module.LearnedSkill(skill_id=identifier, preconditions=tuple(preconditions), goal_condition=goal_condition, policy_blob=policy, success_rate=max(0.0, min(1.0, 0.5 + 0.5 * float(skill.get('quality', 0.0)))), use_count=max(0, int(skill.get('count', 0)))))
            saved += 1
        connection.commit()
        return saved
    finally:
        connection.close()

def skill_label_for_position(window: list[dict], position: int, skills: list[dict]) -> int | None:
    best = None
    best_length = -1
    for skill_index, skill in enumerate(skills[:SKILL_HEAD_SIZE]):
        actions = skill.get('actions', [])
        if not SKILL_MIN_STEPS <= len(actions) <= SKILL_MAX_STEPS or position + len(actions) > len(window):
            continue
        if all((int(window[position + offset]['action']) == int(action) for offset, action in enumerate(actions))):
            if len(actions) > best_length:
                best = skill_index
                best_length = len(actions)
    return best

def hierarchical_skill_plan_values(np, model: dict, hidden, skills: list[dict], critic_weights: dict | tuple[float, float, float] | None=None):
    count = min(SKILL_HEAD_SIZE, len(skills))
    result = np.zeros(count, dtype=np.float32)
    world_steps = max(0, int(model.get('world_training_steps', 0)))
    minimum_steps = max(WORLD_MODEL_MIN_TRAINING_STEPS, len(model['action_factors']) * 8)
    confidence = world_model_planning_confidence(model, world_steps, minimum_steps)
    if count <= 0 or confidence <= 0.0:
        return result
    horizon = max(WORLD_MODEL_SKILL_MIN_HORIZON, min(WORLD_MODEL_SKILL_MAX_HORIZON, int(round(WORLD_MODEL_SKILL_MIN_HORIZON + confidence * (WORLD_MODEL_SKILL_MAX_HORIZON - WORLD_MODEL_SKILL_MIN_HORIZON)))))
    gamma = max(0.1, min(0.98, float(critic_weights.get('planning_discount', 0.85)))) if isinstance(critic_weights, dict) else 0.85
    uncertainty_weight = max(0.0, min(2.0, float(critic_weights.get('world_uncertainty_penalty', 0.25)))) if isinstance(critic_weights, dict) else 0.25
    weights = critic_weight_vector(np, critic_weights)
    for skill_index, skill in enumerate(skills[:count]):
        actions = [max(0, min(len(model['action_factors']) - 1, int(value))) for value in skill.get('actions', [])]
        durations = [max(0, min(DURATION_HEAD_SIZE - 1, int(value))) for value in skill.get('durations', [])]
        if not actions:
            continue
        if len(durations) < len(actions):
            durations.extend([DURATION_HEAD_SIZE // 2] * (len(actions) - len(durations)))
        latent = world_model_latent(np, model, hidden)
        survival = 1.0
        total = 0.0
        for depth in range(horizon):
            position = depth % len(actions)
            latent, reward_vector, done_probability = latent_world_model_step(np, model, latent, actions[position], durations[position], stochastic_token=skill_index * 257 + depth)
            uncertainty = float(np.mean(np.std(latent, axis=0)))
            total += gamma ** depth * survival * (float(reward_vector @ weights) - uncertainty_weight * uncertainty)
            survival *= max(0.0, 1.0 - done_probability)
            if survival < 0.02 or uncertainty > 0.55 + 0.65 * confidence:
                break
        result[skill_index] = float(total * confidence)
    return np.clip(result, -4.0, 4.0)

def choose_skill(np, model: dict, hidden, skills: list[dict], start_probability: float, exploration: float, critic_weights: dict | tuple[float, float, float] | None=None, deterministic: bool=False) -> int | None:
    count = min(SKILL_HEAD_SIZE, len(skills))
    world_steps = max(0, int(model.get('world_training_steps', 0)))
    minimum_steps = max(WORLD_MODEL_MIN_TRAINING_STEPS, len(model['action_factors']) * 8)
    world_confidence = world_model_planning_confidence(model, world_steps, minimum_steps)
    effective_start = max(max(0.0, min(1.0, float(start_probability))), 0.55 * world_confidence)
    if count <= 0:
        return None
    if deterministic:
        if effective_start < 0.5:
            return None
    elif random.random() > effective_start:
        return None
    logits = np.asarray(hidden, dtype=np.float32) @ model['policy_skill_w'][:, :count] + model['policy_skill_b'][:count]
    values = np.asarray(hidden, dtype=np.float32) @ model['skill_value_w'][:, :count] + model['skill_value_b'][:count]
    quality = np.asarray([float(skill.get('quality', 0.0)) for skill in skills[:count]], dtype=np.float32)
    planned = hierarchical_skill_plan_values(np, model, hidden, skills[:count], critic_weights)
    planning_weight = max(0.0, min(1.0, float(critic_weights.get('planning_weight', 0.38)))) if isinstance(critic_weights, dict) else 0.38
    score = logits + 0.35 * values + 0.2 * quality + planning_weight * planned
    if not deterministic and random.random() < max(0.0, min(0.3, float(exploration))):
        return random.randrange(count)
    return int(np.argmax(score))

def _train_progress_pair(np, model: dict, earlier_hidden, later_hidden, margin: float, weight: float, gradients: dict[str, object]):
    earlier = predict_progress(np, model, earlier_hidden)
    later = predict_progress(np, model, later_hidden)
    violation = float(margin) - later + earlier
    if violation <= 0.0:
        return (0.0, np.zeros_like(earlier_hidden), np.zeros_like(later_hidden))
    scale = max(0.0, float(weight))
    gradients['progress_w'][:, 0] += scale * (earlier_hidden - later_hidden)
    gradients['progress_b'][0] += 0.0
    earlier_gradient = model['progress_w'][:, 0] * scale
    later_gradient = -model['progress_w'][:, 0] * scale
    return (violation * scale, earlier_gradient.astype(np.float32), later_gradient.astype(np.float32))

def _train_skill_head(np, model: dict, hidden, skill_index: int, target_return: float, weight: float, gradients: dict[str, object]):
    count = SKILL_HEAD_SIZE
    logits = hidden @ model['policy_skill_w'] + model['policy_skill_b']
    probabilities = _softmax_vector(np, logits).astype(np.float32)
    gradient = probabilities
    gradient[int(skill_index)] -= 1.0
    gradient *= max(0.0, float(weight))
    gradients['policy_skill_w'] += np.outer(hidden, gradient).astype(np.float32)
    gradients['policy_skill_b'] += gradient
    hidden_gradient = model['policy_skill_w'] @ gradient
    value = float(hidden @ model['skill_value_w'][:, int(skill_index)] + model['skill_value_b'][int(skill_index)])
    error = max(-3.0, min(3.0, value - float(target_return))) * max(0.0, float(weight))
    gradients['skill_value_w'][:, int(skill_index)] += hidden * error
    gradients['skill_value_b'][int(skill_index)] += error
    hidden_gradient += model['skill_value_w'][:, int(skill_index)] * error
    loss = -math.log(max(1e-09, float(probabilities[int(skill_index)]))) * max(0.0, float(weight)) + 0.5 * error * error
    return (float(loss), hidden_gradient.astype(np.float32))

def clip_gradients_by_global_norm(np, gradients: list, maximum_norm: float=8.0) -> float:
    maximum = max(1e-06, float(maximum_norm))
    global_norm = 0.0
    for gradient in gradients:
        if not np.isfinite(gradient).all():
            raise RuntimeError('训练梯度包含无效数值')
        component_norm = float(np.linalg.norm(gradient))
        global_norm = math.hypot(global_norm, component_norm)
    if global_norm > maximum:
        scale = maximum / max(global_norm, 1e-12)
        for gradient in gradients:
            gradient *= scale
    return global_norm

def _softmax_vector(np, logits):
    values = np.asarray(logits, dtype=np.float64)
    values -= float(values.max(initial=0.0))
    exp = np.exp(np.clip(values, -60.0, 30.0))
    return exp / max(1e-12, float(exp.sum()))
_TEMPORAL_PARAMETER_KEYS = frozenset({'frame_proj', 'frame_bias', 'action_embedding', 'duration_embedding', 'Wz', 'Uz', 'bz', 'Wr', 'Ur', 'br', 'Wh', 'Uh', 'bh'})
_CONV_PARAMETER_KEYS = frozenset({'perception_patch_w', 'perception_patch_b', 'perception_scene_w', 'perception_scene_b', 'perception_hud_w', 'perception_hud_b', 'perception_motion_w', 'perception_motion_b', 'perception_event_w', 'perception_event_b', 'perception_event_confidence_w', 'perception_event_confidence_b'})
_TRAINABLE_PARAMETER_KEYS = (*_CONV_PARAMETER_KEYS, 'frame_proj', 'frame_bias', 'action_embedding', 'duration_embedding', 'Wz', 'Uz', 'bz', 'Wr', 'Ur', 'br', 'Wh', 'Uh', 'bh', 'online_adapter_w', 'online_adapter_b', 'policy_control_w', 'policy_control_b', 'policy_key_w', 'policy_key_b', 'policy_mouse_w', 'policy_mouse_b', 'policy_button_w', 'policy_button_b', 'policy_duration_w', 'policy_duration_b', 'policy_duration_kind_b', 'policy_control_decision_w', 'policy_control_decision_b', 'policy_action_w', 'policy_action_b', 'policy_skill_w', 'policy_skill_b', 'skill_value_w', 'skill_value_b', 'mouse_offset_w', 'mouse_offset_b', 'q_control_w', 'q_control_b', 'q_key_w', 'q_key_b', 'q_mouse_w', 'q_mouse_b', 'q_button_w', 'q_button_b', 'q_duration_w', 'q_duration_b', 'q_duration_kind_b', 'q_action_w', 'q_action_b', 'value_w', 'value_b', 'progress_w', 'progress_b', 'safety_w', 'safety_b', 'world_encoder_w', 'world_encoder_b', 'world_dynamics_w', 'world_dynamics_action_w', 'world_dynamics_duration_w', 'world_stochastic_w', 'world_prior_state_w', 'world_prior_action_w', 'world_prior_duration_w', 'world_prior_b', 'world_posterior_state_w', 'world_posterior_observation_w', 'world_posterior_b', 'world_dynamics_b', 'world_reward_w', 'world_reward_action_w', 'world_reward_duration_w', 'world_reward_b', 'world_done_w', 'world_done_b', 'world_continuation_w', 'world_continuation_b', 'world_latent_to_hidden_w', 'world_latent_to_hidden_b', 'world_slot_w', 'world_slot_b', 'world_hud_w', 'world_hud_b', 'world_event_w', 'world_event_b', 'reward_model_w', 'reward_model_b')
ONLINE_TRAINABLE_KEYS = frozenset({'online_adapter_w', 'online_adapter_b', 'policy_action_w', 'policy_action_b', 'policy_control_w', 'policy_control_b', 'policy_key_w', 'policy_key_b', 'policy_mouse_w', 'policy_mouse_b', 'policy_button_w', 'policy_button_b', 'policy_duration_w', 'policy_duration_b', 'policy_duration_kind_b', 'mouse_offset_w', 'mouse_offset_b', 'q_action_w', 'q_action_b', 'value_w', 'value_b'})

def _training_gradient_buffer(np, model: dict) -> dict[str, object]:
    return {key: np.zeros_like(model[key], dtype=np.float32) for key in _TRAINABLE_PARAMETER_KEYS}

def _factor_bucket_gradient(np, factors, column: int, action_gradient, size: int):
    bucket_gradient = np.zeros(size, dtype=np.float32)
    np.add.at(bucket_gradient, factors[:, column], np.asarray(action_gradient, dtype=np.float32))
    return bucket_gradient

def _structured_policy_head_supervision(np, model: dict, hidden, action_payload: object, weight: float, gradients: dict[str, object]) -> tuple[float, object]:
    magnitude = max(0.0, min(100.0, float(weight)))
    hidden_value = np.asarray(hidden, dtype=np.float32)
    hidden_gradient = np.zeros_like(hidden_value)
    if magnitude <= 1e-12:
        return (0.0, hidden_gradient)
    payload = decode_action_payload(action_payload)
    action = normalized_action(payload)
    kind, mouse_bucket, _ = action_factor_tuple(action, int(payload['duration_index']))
    loss = 0.0
    control_logits = hidden_value @ model['policy_control_w'] + model['policy_control_b']
    control_probabilities = _softmax_vector(np, control_logits).astype(np.float32)
    control_gradient = control_probabilities.copy()
    control_gradient[int(kind)] -= 1.0
    control_gradient *= 0.35 * magnitude
    gradients['policy_control_w'] += np.outer(hidden_value, control_gradient).astype(np.float32)
    gradients['policy_control_b'] += control_gradient
    hidden_gradient += model['policy_control_w'] @ control_gradient
    loss += -0.35 * magnitude * math.log(max(1e-09, float(control_probabilities[int(kind)])))
    mouse_logits = hidden_value @ model['policy_mouse_w'] + model['policy_mouse_b']
    mouse_probabilities = _softmax_vector(np, mouse_logits).astype(np.float32)
    mouse_gradient = mouse_probabilities.copy()
    mouse_gradient[int(mouse_bucket)] -= 1.0
    mouse_gradient *= 0.3 * magnitude
    gradients['policy_mouse_w'] += np.outer(hidden_value, mouse_gradient).astype(np.float32)
    gradients['policy_mouse_b'] += mouse_gradient
    hidden_gradient += model['policy_mouse_w'] @ mouse_gradient
    loss += -0.3 * magnitude * math.log(max(1e-09, float(mouse_probabilities[int(mouse_bucket)])))
    key_logits = hidden_value @ model['policy_key_w'] + model['policy_key_b']
    key_probabilities = _sigmoid(np, key_logits).astype(np.float32)
    key_targets = np.zeros(KEY_HEAD_SIZE, dtype=np.float32)
    for key in action['keys']:
        if 0 <= int(key) < KEY_HEAD_SIZE:
            key_targets[int(key)] = 1.0
    key_gradient = key_probabilities * 0.035
    selected_keys = np.flatnonzero(key_targets > 0.5)
    if len(selected_keys):
        key_gradient[selected_keys] = key_probabilities[selected_keys] - 1.0
    key_gradient *= 0.1 * magnitude
    gradients['policy_key_w'] += np.outer(hidden_value, key_gradient).astype(np.float32)
    gradients['policy_key_b'] += key_gradient
    hidden_gradient += model['policy_key_w'] @ key_gradient
    chosen_key_probability = float(np.mean(key_probabilities[selected_keys])) if len(selected_keys) else float(np.mean(1.0 - key_probabilities))
    loss += -0.1 * magnitude * math.log(max(1e-09, chosen_key_probability))
    button_logits = hidden_value @ model['policy_button_w'] + model['policy_button_b']
    button_probabilities = _sigmoid(np, button_logits).astype(np.float32)
    button_names = ('left', 'right', 'middle', 'x1', 'x2')
    button_targets = np.asarray([float(name in action['buttons']) for name in button_names], dtype=np.float32)
    button_gradient = (button_probabilities - button_targets) * (0.2 * magnitude)
    gradients['policy_button_w'] += np.outer(hidden_value, button_gradient).astype(np.float32)
    gradients['policy_button_b'] += button_gradient
    hidden_gradient += model['policy_button_w'] @ button_gradient
    button_likelihood = np.where(button_targets > 0.5, button_probabilities, 1.0 - button_probabilities)
    loss += -0.2 * magnitude * float(np.mean(np.log(np.maximum(button_likelihood, 1e-09))))
    return (float(loss), hidden_gradient.astype(np.float32, copy=False))

def control_supervision_target(previous_action: int, current_action: int, next_action: int, done: bool) -> int:
    if done or int(next_action) < 0:
        return CONTROL_DECISIONS.index('release')
    if int(current_action) >= 0 and int(next_action) == int(current_action):
        return CONTROL_DECISIONS.index('continue')
    return CONTROL_DECISIONS.index('start')

def _train_control_decision_head(np, model: dict, hidden, previous_action: int, current_action: int, next_action: int, done: bool, weight: float, gradients: dict[str, object]) -> tuple[float, object]:
    target = control_supervision_target(previous_action, current_action, next_action, done)
    hidden_value = np.asarray(hidden, dtype=np.float32)
    logits = hidden_value @ model['policy_control_decision_w'] + model['policy_control_decision_b']
    probabilities = _softmax_vector(np, logits)
    output_gradient = probabilities.copy()
    output_gradient[target] -= 1.0
    output_gradient *= max(0.0, min(4.0, float(weight)))
    gradients['policy_control_decision_w'] += np.outer(hidden_value, output_gradient)
    gradients['policy_control_decision_b'] += output_gradient
    hidden_gradient = model['policy_control_decision_w'] @ output_gradient
    return (-max(0.0, float(weight)) * math.log(max(1e-09, float(probabilities[target]))), hidden_gradient.astype(np.float32, copy=False))

def _train_factor_policy(np, model: dict, hidden, factors, learning_rate: float, weight: float, action_id: int | None=None, gradients: dict[str, object] | None=None, probabilities=None, duration_index: int | None=None, action_payload: object | None=None) -> tuple[float, object]:
    step = max(0.0, min(0.05, float(learning_rate)))
    if action_id is None:
        matches = np.flatnonzero(np.all(model['action_factors'][:, :2] == np.asarray(factors)[:2], axis=1))
        action_id = int(matches[0]) if len(matches) else 0
    if probabilities is None:
        probabilities, _, _ = factorized_action_outputs_from_hidden(np, model, hidden)
    signed_weight = max(-100.0, min(100.0, float(weight)))
    magnitude = abs(signed_weight)
    local = gradients is None
    if local:
        gradients = _training_gradient_buffer(np, model)
    if magnitude <= 1e-12:
        return (0.0, np.zeros_like(np.asarray(hidden, dtype=np.float32)))
    direction = 1.0 if signed_weight > 0.0 else -1.0
    objective_loss, objective_gradient = signed_policy_objective(np, np.asarray(probabilities, dtype=np.float32)[None, :], np.asarray([int(action_id)], dtype=np.int64), np.asarray([direction], dtype=np.float32), with_gradient=True)
    action_gradient = np.asarray(objective_gradient[0], dtype=np.float32) * magnitude
    loss = float(objective_loss) * magnitude
    factor_matrix = model['action_factors'].astype(np.int64, copy=False)
    memorized_gradient = 0.3 * action_gradient
    factor_action_gradient = 0.7 / 4.0 * action_gradient
    hidden_gradient = model['policy_action_w'] @ memorized_gradient
    gradients['policy_action_w'] += np.outer(hidden, memorized_gradient).astype(np.float32)
    gradients['policy_action_b'] += memorized_gradient
    for w_key, b_key, column in (('policy_control_w', 'policy_control_b', 0), ('policy_mouse_w', 'policy_mouse_b', 1)):
        bucket_gradient = _factor_bucket_gradient(np, factor_matrix, column, factor_action_gradient, model[b_key].shape[0])
        gradients[w_key] += np.outer(hidden, bucket_gradient).astype(np.float32)
        gradients[b_key] += bucket_gradient
        hidden_gradient += model[w_key] @ bucket_gradient
    key_gradient = factor_action_gradient @ model['action_key_multihot']
    button_gradient = factor_action_gradient @ model['action_button_multihot']
    gradients['policy_key_w'] += np.outer(hidden, key_gradient).astype(np.float32)
    gradients['policy_key_b'] += key_gradient
    gradients['policy_button_w'] += np.outer(hidden, button_gradient).astype(np.float32)
    gradients['policy_button_b'] += button_gradient
    hidden_gradient += model['policy_key_w'] @ key_gradient
    hidden_gradient += model['policy_button_w'] @ button_gradient
    if signed_weight > 0.0 and duration_index is not None:
        kind = int(action_payload_factor_tuple(action_payload)[0]) if action_payload is not None else int(factor_matrix[int(action_id), 0])
        duration_target = max(0, min(DURATION_HEAD_SIZE - 1, int(duration_index)))
        duration_probabilities, _ = conditional_duration_outputs(np, model, hidden, kind)
        duration_gradient = duration_probabilities.copy()
        duration_gradient[duration_target] -= 1.0
        duration_gradient *= magnitude
        gradients['policy_duration_w'] += np.outer(hidden, duration_gradient).astype(np.float32)
        gradients['policy_duration_b'] += duration_gradient
        gradients['policy_duration_kind_b'][kind] += duration_gradient
        hidden_gradient += model['policy_duration_w'] @ duration_gradient
        loss += -math.log(max(1e-09, float(duration_probabilities[duration_target]))) * magnitude
    mouse_bucket = int(action_payload_factor_tuple(action_payload)[1]) if action_payload is not None else int(factor_matrix[int(action_id), 1])
    mouse_target = None
    if signed_weight > 0.0 and 1 <= mouse_bucket <= MOUSE_GRID_WIDTH * MOUSE_GRID_HEIGHT:
        index = mouse_bucket - 1
        mouse_target = np.asarray([2.0 * (index % MOUSE_GRID_WIDTH) / max(1, MOUSE_GRID_WIDTH - 1) - 1.0, 2.0 * (index // MOUSE_GRID_WIDTH) / max(1, MOUSE_GRID_HEIGHT - 1) - 1.0], dtype=np.float32)
    elif signed_weight > 0.0 and 577 <= mouse_bucket < 602:
        index = mouse_bucket - 577
        mouse_target = np.asarray([(index % 5 - 2) / 2.0, (index // 5 - 2) / 2.0], dtype=np.float32)
    if mouse_target is not None:
        mouse_prediction = np.tanh(np.asarray(hidden, dtype=np.float32) @ model['mouse_offset_w'] + model['mouse_offset_b'])
        mouse_error = (mouse_prediction - mouse_target) * (1.0 - mouse_prediction * mouse_prediction)
        mouse_error *= 0.2 * magnitude
        gradients['mouse_offset_w'] += np.outer(hidden, mouse_error).astype(np.float32)
        gradients['mouse_offset_b'] += mouse_error
        hidden_gradient += model['mouse_offset_w'] @ mouse_error
        loss += 0.1 * float(np.mean((mouse_prediction - mouse_target) ** 2)) * magnitude
    if signed_weight > 0.0 and action_payload is not None:
        structured_loss, structured_hidden_gradient = _structured_policy_head_supervision(np, model, hidden, action_payload, magnitude, gradients)
        loss += structured_loss
        hidden_gradient += structured_hidden_gradient
    if local:
        active = [gradient for gradient in gradients.values() if np.any(gradient)]
        if active:
            clip_gradients_by_global_norm(np, active, 6.0)
            for key, gradient in gradients.items():
                model[key] -= step * gradient
            _synchronize_quantized_conv_weights(np, model)
    return (float(loss), hidden_gradient.astype(np.float32, copy=False))

def _logsumexp_vector(np, values) -> float:
    values = np.asarray(values, dtype=np.float64)
    maximum = float(values.max(initial=0.0))
    return maximum + math.log(max(1e-12, float(np.exp(np.clip(values - maximum, -60.0, 30.0)).sum())))

def _train_factor_q(np, model: dict, hidden, action_id: int, target: float, learning_rate: float, sample_weight: float, gradients: dict[str, object] | None=None, q_values=None, cql_weight: float=0.02, duration_index: int | None=None, action_payload: object | None=None, hidden_is_adapted: bool=False) -> tuple[float, object]:
    step = max(0.0, min(0.02, float(learning_rate)))
    twin_q_values = factorized_twin_q_outputs_from_hidden(np, model, hidden, hidden_is_adapted=hidden_is_adapted)
    local = gradients is None
    if local:
        gradients = _training_gradient_buffer(np, model)
    factor_matrix = model['action_factors'].astype(np.int64, copy=False)
    structured_action = action_from_payload(action_payload) if action_payload is not None else None
    if structured_action is not None:
        structured_kind, structured_mouse, _ = action_payload_factor_tuple(action_payload)
    else:
        structured_kind = structured_mouse = 0
    hidden_gradient = np.zeros_like(hidden, dtype=np.float32)
    td_losses = []
    cql_losses = []
    targets = np.asarray(target, dtype=np.float32).reshape(-1)
    if targets.size == 1:
        targets = np.repeat(targets, VALUE_HEAD_COUNT)
    if targets.size != VALUE_HEAD_COUNT or not np.isfinite(targets).all():
        raise ValueError('critic 训练目标无效')
    ensemble_scale = 1.0 / (VALUE_HEAD_COUNT * Q_TWIN_COUNT)
    for twin in range(Q_TWIN_COUNT):
        for head in range(VALUE_HEAD_COUNT):
            values = np.asarray(twin_q_values[twin, head], dtype=np.float32)
            head_target = float(targets[head])
            error = float(values[int(action_id)] - head_target)
            clipped_error = max(-3.0, min(3.0, error))
            bootstrap_weight = 0.9 + 0.1 * float((int(action_id) + twin + head) % 2)
            action_gradient = np.zeros(len(values), dtype=np.float32)
            action_gradient[int(action_id)] = clipped_error * max(0.0, float(sample_weight)) * ensemble_scale * bootstrap_weight
            conservative_gradient = _softmax_vector(np, values).astype(np.float32)
            conservative_gradient[int(action_id)] -= 1.0
            conservative_scale = 0.0 if head == SAFETY_CRITIC else max(0.0, float(cql_weight))
            conservative_gradient *= conservative_scale * ensemble_scale
            action_gradient += conservative_gradient
            td_losses.append(0.5 * clipped_error * clipped_error)
            cql_losses.append(_logsumexp_vector(np, values) - float(values[int(action_id)]))
            memorized_gradient = 0.3 * action_gradient
            factor_action_gradient = np.zeros_like(action_gradient) if structured_action is not None else 0.7 * action_gradient
            gradients['q_action_w'][twin, head] += np.outer(hidden, memorized_gradient).astype(np.float32)
            gradients['q_action_b'][twin, head] += memorized_gradient
            hidden_gradient += model['q_action_w'][twin, head] @ memorized_gradient
            for w_key, b_key, column in (('q_control_w', 'q_control_b', 0), ('q_mouse_w', 'q_mouse_b', 1)):
                bucket_gradient = _factor_bucket_gradient(np, factor_matrix, column, factor_action_gradient / 4.0, model[b_key].shape[-1])
                gradients[w_key][twin, head] += np.outer(hidden, bucket_gradient).astype(np.float32)
                gradients[b_key][twin, head] += bucket_gradient
                hidden_gradient += model[w_key][twin, head] @ bucket_gradient
            key_gradient = factor_action_gradient / 4.0 @ model['action_key_multihot']
            button_gradient = factor_action_gradient / 4.0 @ model['action_button_multihot']
            gradients['q_key_w'][twin, head] += np.outer(hidden, key_gradient).astype(np.float32)
            gradients['q_key_b'][twin, head] += key_gradient
            gradients['q_button_w'][twin, head] += np.outer(hidden, button_gradient).astype(np.float32)
            gradients['q_button_b'][twin, head] += button_gradient
            hidden_gradient += model['q_key_w'][twin, head] @ key_gradient
            hidden_gradient += model['q_button_w'][twin, head] @ button_gradient
            if structured_action is not None:
                direct_scale = 0.18 * max(0.0, float(sample_weight)) * ensemble_scale * bootstrap_weight
                for w_key, b_key, bucket in (('q_control_w', 'q_control_b', int(structured_kind)), ('q_mouse_w', 'q_mouse_b', int(structured_mouse))):
                    head_values = hidden @ model[w_key][twin, head] + model[b_key][twin, head]
                    direct_error = max(-3.0, min(3.0, float(head_values[bucket]) - head_target))
                    direct_gradient = np.zeros_like(head_values, dtype=np.float32)
                    direct_gradient[bucket] = direct_error * direct_scale
                    gradients[w_key][twin, head] += np.outer(hidden, direct_gradient).astype(np.float32)
                    gradients[b_key][twin, head] += direct_gradient
                    hidden_gradient += model[w_key][twin, head] @ direct_gradient
                    td_losses.append(0.5 * direct_error * direct_error)
                for w_key, b_key, indices in (('q_key_w', 'q_key_b', [int(v) for v in structured_action['keys'] if 0 <= int(v) < KEY_HEAD_SIZE]), ('q_button_w', 'q_button_b', [i for i, name in enumerate(('left', 'right', 'middle', 'x1', 'x2')) if name in structured_action['buttons']])):
                    if not indices:
                        continue
                    head_values = hidden @ model[w_key][twin, head] + model[b_key][twin, head]
                    direct_gradient = np.zeros_like(head_values, dtype=np.float32)
                    for bucket in indices:
                        direct_error = max(-3.0, min(3.0, float(head_values[bucket]) - head_target))
                        direct_gradient[bucket] += direct_error * direct_scale / math.sqrt(len(indices))
                        td_losses.append(0.5 * direct_error * direct_error)
                    gradients[w_key][twin, head] += np.outer(hidden, direct_gradient).astype(np.float32)
                    gradients[b_key][twin, head] += direct_gradient
                    hidden_gradient += model[w_key][twin, head] @ direct_gradient
            if duration_index is not None:
                kind = int(structured_kind) if structured_action is not None else int(factor_matrix[int(action_id), 0])
                duration_target = max(0, min(DURATION_HEAD_SIZE - 1, int(duration_index)))
                duration_values = hidden @ model['q_duration_w'][twin, head] + model['q_duration_b'][twin, head] + model['q_duration_kind_b'][twin, head, kind]
                duration_error = max(-3.0, min(3.0, float(duration_values[duration_target]) - head_target))
                duration_gradient = np.zeros(DURATION_HEAD_SIZE, dtype=np.float32)
                duration_gradient[duration_target] = duration_error * max(0.0, float(sample_weight)) * ensemble_scale * bootstrap_weight
                gradients['q_duration_w'][twin, head] += np.outer(hidden, duration_gradient).astype(np.float32)
                gradients['q_duration_b'][twin, head] += duration_gradient
                gradients['q_duration_kind_b'][twin, head, kind] += duration_gradient
                hidden_gradient += model['q_duration_w'][twin, head] @ duration_gradient
                td_losses.append(0.5 * duration_error * duration_error)
    loss = float(sum(td_losses) / max(1, len(td_losses)) + max(0.0, float(cql_weight)) * sum(cql_losses) / max(1, len(cql_losses)))
    if local:
        active = [gradient for gradient in gradients.values() if np.any(gradient)]
        if active:
            clip_gradients_by_global_norm(np, active, 6.0)
            for key, gradient in gradients.items():
                model[key] -= step * gradient
            _synchronize_quantized_conv_weights(np, model)
    return (loss, hidden_gradient.astype(np.float32, copy=False))

def _train_value_head(np, model: dict, hidden, q_data: float, value: float, expectile: float, sample_weight: float, gradients: dict[str, object]) -> tuple[float, object]:
    difference = float(q_data) - float(value)
    expectile_weight = float(expectile) if difference >= 0.0 else 1.0 - float(expectile)
    weight = expectile_weight * max(0.0, float(sample_weight))
    value_gradient = -2.0 * weight * difference
    gradients['value_w'][:, 0] += hidden * value_gradient
    gradients['value_b'][0] += value_gradient
    hidden_gradient = model['value_w'][:, 0] * value_gradient
    return (float(weight * difference * difference), hidden_gradient.astype(np.float32, copy=False))

def _train_safety_head(np, model: dict, hidden, target: float, sample_weight: float, gradients: dict[str, object]) -> tuple[float, object]:
    target_value = max(0.0, min(1.0, float(target)))
    weight = max(0.0, float(sample_weight))
    prediction = predict_safety_probability(np, model, hidden)
    logit_gradient = (prediction - target_value) * weight
    gradients['safety_w'][:, 0] += np.asarray(hidden, dtype=np.float32) * logit_gradient
    gradients['safety_b'][0] += logit_gradient
    hidden_gradient = model['safety_w'][:, 0] * logit_gradient
    loss = -weight * (target_value * math.log(max(1e-09, prediction)) + (1.0 - target_value) * math.log(max(1e-09, 1.0 - prediction)))
    return (float(loss), hidden_gradient.astype(np.float32, copy=False))

def structured_world_target_from_state(np, model: dict, state) -> dict | None:
    if state is None:
        return None
    try:
        frames, _, _ = decode_temporal_state(state)
        payload = _perception_frame_input(np, normalize_feature_bytes(frames[-1]))
        _, tracks, hud = game_perception_features(np, model, payload, None)
        return {'slots': np.asarray(tracks['slots'], dtype=np.float32).copy(), 'hud': np.asarray(hud['hud_token'], dtype=np.float32).copy(), 'events': dict(hud.get('event_probabilities', {}))}
    except Exception:
        return None

def _train_structured_world_heads(np, model: dict, latents, structured_target: dict | None, sample_weight: float, gradients: dict[str, object]) -> tuple[float, object]:
    target = _runtime_module('world_model').normalize_structured_target(np, structured_target)
    latent_values = np.asarray(latents, dtype=np.float32)
    if target is None:
        return (0.0, np.zeros_like(latent_values))
    slot_target = np.asarray(target['slots'], dtype=np.float32).reshape(-1)
    hud_target = np.asarray(target['hud'], dtype=np.float32)
    event_target = np.asarray(target['events'], dtype=np.float32)
    latent_gradient = np.zeros_like(latent_values)
    loss = 0.0
    member_weight = max(0.0, min(4.0, float(sample_weight))) / WORLD_MODEL_MEMBERS
    for member in range(WORLD_MODEL_MEMBERS):
        latent = latent_values[member]
        slot_prediction = np.tanh(latent @ model['world_slot_w'][member] + model['world_slot_b'][member])
        slot_error = slot_prediction - slot_target
        slot_out_gradient = slot_error * (1.0 - slot_prediction * slot_prediction) * (0.35 * member_weight / slot_target.size)
        gradients['world_slot_w'][member] += np.outer(latent, slot_out_gradient)
        gradients['world_slot_b'][member] += slot_out_gradient
        latent_gradient[member] += model['world_slot_w'][member] @ slot_out_gradient
        loss += 0.35 * member_weight * float(np.mean(slot_error * slot_error))
        hud_prediction = np.tanh(latent @ model['world_hud_w'][member] + model['world_hud_b'][member])
        hud_error = hud_prediction - hud_target
        hud_out_gradient = hud_error * (1.0 - hud_prediction * hud_prediction) * (0.2 * member_weight / hud_target.size)
        gradients['world_hud_w'][member] += np.outer(latent, hud_out_gradient)
        gradients['world_hud_b'][member] += hud_out_gradient
        latent_gradient[member] += model['world_hud_w'][member] @ hud_out_gradient
        loss += 0.2 * member_weight * float(np.mean(hud_error * hud_error))
        event_prediction = _sigmoid(np, latent @ model['world_event_w'][member] + model['world_event_b'][member])
        event_error = event_prediction - event_target
        event_out_gradient = event_error * (0.3 * member_weight / event_target.size)
        gradients['world_event_w'][member] += np.outer(latent, event_out_gradient)
        gradients['world_event_b'][member] += event_out_gradient
        latent_gradient[member] += model['world_event_w'][member] @ event_out_gradient
        loss += -0.3 * member_weight * float(np.mean(event_target * np.log(np.maximum(event_prediction, 1e-08)) + (1.0 - event_target) * np.log(np.maximum(1.0 - event_prediction, 1e-08))))
    return (float(loss), latent_gradient.astype(np.float32, copy=False))

def train_world_model_transition(np, model: dict, hidden, next_hidden, action_id: int, reward_targets, done: bool, sample_weight: float, gradients: dict[str, object], target_model: dict | None=None, target_next_hidden=None, duration_index: int=DURATION_HEAD_SIZE // 2, action_payload=None, structured_target: dict | None=None) -> tuple[float, object]:
    action = max(0, min(len(model['action_embedding']) - 1, int(action_id)))
    duration = max(0, min(DURATION_HEAD_SIZE - 1, int(duration_index)))
    hidden_value = np.asarray(hidden, dtype=np.float32)
    weight = max(0.0, min(4.0, float(sample_weight)))
    action_embedding = structured_action_embedding(np, model, action, action_payload)
    duration_embedding = model['duration_embedding'][duration]
    targets = np.asarray(reward_targets, dtype=np.float32).reshape(-1)
    if targets.shape != (VALUE_HEAD_COUNT,) or not np.isfinite(targets).all():
        raise ValueError('世界模型回报目标无效')
    targets[TASK_CRITIC] = np.clip(targets[TASK_CRITIC], -1.0, 1.0)
    targets[EXPLORATION_CRITIC] = np.clip(targets[EXPLORATION_CRITIC], 0.0, 1.0)
    targets[SAFETY_CRITIC] = np.clip(targets[SAFETY_CRITIC], 0.0, 2.0)
    latent_target_model = target_model if target_model is not None else model
    latent_target_hidden = target_next_hidden if target_next_hidden is not None else next_hidden
    target_latents = world_model_latent(np, latent_target_model, latent_target_hidden) if not done and latent_target_hidden is not None else None
    hidden_gradient = np.zeros_like(hidden_value, dtype=np.float32)
    action_gradient_total = np.zeros_like(action_embedding, dtype=np.float32)
    duration_gradient_total = np.zeros_like(duration_embedding, dtype=np.float32)
    total_loss = 0.0
    continuation_target = 0.0 if done else 1.0
    member_scale = 1.0 / WORLD_MODEL_MEMBERS
    epsilon_values = world_stochastic_sample(np, action, duration, int(model.get('world_training_steps', 0)))
    for member in range(WORLD_MODEL_MEMBERS):
        bootstrap_weight = weight * (0.9 + 0.05 * ((action + duration + member + int(model.get('world_training_steps', 0))) % 3))
        encoder_w = model['world_encoder_w'][member]
        latent_pre = hidden_value @ encoder_w + model['world_encoder_b'][member]
        latent = np.tanh(latent_pre)
        dynamics_pre = latent @ model['world_dynamics_w'][member] + action_embedding @ model['world_dynamics_action_w'][member] + duration_embedding @ model['world_dynamics_duration_w'][member] + model['world_dynamics_b'][member]
        deterministic = np.tanh(dynamics_pre)
        prior_parameters = deterministic @ model['world_prior_state_w'][member] + action_embedding @ model['world_prior_action_w'][member] + duration_embedding @ model['world_prior_duration_w'][member] + model['world_prior_b'][member]
        prior_mean = np.clip(prior_parameters[:WORLD_STOCHASTIC_SIZE], -6.0, 6.0)
        prior_log_std = np.clip(prior_parameters[WORLD_STOCHASTIC_SIZE:], RSSM_MIN_LOG_STD, RSSM_MAX_LOG_STD)
        prior_std = np.exp(prior_log_std).astype(np.float32)
        posterior_parameters = None
        if target_latents is not None:
            posterior_parameters = deterministic @ model['world_posterior_state_w'][member] + target_latents[member] @ model['world_posterior_observation_w'][member] + model['world_posterior_b'][member]
            posterior_mean = np.clip(posterior_parameters[:WORLD_STOCHASTIC_SIZE], -6.0, 6.0)
            posterior_log_std = np.clip(posterior_parameters[WORLD_STOCHASTIC_SIZE:], RSSM_MIN_LOG_STD, RSSM_MAX_LOG_STD)
            posterior_std = np.exp(posterior_log_std).astype(np.float32)
            stochastic_state = posterior_mean + posterior_std * epsilon_values[member]
        else:
            posterior_mean = prior_mean
            posterior_log_std = prior_log_std
            posterior_std = prior_std
            stochastic_state = prior_mean
        stochastic_pre = deterministic + stochastic_state @ model['world_stochastic_w'][member]
        predicted_latent = np.tanh(stochastic_pre)
        predicted_rewards = predicted_latent @ model['world_reward_w'][member] + action_embedding @ model['world_reward_action_w'][member] + duration_embedding @ model['world_reward_duration_w'][member] + model['world_reward_b'][member]
        reward_error = np.clip(predicted_rewards - targets, -3.0, 3.0)
        reward_gradient = reward_error * (bootstrap_weight * member_scale / VALUE_HEAD_COUNT)
        gradients['world_reward_w'][member] += np.outer(predicted_latent, reward_gradient).astype(np.float32)
        gradients['world_reward_action_w'][member] += np.outer(action_embedding, reward_gradient).astype(np.float32)
        gradients['world_reward_duration_w'][member] += np.outer(duration_embedding, reward_gradient).astype(np.float32)
        gradients['world_reward_b'][member] += reward_gradient
        predicted_gradient = model['world_reward_w'][member] @ reward_gradient
        action_gradient = model['world_reward_action_w'][member] @ reward_gradient
        duration_gradient = model['world_reward_duration_w'][member] @ reward_gradient
        continuation_probability = float(_sigmoid(np, predicted_latent @ model['world_continuation_w'][member] + model['world_continuation_b'][member])[0])
        continuation_gradient = (continuation_probability - continuation_target) * bootstrap_weight * 0.5 * member_scale
        gradients['world_continuation_w'][member, :, 0] += predicted_latent * continuation_gradient
        gradients['world_continuation_b'][member, 0] += continuation_gradient
        predicted_gradient += model['world_continuation_w'][member, :, 0] * continuation_gradient
        dynamics_loss = 0.0
        if target_latents is not None:
            dynamics_error = predicted_latent - target_latents[member]
            predicted_gradient += dynamics_error * (bootstrap_weight * member_scale / model_world_latent_size(model))
            dynamics_loss = 0.5 * bootstrap_weight * float(np.mean(dynamics_error * dynamics_error))
        projection_loss = 0.0
        if not done and next_hidden is not None:
            projected_pre = predicted_latent @ model['world_latent_to_hidden_w'][member] + model['world_latent_to_hidden_b'][member]
            projected_hidden = np.tanh(projected_pre)
            projection_error = projected_hidden - np.asarray(next_hidden, dtype=np.float32)
            projection_gradient = projection_error * (1.0 - projected_hidden * projected_hidden) * (bootstrap_weight * member_scale / max(1, projected_hidden.size))
            gradients['world_latent_to_hidden_w'][member] += np.outer(predicted_latent, projection_gradient).astype(np.float32)
            gradients['world_latent_to_hidden_b'][member] += projection_gradient
            predicted_gradient += model['world_latent_to_hidden_w'][member] @ projection_gradient
            projection_loss = 0.5 * bootstrap_weight * float(np.mean(projection_error * projection_error))
        stochastic_pre_gradient = predicted_gradient * (1.0 - predicted_latent * predicted_latent)
        gradients['world_stochastic_w'][member] += np.outer(stochastic_state, stochastic_pre_gradient).astype(np.float32)
        stochastic_gradient = model['world_stochastic_w'][member] @ stochastic_pre_gradient
        deterministic_gradient = stochastic_pre_gradient.copy()
        prior_gradient = np.zeros(2 * WORLD_STOCHASTIC_SIZE, dtype=np.float32)
        posterior_gradient = np.zeros_like(prior_gradient)
        kl_loss = 0.0
        if posterior_parameters is not None:
            posterior_gradient[:WORLD_STOCHASTIC_SIZE] += stochastic_gradient
            posterior_gradient[WORLD_STOCHASTIC_SIZE:] += stochastic_gradient * posterior_std * epsilon_values[member]
            difference = posterior_mean - prior_mean
            prior_variance = np.maximum(prior_std * prior_std, 1e-08)
            posterior_variance = posterior_std * posterior_std
            divergence = prior_log_std - posterior_log_std + (posterior_variance + difference * difference) / (2.0 * prior_variance) - 0.5
            mean_kl = float(np.mean(np.maximum(0.0, divergence)))
            kl_loss = RSSM_KL_WEIGHT * bootstrap_weight * max(0.0, mean_kl - RSSM_KL_FREE_NATS)
            if math.isfinite(mean_kl):
                kl_scale = RSSM_KL_WEIGHT * bootstrap_weight * member_scale / WORLD_STOCHASTIC_SIZE
                posterior_gradient[:WORLD_STOCHASTIC_SIZE] += difference / prior_variance * kl_scale
                posterior_gradient[WORLD_STOCHASTIC_SIZE:] += (-1.0 + posterior_variance / prior_variance) * kl_scale
                prior_gradient[:WORLD_STOCHASTIC_SIZE] -= difference / prior_variance * kl_scale
                prior_gradient[WORLD_STOCHASTIC_SIZE:] += (1.0 - (posterior_variance + difference * difference) / prior_variance) * kl_scale
            gradients['world_posterior_state_w'][member] += np.outer(deterministic, posterior_gradient)
            gradients['world_posterior_observation_w'][member] += np.outer(target_latents[member], posterior_gradient)
            gradients['world_posterior_b'][member] += posterior_gradient
            deterministic_gradient += model['world_posterior_state_w'][member] @ posterior_gradient
        else:
            prior_gradient[:WORLD_STOCHASTIC_SIZE] += stochastic_gradient
        gradients['world_prior_state_w'][member] += np.outer(deterministic, prior_gradient)
        gradients['world_prior_action_w'][member] += np.outer(action_embedding, prior_gradient)
        gradients['world_prior_duration_w'][member] += np.outer(duration_embedding, prior_gradient)
        gradients['world_prior_b'][member] += prior_gradient
        deterministic_gradient += model['world_prior_state_w'][member] @ prior_gradient
        action_gradient += model['world_prior_action_w'][member] @ prior_gradient
        duration_gradient += model['world_prior_duration_w'][member] @ prior_gradient
        dynamics_gradient = deterministic_gradient * (1.0 - deterministic * deterministic)
        gradients['world_dynamics_w'][member] += np.outer(latent, dynamics_gradient).astype(np.float32)
        gradients['world_dynamics_action_w'][member] += np.outer(action_embedding, dynamics_gradient).astype(np.float32)
        gradients['world_dynamics_duration_w'][member] += np.outer(duration_embedding, dynamics_gradient).astype(np.float32)
        gradients['world_dynamics_b'][member] += dynamics_gradient
        latent_gradient = model['world_dynamics_w'][member] @ dynamics_gradient
        action_gradient += model['world_dynamics_action_w'][member] @ dynamics_gradient
        duration_gradient += model['world_dynamics_duration_w'][member] @ dynamics_gradient
        encoder_gradient = latent_gradient * (1.0 - latent * latent)
        gradients['world_encoder_w'][member] += np.outer(hidden_value, encoder_gradient).astype(np.float32)
        gradients['world_encoder_b'][member] += encoder_gradient
        action_gradient_total += action_gradient
        duration_gradient_total += duration_gradient
        hidden_gradient += encoder_w @ encoder_gradient
        reward_loss = 0.5 * bootstrap_weight * float(np.mean(reward_error * reward_error))
        continuation_loss = -0.5 * bootstrap_weight * (continuation_target * math.log(max(1e-09, continuation_probability)) + (1.0 - continuation_target) * math.log(max(1e-09, 1.0 - continuation_probability)))
        total_loss += (dynamics_loss + projection_loss + reward_loss + continuation_loss + kl_loss) * member_scale
    if structured_target is not None:
        structured_latents = world_model_latent(np, model, next_hidden if next_hidden is not None else hidden_value)
        structured_loss, structured_latent_gradient = _train_structured_world_heads(np, model, structured_latents, structured_target, weight, gradients)
        total_loss += structured_loss
        if next_hidden is None:
            for member in range(WORLD_MODEL_MEMBERS):
                encoder_gradient = structured_latent_gradient[member] * (1.0 - structured_latents[member] * structured_latents[member])
                gradients['world_encoder_w'][member] += np.outer(hidden_value, encoder_gradient)
                gradients['world_encoder_b'][member] += encoder_gradient
                hidden_gradient += model['world_encoder_w'][member] @ encoder_gradient
    gradients['action_embedding'][action] += action_gradient_total
    gradients['duration_embedding'][duration] += duration_gradient_total
    model['world_training_steps'] = int(model.get('world_training_steps', 0)) + 1
    return (float(total_loss), hidden_gradient.astype(np.float32, copy=False))

def train_world_model_overshooting(np, model: dict, start_hidden, rollout: list[tuple[dict, object | None]], sample_weight: float, gradients: dict[str, object], target_model: dict) -> tuple[float, object]:
    items = list(rollout)[:WORLD_MODEL_OVERSHOOT_MAX_STEPS]
    if len(items) < WORLD_MODEL_OVERSHOOT_MIN_STEPS:
        return (0.0, np.zeros_like(np.asarray(start_hidden, dtype=np.float32)))
    checkpoint_weights = {5: 1.0, 8: 0.8, 12: 0.6, 16: 0.45, 20: 0.35}
    base_weight = max(0.0, min(2.0, float(sample_weight)))
    latent = world_model_latent(np, model, start_hidden)
    caches: list[dict] = []
    total_loss = 0.0
    for offset, (record, target_next_hidden) in enumerate(items):
        action = max(0, min(len(model['action_embedding']) - 1, int(record['action'])))
        duration = _record_duration_index(record)
        action_payload = record.get('action_payload')
        action_embedding = structured_action_embedding(np, model, action, action_payload)
        duration_embedding = model['duration_embedding'][duration]
        deterministic = rssm_deterministic_transition(np, model, latent, action, duration, action_payload)
        prior_mean, prior_std, _ = rssm_prior(np, model, deterministic, action, duration, action_payload)
        predicted_latent = rssm_latent_from_state(np, model, deterministic, prior_mean)
        predicted_rewards = (np.einsum('ml,mlv->mv', predicted_latent, model['world_reward_w'], optimize=True) + np.einsum('a,mav->mv', action_embedding, model['world_reward_action_w'], optimize=True) + np.einsum('d,mdv->mv', duration_embedding, model['world_reward_duration_w'], optimize=True) + model['world_reward_b']).astype(np.float32)
        continuation_probability = _sigmoid(np, np.einsum('ml,mlq->mq', predicted_latent, model['world_continuation_w'], optimize=True) + model['world_continuation_b'])[:, 0].astype(np.float32)
        done_target = 1.0 if bool(record.get('done', False)) else 0.0
        continuation_target = 1.0 - done_target
        reward_targets = np.asarray((smooth_reward(float(record.get('task_reward', 0.0))), max(0.0, min(1.0, float(record.get('exploration_reward', 0.0)))), max(0.0, min(2.0, float(record.get('safety_penalty', 0.0))))), dtype=np.float32)
        target_latent = world_model_latent(np, target_model, target_next_hidden) if target_next_hidden is not None and (not done_target) else None
        horizon = offset + 1
        horizon_weight = base_weight * checkpoint_weights.get(horizon, 0.0)
        if horizon_weight > 0.0:
            reward_error = predicted_rewards - reward_targets[None, :]
            total_loss += 0.35 * horizon_weight * float(np.mean(reward_error * reward_error))
            total_loss += -0.15 * horizon_weight * float(np.mean(continuation_target * np.log(np.maximum(continuation_probability, 1e-09)) + (1.0 - continuation_target) * np.log(np.maximum(1.0 - continuation_probability, 1e-09))))
            if target_latent is not None:
                latent_error = predicted_latent - target_latent
                total_loss += 0.5 * horizon_weight * float(np.mean(latent_error * latent_error))
        caches.append({'latent': latent, 'deterministic': deterministic, 'prior_mean': prior_mean, 'prior_std': prior_std, 'predicted_latent': predicted_latent, 'predicted_rewards': predicted_rewards, 'continuation_probability': continuation_probability, 'continuation_target': continuation_target, 'reward_targets': reward_targets, 'target_latent': target_latent, 'action': action, 'duration': duration, 'action_embedding': action_embedding, 'duration_embedding': duration_embedding, 'weight': horizon_weight})
        latent = predicted_latent
        if done_target:
            break
    if len(caches) < WORLD_MODEL_OVERSHOOT_MIN_STEPS or not any((float(cache['weight']) > 0.0 for cache in caches)):
        return (0.0, np.zeros_like(np.asarray(start_hidden, dtype=np.float32)))
    carry = np.zeros((WORLD_MODEL_MEMBERS, model_world_latent_size(model)), dtype=np.float32)
    for cache in reversed(caches):
        previous_carry = np.zeros_like(carry)
        action_gradient_total = np.zeros_like(cache['action_embedding'])
        duration_gradient_total = np.zeros_like(cache['duration_embedding'])
        loss_weight = float(cache['weight'])
        for member in range(WORLD_MODEL_MEMBERS):
            next_gradient = carry[member].copy()
            action_gradient = np.zeros_like(cache['action_embedding'])
            duration_gradient = np.zeros_like(cache['duration_embedding'])
            if loss_weight > 0.0:
                reward_error = np.clip(cache['predicted_rewards'][member] - cache['reward_targets'], -3.0, 3.0)
                reward_gradient = reward_error * (0.35 * loss_weight / (WORLD_MODEL_MEMBERS * VALUE_HEAD_COUNT))
                gradients['world_reward_w'][member] += np.outer(cache['predicted_latent'][member], reward_gradient).astype(np.float32)
                gradients['world_reward_action_w'][member] += np.outer(cache['action_embedding'], reward_gradient).astype(np.float32)
                gradients['world_reward_duration_w'][member] += np.outer(cache['duration_embedding'], reward_gradient).astype(np.float32)
                gradients['world_reward_b'][member] += reward_gradient
                next_gradient += model['world_reward_w'][member] @ reward_gradient
                action_gradient += model['world_reward_action_w'][member] @ reward_gradient
                duration_gradient += model['world_reward_duration_w'][member] @ reward_gradient
                continuation_gradient = (cache['continuation_probability'][member] - cache['continuation_target']) * (0.15 * loss_weight / WORLD_MODEL_MEMBERS)
                gradients['world_continuation_w'][member, :, 0] += cache['predicted_latent'][member] * continuation_gradient
                gradients['world_continuation_b'][member, 0] += continuation_gradient
                next_gradient += model['world_continuation_w'][member, :, 0] * continuation_gradient
                if cache['target_latent'] is not None:
                    next_gradient += (cache['predicted_latent'][member] - cache['target_latent'][member]) * (0.5 * loss_weight / (WORLD_MODEL_MEMBERS * model_world_latent_size(model)))
            stochastic_pre_gradient = next_gradient * (1.0 - cache['predicted_latent'][member] ** 2)
            deterministic_gradient = stochastic_pre_gradient.copy()
            prior_mean_gradient = model['world_stochastic_w'][member] @ stochastic_pre_gradient
            prior_mean_mask = (np.abs(cache['prior_mean'][member]) < 5.999).astype(np.float32)
            prior_parameter_gradient = np.zeros(2 * WORLD_STOCHASTIC_SIZE, dtype=np.float32)
            prior_parameter_gradient[:WORLD_STOCHASTIC_SIZE] = prior_mean_gradient * prior_mean_mask
            gradients['world_prior_state_w'][member] += np.outer(cache['deterministic'][member], prior_parameter_gradient).astype(np.float32)
            gradients['world_prior_action_w'][member] += np.outer(cache['action_embedding'], prior_parameter_gradient).astype(np.float32)
            gradients['world_prior_duration_w'][member] += np.outer(cache['duration_embedding'], prior_parameter_gradient).astype(np.float32)
            gradients['world_prior_b'][member] += prior_parameter_gradient
            deterministic_gradient += model['world_prior_state_w'][member] @ prior_parameter_gradient
            action_gradient += model['world_prior_action_w'][member] @ prior_parameter_gradient
            duration_gradient += model['world_prior_duration_w'][member] @ prior_parameter_gradient
            dynamics_gradient = deterministic_gradient * (1.0 - cache['deterministic'][member] ** 2)
            gradients['world_dynamics_w'][member] += np.outer(cache['latent'][member], dynamics_gradient).astype(np.float32)
            gradients['world_dynamics_action_w'][member] += np.outer(cache['action_embedding'], dynamics_gradient).astype(np.float32)
            gradients['world_dynamics_duration_w'][member] += np.outer(cache['duration_embedding'], dynamics_gradient).astype(np.float32)
            gradients['world_dynamics_b'][member] += dynamics_gradient
            previous_carry[member] = model['world_dynamics_w'][member] @ dynamics_gradient
            action_gradient += model['world_dynamics_action_w'][member] @ dynamics_gradient
            duration_gradient += model['world_dynamics_duration_w'][member] @ dynamics_gradient
            action_gradient_total += action_gradient
            duration_gradient_total += duration_gradient
        gradients['action_embedding'][cache['action']] += action_gradient_total
        gradients['duration_embedding'][cache['duration']] += duration_gradient_total
        carry = previous_carry
    start_hidden_value = np.asarray(start_hidden, dtype=np.float32)
    initial_latent = world_model_latent(np, model, start_hidden_value)
    hidden_gradient = np.zeros_like(start_hidden_value)
    for member in range(WORLD_MODEL_MEMBERS):
        encoder_gradient = carry[member] * (1.0 - initial_latent[member] ** 2)
        gradients['world_encoder_w'][member] += np.outer(start_hidden_value, encoder_gradient).astype(np.float32)
        gradients['world_encoder_b'][member] += encoder_gradient
        hidden_gradient += model['world_encoder_w'][member] @ encoder_gradient
    model['world_training_steps'] = int(model.get('world_training_steps', 0)) + len(caches)
    normalizer = sum((checkpoint_weights[step] for step in checkpoint_weights if step <= len(caches)))
    return (float(total_loss / max(1e-06, normalizer)), hidden_gradient.astype(np.float32, copy=False))

def _optimizer_layout(np, model: dict) -> tuple[list[str], object]:
    keys = [key for key in _TRAINABLE_PARAMETER_KEYS if key in model and isinstance(model[key], np.ndarray) and np.issubdtype(model[key].dtype, np.floating)]
    offsets = [0]
    for key in keys:
        offsets.append(offsets[-1] + int(model[key].size))
    return (keys, np.asarray(offsets, dtype=np.int64))

def _reset_optimizer_state(np, model: dict) -> None:
    keys, offsets = _optimizer_layout(np, model)
    total = int(offsets[-1]) if len(offsets) else 0
    model['optimizer_step'] = 0
    model['optimizer_schedule_step'] = 0
    model['optimizer_keys'] = list(keys)
    model['optimizer_offsets'] = offsets
    model['optimizer_m'] = np.zeros(total, dtype=np.float32)
    model['optimizer_v'] = np.zeros(total, dtype=np.float32)

def _ensure_optimizer_state(np, model: dict) -> None:
    keys, offsets = _optimizer_layout(np, model)
    total = int(offsets[-1]) if len(offsets) else 0
    stored_keys = [str(value) for value in model.get('optimizer_keys', [])]
    stored_offsets = np.asarray(model.get('optimizer_offsets', np.zeros(0)), dtype=np.int64).reshape(-1)
    moments = np.asarray(model.get('optimizer_m', np.zeros(0)), dtype=np.float32).reshape(-1)
    velocities = np.asarray(model.get('optimizer_v', np.zeros(0)), dtype=np.float32).reshape(-1)
    if stored_keys != keys or stored_offsets.shape != offsets.shape or (not np.array_equal(stored_offsets, offsets)) or (moments.shape != (total,)) or (velocities.shape != (total,)) or (not np.isfinite(moments).all()) or (not np.isfinite(velocities).all()):
        _reset_optimizer_state(np, model)
        return
    model['optimizer_keys'] = stored_keys
    model['optimizer_offsets'] = stored_offsets.copy()
    model['optimizer_m'] = moments.copy()
    model['optimizer_v'] = velocities.copy()
    model['optimizer_step'] = max(0, int(model.get('optimizer_step', 0)))
    model['optimizer_schedule_step'] = max(0, int(model.get('optimizer_schedule_step', model['optimizer_step'])))

def _scheduled_learning_rate(base_learning_rate: float, schedule_step: int, warmup_steps: int, cosine_steps: int) -> float:
    base = max(1e-08, min(0.1, float(base_learning_rate)))
    step = max(1, int(schedule_step))
    warmup = max(1, int(warmup_steps))
    decay = max(16, int(cosine_steps))
    warmup_scale = min(1.0, step / warmup)
    progress = max(0.0, min(1.0, (step - warmup) / decay))
    cosine_scale = 0.1 + 0.9 * 0.5 * (1.0 + math.cos(math.pi * progress))
    return base * warmup_scale * cosine_scale

def _adam_apply(np, model: dict, gradients: dict[str, object], learning_rate: float, warmup_steps: int=OPTIMIZER_WARMUP_STEPS_DEFAULT, cosine_steps: int=OPTIMIZER_COSINE_STEPS_DEFAULT, weight_decay: float=OPTIMIZER_WEIGHT_DECAY_DEFAULT) -> float:
    _ensure_optimizer_state(np, model)
    model['optimizer_step'] = int(model.get('optimizer_step', 0)) + 1
    model['optimizer_schedule_step'] = int(model.get('optimizer_schedule_step', 0)) + 1
    step = int(model['optimizer_step'])
    schedule_step = int(model['optimizer_schedule_step'])
    effective_lr = _scheduled_learning_rate(learning_rate, schedule_step, warmup_steps, cosine_steps)
    beta1 = 0.9
    beta2 = 0.999
    epsilon = 1e-08
    decay = max(0.0, min(0.1, float(weight_decay)))
    key_index = {key: index for index, key in enumerate(model['optimizer_keys'])}
    offsets = model['optimizer_offsets']
    flat_m = model['optimizer_m']
    flat_v = model['optimizer_v']
    for key, gradient in gradients.items():
        index = key_index.get(key)
        if index is None or not np.any(gradient):
            continue
        parameter = model[key]
        start = int(offsets[index])
        end = int(offsets[index + 1])
        moment = flat_m[start:end].reshape(parameter.shape)
        velocity = flat_v[start:end].reshape(parameter.shape)
        gradient_value = np.asarray(gradient, dtype=np.float32)
        moment *= beta1
        moment += (1.0 - beta1) * gradient_value
        velocity *= beta2
        velocity += (1.0 - beta2) * gradient_value * gradient_value
        corrected_m = moment / (1.0 - beta1 ** step)
        corrected_v = velocity / (1.0 - beta2 ** step)
        scale = 0.35 if key in _TEMPORAL_PARAMETER_KEYS else 0.12 if key in _CONV_PARAMETER_KEYS else 1.0
        if decay > 0.0 and (key.endswith('_w') or key in {'action_embedding', 'duration_embedding', 'conv_master_w'}):
            parameter *= max(0.0, 1.0 - effective_lr * scale * decay)
        parameter -= effective_lr * scale * corrected_m / (np.sqrt(corrected_v) + epsilon)
    return float(effective_lr)

def online_adapter_hidden(np, model: dict, hidden, return_cache: bool=False):
    base = np.asarray(hidden, dtype=np.float32)
    weights = np.asarray(model.get('online_adapter_w', np.zeros(base.shape[-1])), dtype=np.float32)
    bias = np.asarray(model.get('online_adapter_b', np.zeros(base.shape[-1])), dtype=np.float32)
    if weights.shape != (base.shape[-1],) or bias.shape != (base.shape[-1],):
        raise ValueError('在线 adapter 尺寸无效')
    preactivation = base * weights + bias
    residual = np.tanh(preactivation).astype(np.float32, copy=False)
    adapted = (base + ONLINE_ADAPTER_SCALE * residual).astype(np.float32, copy=False)
    if return_cache:
        return (adapted, (base, residual))
    return adapted

def _batch_twin_q_outputs_from_hidden(np, model: dict, hidden_matrix, hidden_is_adapted: bool=False):
    hidden_matrix = np.asarray(hidden_matrix, dtype=np.float32)
    if not hidden_is_adapted:
        hidden_matrix = online_adapter_hidden(np, model, hidden_matrix)
    factors = model['action_factors'].astype(np.int64, copy=False)
    key_matrix = model['action_key_multihot'].astype(np.float32, copy=False)
    button_matrix = model['action_button_multihot'].astype(np.float32, copy=False)
    q_control = np.einsum('bh,tvhc->btvc', hidden_matrix, model['q_control_w']) + model['q_control_b'][None, :, :, :]
    q_key = np.einsum('bh,tvhk->btvk', hidden_matrix, model['q_key_w']) + model['q_key_b'][None, :, :, :]
    q_mouse = np.einsum('bh,tvhm->btvm', hidden_matrix, model['q_mouse_w']) + model['q_mouse_b'][None, :, :, :]
    q_button = np.einsum('bh,tvhu->btvu', hidden_matrix, model['q_button_w']) + model['q_button_b'][None, :, :, :]
    factor_q = (q_control[:, :, :, factors[:, 0]] + q_mouse[:, :, :, factors[:, 1]] + np.einsum('btvk,ak->btva', q_key, key_matrix, optimize=True) + np.einsum('btvu,au->btva', q_button, button_matrix, optimize=True)) / 4.0
    exact_q = np.einsum('bh,tvha->btva', hidden_matrix, model['q_action_w']) + model['q_action_b'][None, :, :, :]
    return (0.7 * factor_q + 0.3 * exact_q).astype(np.float32)

def _batch_model_outputs_from_hidden(np, model: dict, hidden_matrix):
    hidden_matrix = online_adapter_hidden(np, model, np.asarray(hidden_matrix, dtype=np.float32))
    factors = model['action_factors'].astype(np.int64, copy=False)
    policy_control = hidden_matrix @ model['policy_control_w'] + model['policy_control_b']
    policy_key = hidden_matrix @ model['policy_key_w'] + model['policy_key_b']
    policy_mouse = hidden_matrix @ model['policy_mouse_w'] + model['policy_mouse_b']
    policy_button = hidden_matrix @ model['policy_button_w'] + model['policy_button_b']
    key_matrix = model['action_key_multihot'].astype(np.float32, copy=False)
    button_matrix = model['action_button_multihot'].astype(np.float32, copy=False)
    factor_logits = (policy_control[:, factors[:, 0]] + policy_mouse[:, factors[:, 1]] + policy_key @ key_matrix.T + policy_button @ button_matrix.T) / 4.0
    memorized_logits = hidden_matrix @ model['policy_action_w'] + model['policy_action_b']
    logits = (0.7 * factor_logits + 0.3 * memorized_logits).astype(np.float64)
    logits -= logits.max(axis=1, keepdims=True)
    probabilities = np.exp(np.clip(logits, -60.0, 30.0))
    probabilities /= np.maximum(1e-12, probabilities.sum(axis=1, keepdims=True))
    twin_q_values = _batch_twin_q_outputs_from_hidden(np, model, hidden_matrix, hidden_is_adapted=True)
    q_values = np.minimum(twin_q_values[:, 0], twin_q_values[:, 1])
    values = hidden_matrix @ model['value_w'] + model['value_b']
    return (probabilities.astype(np.float32), q_values.astype(np.float32), values[:, 0].astype(np.float32))

def factorized_twin_q_outputs_from_hidden(np, model: dict, hidden, hidden_is_adapted: bool=False):
    hidden_value = np.asarray(hidden, dtype=np.float32)[None, :]
    return _batch_twin_q_outputs_from_hidden(np, model, hidden_value, hidden_is_adapted=hidden_is_adapted)[0]

def factorized_action_outputs_from_hidden(np, model: dict, hidden):
    hidden_value = np.asarray(hidden, dtype=np.float32).reshape(-1)
    cached = model.get('_accelerated_policy_cache')
    if isinstance(cached, tuple) and len(cached) == 3:
        cache_key = hashlib.blake2s(hidden_value.tobytes(), digest_size=8).digest()
        if hmac.compare_digest(cache_key, cached[0]):
            probabilities = np.asarray(cached[1], dtype=np.float32)
            adapted_hidden = np.asarray(cached[2], dtype=np.float32)
            twin_values = factorized_twin_q_outputs_from_hidden(np, model, adapted_hidden, hidden_is_adapted=True)
            return (probabilities.copy(), np.minimum(twin_values[0], twin_values[1]).astype(np.float32), adapted_hidden.copy())
    adapted_hidden = online_adapter_hidden(np, model, hidden)
    probabilities, q_values, _ = _batch_model_outputs_from_hidden(np, model, np.asarray(hidden, dtype=np.float32)[None, :])
    return (probabilities[0], q_values[0], adapted_hidden)

def sequence_training_windows(records: list[dict], sequence_length: int, burn_in_steps: int) -> list[tuple[list[dict], int]]:
    length = max(32, min(256, int(sequence_length)))
    burn = max(0, min(min(64, length - 1), int(burn_in_steps)))
    episodes: dict[tuple[str, str, str], list[dict]] = {}
    for record in records:
        run_id = str(record.get('run_id', record['episode_id']))
        episode_id = str(record['episode_id'])
        sequence_id = str(record.get('_sequence_id', episode_id))
        episodes.setdefault((run_id, episode_id, sequence_id), []).append(record)
    windows: list[tuple[list[dict], int]] = []
    for episode_records in episodes.values():
        for continuous_part in _continuous_trajectory_parts(episode_records):
            for start in range(0, len(continuous_part), length):
                context_start = max(0, start - burn)
                train_end = min(len(continuous_part), start + length)
                lookahead = max((int(item.get('n_steps', 1)) for item in continuous_part[start:train_end]), default=1)
                end = min(len(continuous_part), train_end + lookahead)
                window = continuous_part[context_start:end]
                if window:
                    windows.append((window, start - context_start))
    return windows

def evaluate_model_records(np, model: dict, items: list[dict]) -> dict[str, float]:
    empty = {'accuracy': 0.0, 'human_log_likelihood': 0.0, 'progress_accuracy': 0.0, 'return_ranking_accuracy': 0.0, 'q_mae': 0.0, 'q_calibration_error': 1.0, 'value_mae': 0.0, 'safety_error': 1.0, 'score': -0.2, 'episode_count': 0.0, 'success_episode_rate': 0.0, 'average_survival_steps': 0.0, 'actual_cumulative_score': 0.0, 'episode_test_score': 0.0, 'outcome_prediction_score': 0.0, 'outcome_accuracy': 0.0, 'explicit_outcome_count': 0.0, 'victory_episode_rate': 0.0, 'death_episode_rate': 0.0, 'level_episode_rate': 0.0, 'explicit_score_delta': 0.0, 'world_reward_mae': -1.0, 'world_done_brier': -1.0, 'world_latent_error': -1.0, 'world_multistep_error': -1.0, 'world_slot_error': -1.0, 'world_hud_error': -1.0, 'world_event_brier': -1.0}
    if not items:
        return empty
    human_total = 0
    human_correct = 0
    human_log_probabilities = []
    q_errors = []
    value_errors = []
    safety_errors = []
    world_reward_errors = []
    world_done_errors = []
    world_latent_errors = []
    world_multistep_errors = []
    world_slot_errors = []
    world_hud_errors = []
    world_event_errors = []
    outcome_error_total = 0.0
    outcome_weight_total = 0.0
    outcome_correct_total = 0.0
    progress_pairs = 0
    progress_correct = 0
    return_pairs = 0
    return_correct = 0
    current_sequence = None
    previous_step = None
    hidden = None
    episode_outputs = []
    episode_tests = []

    def outcome_target(record: dict) -> tuple[float | None, float]:
        outcome_type = int(record.get('outcome_type', OUTCOME_NONE))
        confidence = max(0.0, min(1.0, float(record.get('outcome_confidence', 0.0))))
        if outcome_type == OUTCOME_DEATH:
            return (-1.0, confidence)
        if outcome_type == OUTCOME_VICTORY:
            return (1.0, confidence)
        if outcome_type == OUTCOME_LEVEL:
            return (0.8, confidence)
        if outcome_type == OUTCOME_SCORE:
            delta = float(record.get('score_delta', 0.0))
            if abs(delta) <= 1e-12:
                return (None, 0.0)
            return (math.tanh(delta / max(1.0, abs(delta) * 0.25)), confidence)
        return (None, 0.0)

    def finish_episode():
        nonlocal progress_pairs, progress_correct, return_pairs, return_correct, episode_outputs
        if len(episode_outputs) >= 2:
            for left in range(0, len(episode_outputs) - 4, max(1, len(episode_outputs) // 12)):
                right = min(len(episode_outputs) - 1, left + max(4, len(episode_outputs) // 4))
                a, b = (episode_outputs[left], episode_outputs[right])
                task_difference = b['task_return'] - a['task_return']
                if a['source'] == 'human' and b['source'] == 'human':
                    progress_pairs += 1
                    progress_correct += int(b['progress'] > a['progress'])
                elif abs(task_difference) > 0.1:
                    progress_pairs += 1
                    progress_correct += int((b['progress'] > a['progress']) == (task_difference > 0.0))
                if abs(b['return'] - a['return']) > 0.05:
                    return_pairs += 1
                    return_correct += int((b['value'] > a['value']) == (b['return'] > a['return']))
        if len(episode_outputs) >= 5:
            stride = max(1, len(episode_outputs) // 8)
            for start in range(0, len(episode_outputs) - 4, stride):
                rollout_steps = min(6, len(episode_outputs) - start - 1)
                latent = world_model_latent(np, model, episode_outputs[start]['hidden'])
                for offset in range(rollout_steps):
                    item = episode_outputs[start + offset]
                    latent, _, _ = latent_world_model_step(np, model, latent, int(item['action']), int(item['duration_index']), action_payload=item.get('action_payload'))
                target_latent = world_model_latent(np, model, episode_outputs[start + rollout_steps]['hidden'])
                world_multistep_errors.append(float(np.sqrt(np.mean((latent - target_latent) ** 2))))
        if episode_outputs:
            task_total = sum((float(item['task_reward']) for item in episode_outputs))
            safety_total = sum((float(item['safety_penalty']) for item in episode_outputs))
            explicit = [item for item in episode_outputs if int(item['outcome_type']) != OUTCOME_NONE and float(item['outcome_confidence']) > 0.0]
            victory = max((float(item['outcome_confidence']) for item in explicit if int(item['outcome_type']) == OUTCOME_VICTORY), default=0.0)
            death = max((float(item['outcome_confidence']) for item in explicit if int(item['outcome_type']) == OUTCOME_DEATH), default=0.0)
            level = max((float(item['outcome_confidence']) for item in explicit if int(item['outcome_type']) == OUTCOME_LEVEL), default=0.0)
            score_delta = sum((float(item['score_delta']) * float(item['outcome_confidence']) for item in explicit if int(item['outcome_type']) == OUTCOME_SCORE))
            trajectory_class = str(episode_outputs[-1].get('trajectory_class', ''))
            source_name = str(episode_outputs[-1].get('source', ''))
            if victory > 0.0 or death > 0.0:
                actual_success = victory > death
            elif level > 0.0 or score_delta > 0.0:
                actual_success = True
            else:
                actual_success = trajectory_class == 'successful_ai' or (source_name == 'human' and task_total > max(0.05, safety_total * 0.5))
            episode_tests.append({'success': float(actual_success), 'survival': float(len(episode_outputs)), 'score': float(score_delta if explicit else task_total), 'victory': float(victory > 0.0), 'death': float(death > 0.0), 'level': float(level > 0.0), 'explicit': float(bool(explicit))})
        episode_outputs = []
    for record in sorted(items, key=lambda item: (str(item.get('run_id', item['episode_id'])), str(item['episode_id']), str(item.get('_sequence_id', item['episode_id'])), int(item['step']))):
        run_id = str(record.get('run_id', record['episode_id']))
        episode_id = str(record['episode_id'])
        sequence_key = (run_id, episode_id, str(record.get('_sequence_id', episode_id)))
        current_step = int(record['step'])
        if sequence_key != current_sequence or (previous_step is not None and current_step != previous_step + 1):
            finish_episode()
            current_sequence = sequence_key
            hidden = np.zeros(int(model['hidden_size']), dtype=np.float32)
        frames, actions, durations = decode_temporal_state(record['state'])
        hidden = recurrent_model_step(np, model, frames[-1], hidden, actions[-1], durations[-1])
        probabilities, q_values, _ = factorized_action_outputs_from_hidden(np, model, hidden)
        action_id = int(record['action'])
        probability = max(1e-09, float(probabilities[action_id]))
        greedy_match = int(int(np.argmax(probabilities)) == action_id)
        if record['source'] == 'human':
            human_total += 1
            human_correct += greedy_match
            human_log_probabilities.append(math.log(probability))
        critic_prediction = q_values[:, action_id]
        critic_target = np.asarray([float(record.get('n_task_return', record.get('task_reward', 0.0))), float(record.get('n_exploration_return', record.get('exploration_reward', 0.0))), float(record.get('n_safety_return', record.get('safety_penalty', 0.0)))], dtype=np.float32)
        q_data = float(combined_critic_values(np, critic_prediction[:, None])[0])
        value = float(hidden @ model['value_w'][:, 0] + model['value_b'][0])
        target_return = float(record.get('n_return', record.get('reward', 0.0)))
        value_errors.append(abs(q_data - value))
        q_errors.append(float(np.mean(np.abs(critic_prediction - critic_target))))
        safe_target = max(0.0, min(1.0, float(record.get('n_safety_return', 0.0)) / 4.0))
        safe_prediction = predict_safety_probability(np, model, hidden)
        safety_errors.append(abs(safe_prediction - safe_target))
        latent = world_model_latent(np, model, hidden)
        predicted_latents, predicted_rewards, predicted_done = latent_world_model_step(np, model, latent, action_id, _record_duration_index(record), action_payload=record.get('action_payload'))
        external_rewards = np.asarray([smooth_reward(float(record.get('task_reward', 0.0))), max(0.0, min(1.0, float(record.get('exploration_reward', 0.0)))), max(0.0, min(2.0, float(record.get('safety_penalty', 0.0))))], dtype=np.float32)
        world_reward_errors.append(float(np.mean(np.abs(predicted_rewards - external_rewards))))
        world_done_errors.append((float(predicted_done) - float(bool(record.get('done')))) ** 2)
        if record.get('next_state') is not None and (not bool(record.get('done'))):
            try:
                actual_next_hidden = _latest_temporal_hidden(np, model, record['next_state'])
                actual_next_latents = world_model_latent(np, model, actual_next_hidden)
                world_latent_errors.append(float(np.sqrt(np.mean((predicted_latents - actual_next_latents) ** 2))))
                structured_target = structured_world_target_from_state(np, model, record['next_state'])
                normalized_target = _runtime_module('world_model').normalize_structured_target(np, structured_target)
                if normalized_target is not None:
                    structured_prediction = _runtime_module('world_model').predict_structured_state(np, model, predicted_latents)
                    world_slot_errors.append(float(np.sqrt(np.mean((np.asarray(structured_prediction['slots'], dtype=np.float32) - np.asarray(normalized_target['slots'], dtype=np.float32)) ** 2))))
                    world_hud_errors.append(float(np.sqrt(np.mean((np.asarray(structured_prediction['hud'], dtype=np.float32) - np.asarray(normalized_target['hud'], dtype=np.float32)) ** 2))))
                    predicted_events = np.asarray([float(structured_prediction['events'].get(name, 0.0)) for name in EVENT_NAMES], dtype=np.float32)
                    target_events = np.asarray(normalized_target['events'], dtype=np.float32)
                    world_event_errors.append(float(np.mean((predicted_events - target_events) ** 2)))
            except Exception:
                pass
        explicit_target, explicit_weight = outcome_target(record)
        if explicit_target is not None and explicit_weight > 0.0:
            outcome_prediction = math.tanh(float(critic_prediction[TASK_CRITIC]))
            outcome_error_total += explicit_weight * abs(outcome_prediction - explicit_target)
            outcome_weight_total += explicit_weight
            outcome_correct_total += explicit_weight * float((outcome_prediction >= 0.0) == (explicit_target >= 0.0))
        episode_outputs.append({'source': str(record['source']), 'trajectory_class': str(record.get('trajectory_class', '')), 'progress': predict_progress(np, model, hidden), 'task_return': float(record.get('n_task_return', record.get('task_reward', 0.0))), 'return': target_return, 'value': q_data, 'action_probability': probability, 'greedy_match': float(greedy_match), 'task_reward': float(record.get('task_reward', 0.0)), 'safety_penalty': float(record.get('safety_penalty', 0.0)), 'outcome_type': int(record.get('outcome_type', OUTCOME_NONE)), 'outcome_confidence': float(record.get('outcome_confidence', 0.0)), 'score_delta': float(record.get('score_delta', 0.0)), 'hidden': np.asarray(hidden, dtype=np.float32).copy(), 'action': action_id, 'duration_index': _record_duration_index(record), 'action_payload': record.get('action_payload')})
        previous_step = current_step
    finish_episode()
    accuracy = human_correct / max(1, human_total)
    mean_log = sum(human_log_probabilities) / max(1, len(human_log_probabilities))
    random_log = math.log(max(2, len(model['action_factors'])))
    normalized_log_likelihood = max(0.0, min(1.0, 1.0 + mean_log / random_log)) if human_log_probabilities else 0.0
    progress_accuracy = progress_correct / max(1, progress_pairs)
    return_ranking_accuracy = return_correct / max(1, return_pairs)
    q_mae = sum(q_errors) / max(1, len(q_errors))
    q_calibration_error = max(0.0, min(1.0, q_mae / 3.0))
    value_mae = sum(value_errors) / max(1, len(value_errors))
    safety_error = sum(safety_errors) / max(1, len(safety_errors))
    episode_count = len(episode_tests)
    success_episode_rate = sum((item['success'] for item in episode_tests)) / episode_count if episode_count else 0.0
    average_survival_steps = sum((item['survival'] for item in episode_tests)) / episode_count if episode_count else 0.0
    actual_cumulative_score = sum((item['score'] for item in episode_tests)) / episode_count if episode_count else 0.0
    explicit_episodes = [item for item in episode_tests if item['explicit'] > 0.0]
    explicit_episode_count = len(explicit_episodes)
    victory_episode_rate = sum((item['victory'] for item in explicit_episodes)) / explicit_episode_count if explicit_episode_count else 0.0
    death_episode_rate = sum((item['death'] for item in explicit_episodes)) / explicit_episode_count if explicit_episode_count else 0.0
    level_episode_rate = sum((item['level'] for item in explicit_episodes)) / explicit_episode_count if explicit_episode_count else 0.0
    explicit_score_delta = sum((item['score'] for item in explicit_episodes)) / explicit_episode_count if explicit_episode_count else 0.0
    outcome_prediction_score = max(0.0, min(1.0, 1.0 - outcome_error_total / (2.0 * outcome_weight_total))) if outcome_weight_total > 0.0 else 0.0
    outcome_accuracy = outcome_correct_total / outcome_weight_total if outcome_weight_total > 0.0 else 0.0
    episode_test_score = outcome_prediction_score
    world_reward_mae = sum(world_reward_errors) / len(world_reward_errors) if world_reward_errors else -1.0
    world_done_brier = sum(world_done_errors) / len(world_done_errors) if world_done_errors else -1.0
    world_latent_error = sum(world_latent_errors) / len(world_latent_errors) if world_latent_errors else -1.0
    world_multistep_error = sum(world_multistep_errors) / len(world_multistep_errors) if world_multistep_errors else -1.0
    world_slot_error = sum(world_slot_errors) / len(world_slot_errors) if world_slot_errors else -1.0
    world_hud_error = sum(world_hud_errors) / len(world_hud_errors) if world_hud_errors else -1.0
    world_event_brier = sum(world_event_errors) / len(world_event_errors) if world_event_errors else -1.0
    score = 0.38 * outcome_prediction_score + 0.2 * return_ranking_accuracy + 0.14 * progress_accuracy + 0.14 * normalized_log_likelihood + 0.06 * accuracy + 0.05 * max(0.0, 1.0 - q_calibration_error) + 0.03 * max(0.0, 1.0 - safety_error)
    return {'accuracy': float(accuracy), 'human_log_likelihood': float(normalized_log_likelihood), 'progress_accuracy': float(progress_accuracy), 'return_ranking_accuracy': float(return_ranking_accuracy), 'q_mae': float(q_mae), 'q_calibration_error': float(q_calibration_error), 'value_mae': float(value_mae), 'safety_error': float(safety_error), 'score': float(score), 'episode_count': float(episode_count), 'success_episode_rate': float(success_episode_rate), 'average_survival_steps': float(average_survival_steps), 'actual_cumulative_score': float(actual_cumulative_score), 'episode_test_score': float(episode_test_score), 'outcome_prediction_score': float(outcome_prediction_score), 'outcome_accuracy': float(outcome_accuracy), 'explicit_outcome_count': float(outcome_weight_total), 'victory_episode_rate': float(victory_episode_rate), 'death_episode_rate': float(death_episode_rate), 'level_episode_rate': float(level_episode_rate), 'explicit_score_delta': float(explicit_score_delta), 'world_reward_mae': float(world_reward_mae), 'world_done_brier': float(world_done_brier), 'world_latent_error': float(world_latent_error), 'world_multistep_error': float(world_multistep_error), 'world_slot_error': float(world_slot_error), 'world_hud_error': float(world_hud_error), 'world_event_brier': float(world_event_brier)}

def train_model(np, model: dict, dataset: dict, target_model: dict, epochs: int, batch_size: int, learning_rate: float, stop_event: threading.Event | None, config: dict | None=None) -> dict:
    if not dataset or not dataset.get('train'):
        return {'samples': 0, 'accuracy': 0.0, 'value_mae': 0.0, 'validation_accuracy': 0.0, 'validation_value_mae': 0.0}
    config = config or DEFAULT_CONFIG
    records = list(dataset['train'])
    validation = list(dataset.get('validation', []))
    skills = list(dataset.get('skills', []))[:SKILL_HEAD_SIZE]
    human_records = [record for record in records if record['source'] == 'human']
    ai_records = [record for record in records if record['source'] == 'ai']
    successful_ai = [record for record in ai_records if record.get('trajectory_class') == 'successful_ai']
    failed_ai = [record for record in ai_records if record.get('trajectory_class') == 'failed_ai']
    training_round = max(0, int(model.get('training_rounds', 0)))
    elite_quality_floor = min(0.82, 0.6 + 0.025 * training_round)
    elite_human_records = [record for record in human_records if not human_record_has_explicit_failure(record) and float(record.get('episode_quality', 0.5)) >= elite_quality_floor]
    if human_records and len(elite_human_records) < min(128, len(human_records)):
        ordered_human = sorted((record for record in human_records if not human_record_has_explicit_failure(record)), key=lambda record: float(record.get('episode_quality', 0.5)), reverse=True)
        elite_human_records = ordered_human[:max(min(128, len(ordered_human)), math.ceil(len(ordered_human) * 0.35))]
    epochs = max(1, min(40, int(epochs)))
    batch_size = max(8, min(8192, int(batch_size)))
    lr = max(1e-06, min(0.02, float(learning_rate)))
    configured_bc_weight = max(0.1, min(4.0, float(config.get('behavior_cloning_weight', 1.4))))
    bc_weight = max(0.15, configured_bc_weight / math.sqrt(1.0 + max(0, int(model.get('training_rounds', 0)))))
    expectile = max(0.5, min(0.95, float(config.get('iql_expectile', 0.8))))
    temperature = max(0.25, min(10.0, float(config.get('iql_temperature', 1.5))))
    progress_margin = max(0.01, min(1.0, float(config.get('progress_margin', PROGRESS_RANK_MARGIN))))
    progress_weight = max(0.0, min(4.0, float(config.get('progress_pair_weight', 1.0))))
    skill_weight = max(0.0, min(2.0, float(config.get('skill_policy_weight', 0.35))))
    sequence_length = max(32, min(256, int(config.get('sequence_length', TRAIN_SEQUENCE_LENGTH))))
    burn_in = max(4, min(min(64, sequence_length - 1), int(config.get('burn_in_steps', TRAIN_BURN_IN_STEPS))))
    cql_weight = 0.02
    warmup_steps = max(1, int(config.get('learning_rate_warmup_steps', OPTIMIZER_WARMUP_STEPS_DEFAULT)))
    cosine_steps = max(16, int(config.get('learning_rate_cosine_steps', OPTIMIZER_COSINE_STEPS_DEFAULT)))
    weight_decay = max(0.0, min(0.1, float(config.get('weight_decay', OPTIMIZER_WEIGHT_DECAY_DEFAULT))))
    progress_reward_scale = max(0.05, min(4.0, float(config.get('progress_reward_scale', 1.0))))
    heuristic_task_aux_weight = max(0.0, min(0.5, float(config.get('heuristic_task_aux_weight', 0.12))))
    rng = np.random.default_rng(VISUAL_INITIALIZATION_SEED + int(model.get('training_rounds', 0)) * 1009 + len(records))
    semantic_cache_limit = training_vector_cache_limit(len(records))
    model['_semantic_cache_limit'] = semantic_cache_limit
    target_model['_semantic_cache_limit'] = semantic_cache_limit
    _ensure_optimizer_state(np, model)
    last_effective_lr = 0.0
    policy_loss_total = q_loss_total = value_loss_total = progress_loss_total = skill_loss_total = 0.0
    safety_loss_total = world_loss_total = 0.0
    updates = 0
    windows_per_batch = max(1, batch_size // sequence_length)
    runtime_tier = str(model.get('runtime_tier', 'low_numpy'))
    if runtime_tier == 'low_numpy':
        pretrain_limit = min(256, max(64, len(records) // 128))
    elif runtime_tier == 'high_directml':
        pretrain_limit = min(2048, max(256, len(records) // 32))
    else:
        pretrain_limit = min(1024, max(128, len(records) // 64))
    visual_pretraining = pretrain_visual_encoder(np, model, records, lr, stop_event, pretrain_limit, target_model=target_model)

    def forward_window(window: list[dict], encoder_model: dict, with_cache: bool):
        hidden = np.zeros(int(encoder_model['hidden_size']), dtype=np.float32)
        encoded = []
        previous_step: int | None = None
        for record in window:
            raise_if_cancelled(stop_event)
            current_step = int(record['step'])
            if previous_step is not None and current_step != previous_step + 1:
                hidden.fill(0.0)
            frames, actions, durations = decode_temporal_state(record['state'])
            current_frame = frames[-1]
            previous_action = actions[-1]
            previous_duration = durations[-1]
            if with_cache:
                hidden, caches = recurrent_model_step(np, encoder_model, current_frame, hidden, previous_action, previous_duration, return_cache=True)
            else:
                hidden = recurrent_model_step(np, encoder_model, current_frame, hidden, previous_action, previous_duration, return_cache=False)
                caches = None
            encoded.append((hidden.copy(), caches))
            previous_step = current_step
        return encoded

    def backpropagate_window(gradients, encoded, hidden_gradients, first_train: int, train_end: int):
        carry = np.zeros(int(model['hidden_size']), dtype=np.float32)
        for position in range(train_end - 1, first_train - 1, -1):
            raise_if_cancelled(stop_event)
            _, carry = _backprop_temporal_encoder(np, model, encoded[position][1], hidden_gradients[position] + carry, lr * 0.35, gradients, return_initial_gradient=True)

    def apply_gradients(gradients, divisor: int):
        nonlocal last_effective_lr
        if divisor <= 0:
            return
        for gradient in gradients.values():
            raise_if_cancelled(stop_event)
            gradient /= divisor
        active = [gradient for gradient in gradients.values() if np.any(gradient)]
        if active:
            clip_gradients_by_global_norm(np, active, 8.0)
            last_effective_lr = _adam_apply(np, model, gradients, lr, warmup_steps, cosine_steps, weight_decay)
            _synchronize_quantized_conv_weights(np, model)
    bc_epoch_divisor = min(8, 4 + training_round // 2)
    bc_epochs = max(1, epochs // bc_epoch_divisor) if elite_human_records else 0
    bc_windows = sequence_training_windows(elite_human_records, sequence_length, burn_in)
    for _ in range(bc_epochs):
        raise_if_cancelled(stop_event)
        rng.shuffle(bc_windows)
        for group_start in range(0, len(bc_windows), windows_per_batch):
            raise_if_cancelled(stop_event)
            gradients = _training_gradient_buffer(np, model)
            trained = 0
            for window, first_train in bc_windows[group_start:group_start + windows_per_batch]:
                raise_if_cancelled(stop_event)
                train_end = min(len(window), first_train + sequence_length)
                if train_end <= first_train:
                    continue
                encoded = forward_window(window, model, True)
                hidden_matrix = np.stack([item[0] for item in encoded[first_train:train_end]], axis=0)
                probabilities, _, _ = _batch_model_outputs_from_hidden(np, model, hidden_matrix)
                hidden_gradients = [np.zeros(int(model['hidden_size']), dtype=np.float32) for _ in window]
                for local_index, record in enumerate(window[first_train:train_end]):
                    raise_if_cancelled(stop_event)
                    position = first_train + local_index
                    action_id = int(record['action'])
                    episode_quality = float(record.get('episode_quality', 0.5))
                    if human_record_has_explicit_failure(record) or episode_quality < 0.45:
                        continue
                    quality, _, _ = human_training_signal(float(record.get('n_task_return', record['task_reward'])), False, episode_quality)
                    duration_index = _record_duration_index(record)
                    loss, hidden_gradient = _train_factor_policy(np, model, encoded[position][0], model['action_factors'][action_id], lr, bc_weight * quality, action_id=action_id, gradients=gradients, probabilities=probabilities[local_index], duration_index=duration_index, action_payload=record.get('action_payload'))
                    hidden_gradients[position] += hidden_gradient
                    policy_loss_total += loss
                    label = skill_label_for_position(window, position, skills) if skills else None
                    if label is not None:
                        skill_loss, skill_gradient = _train_skill_head(np, model, encoded[position][0], label, float(record.get('n_task_return', record.get('task_reward', 0.0))), skill_weight * quality, gradients)
                        hidden_gradients[position] += skill_gradient
                        skill_loss_total += skill_loss
                    trained += 1
                    updates += 1
                if train_end - first_train >= 5:
                    ordered = _ordered_progress_positions(window, first_train, train_end - 1)
                    if ordered is not None:
                        low_position, high_position, pair_quality = ordered
                        progress_loss, low_gradient, high_gradient = _train_progress_pair(np, model, encoded[low_position][0], encoded[high_position][0], progress_margin, progress_weight * pair_quality, gradients)
                        hidden_gradients[low_position] += low_gradient
                        hidden_gradients[high_position] += high_gradient
                        progress_loss_total += progress_loss
                backpropagate_window(gradients, encoded, hidden_gradients, first_train, train_end)
            apply_gradients(gradients, trained)
    iql_epochs = max(1, epochs - bc_epochs)
    all_windows = sequence_training_windows(records, sequence_length, burn_in)
    successful_windows = sequence_training_windows(successful_ai, sequence_length, burn_in)
    if successful_windows:
        all_windows.extend(successful_windows)
    for epoch in range(iql_epochs):
        raise_if_cancelled(stop_event)
        rng.shuffle(all_windows)
        for group_start in range(0, len(all_windows), windows_per_batch):
            raise_if_cancelled(stop_event)
            gradients = _training_gradient_buffer(np, model)
            trained = 0
            for window, first_train in all_windows[group_start:group_start + windows_per_batch]:
                raise_if_cancelled(stop_event)
                train_end = min(len(window), first_train + sequence_length)
                if train_end <= first_train:
                    continue
                encoded = forward_window(window, model, True)
                target_encoded = forward_window(window, target_model, False)
                train_items = window[first_train:train_end]
                hidden_matrix = np.stack([item[0] for item in encoded[first_train:train_end]], axis=0)
                probabilities, q_values, values = _batch_model_outputs_from_hidden(np, model, hidden_matrix)
                hidden_gradients = [np.zeros(int(model['hidden_size']), dtype=np.float32) for _ in window]
                step_to_position = {int(item['step']): index for index, item in enumerate(window)}
                for local_index, record in enumerate(train_items):
                    raise_if_cancelled(stop_event)
                    position = first_train + local_index
                    hidden = hidden_matrix[local_index]
                    action_id = int(record['action'])
                    duration_index = _record_duration_index(record)
                    observed_critics = q_values[local_index, :, action_id]
                    q_data = float(combined_critic_values(np, observed_critics[:, None], config)[0])
                    value = float(values[local_index])
                    human_policy_multiplier, _, value_weight = human_training_signal(float(record.get('n_task_return', record['task_reward'])), human_record_has_explicit_failure(record), float(record.get('episode_quality', 0.5))) if record['source'] == 'human' else (1.0, 0.0, 1.0)
                    value_loss, value_hidden_gradient = _train_value_head(np, model, hidden, q_data, value, expectile, value_weight, gradients)
                    future_step = int(record['step']) + int(record.get('n_steps', 1))
                    future_position = step_to_position.get(future_step)
                    has_future = not bool(record['n_done']) and future_position is not None and (0 <= future_position < len(target_encoded))
                    stored_task_target = float(record.get('n_task_return', record.get('task_reward', 0.0)))
                    task_return_anchor = stored_task_target
                    if has_future and abs(stored_task_target) < 0.05 and (int(record.get('outcome_type', OUTCOME_NONE)) == OUTCOME_NONE) and (future_position is not None):
                        target_progress_now = predict_progress(np, target_model, target_encoded[position][0])
                        target_progress_future = predict_progress(np, target_model, target_encoded[future_position][0])
                        target_progress_delta = float(np.clip(target_progress_future - target_progress_now, -0.5, 0.5))
                        task_return_anchor += 0.1 * target_progress_delta
                    critic_targets = np.asarray([task_return_anchor, float(record.get('n_exploration_return', record.get('exploration_reward', 0.0))), float(record.get('n_safety_return', record.get('safety_penalty', 0.0)))], dtype=np.float32)
                    if has_future:
                        online_future_hidden = encoded[future_position][0]
                        target_future_hidden = target_encoded[future_position][0]
                        critic_targets += float(record['discount_power']) * critic_bootstrap_values(np, model, online_future_hidden, config, target_model, target_future_hidden)
                    critic_targets[TASK_CRITIC] = np.clip(critic_targets[TASK_CRITIC], -3.0, 3.0)
                    critic_targets[EXPLORATION_CRITIC] = np.clip(critic_targets[EXPLORATION_CRITIC], 0.0, 3.0)
                    critic_targets[SAFETY_CRITIC] = np.clip(critic_targets[SAFETY_CRITIC], 0.0, 4.0)
                    priority_weight = min(3.0, max(0.2, float(record['priority']) / 3.0))
                    if str(record.get('source', '')) == 'human':
                        surprise_multiplier = _runtime_module('training').human_surprise_sample_weight(record)
                        configured_surprise = max(0.0, min(2.0, float(config.get('human_surprise_training_weight', 0.65))))
                        priority_weight = min(4.0, priority_weight * (1.0 + configured_surprise * (surprise_multiplier - 1.0)))
                    q_loss, q_hidden_gradient = _train_factor_q(np, model, hidden, action_id, critic_targets, lr, priority_weight, gradients=gradients, q_values=q_values[local_index], cql_weight=cql_weight, duration_index=duration_index, action_payload=record.get('action_payload'), structured_target=structured_world_target_from_state(np, model, record.get('next_state') or record.get('state')))
                    safety_target = max(0.0, min(1.0, float(record.get('n_safety_return', 0.0)) / 4.0))
                    safety_loss, safety_hidden_gradient = _train_safety_head(np, model, hidden, safety_target, priority_weight, gradients)
                    next_step_position = step_to_position.get(int(record['step']) + 1)
                    world_next_hidden = encoded[next_step_position][0] if next_step_position is not None and (not bool(record['done'])) else None
                    world_target_next_hidden = target_encoded[next_step_position][0] if next_step_position is not None and (not bool(record['done'])) else None
                    external_task_target = float(record.get('task_reward', 0.0))
                    world_task_target = smooth_reward(external_task_target)
                    world_loss, world_hidden_gradient = train_world_model_transition(np, model, hidden, world_next_hidden, action_id, (world_task_target, float(record.get('exploration_reward', 0.0)), float(record.get('safety_penalty', 0.0))), bool(record['done']), priority_weight, gradients, target_model=target_model, target_next_hidden=world_target_next_hidden, duration_index=duration_index, action_payload=record.get('action_payload'))
                    reward_model_loss, reward_model_hidden_gradient = train_reward_model_transition(np, model, hidden, world_next_hidden, record, priority_weight, gradients)
                    world_hidden_gradient += reward_model_hidden_gradient
                    world_loss += reward_model_loss
                    if local_index % WORLD_MODEL_OVERSHOOT_MIN_STEPS == 0:
                        overshoot_rollout = []
                        start_step = int(record['step'])
                        for rollout_offset in range(WORLD_MODEL_OVERSHOOT_MAX_STEPS):
                            raise_if_cancelled(stop_event)
                            rollout_position = position + rollout_offset
                            if rollout_position >= len(window):
                                break
                            rollout_record = window[rollout_position]
                            if int(rollout_record['step']) != start_step + rollout_offset:
                                break
                            rollout_next_position = step_to_position.get(int(rollout_record['step']) + 1)
                            if bool(rollout_record.get('done')):
                                overshoot_rollout.append((rollout_record, None))
                                break
                            if rollout_next_position is None:
                                break
                            overshoot_rollout.append((rollout_record, target_encoded[rollout_next_position][0]))
                        if len(overshoot_rollout) >= WORLD_MODEL_OVERSHOOT_MIN_STEPS:
                            overshoot_loss, overshoot_hidden_gradient = train_world_model_overshooting(np, model, hidden, overshoot_rollout, priority_weight * 0.35, gradients, target_model)
                            world_hidden_gradient += overshoot_hidden_gradient
                            world_loss += overshoot_loss
                    advantage = q_data - value
                    actor_weight = min(20.0, math.exp(max(-5.0, min(3.0, advantage / temperature))))
                    policy_direction = 1.0
                    if record['source'] == 'human':
                        trajectory_scale = human_policy_multiplier * (1.0 if advantage > 0.0 else 0.1)
                    elif record.get('trajectory_class') == 'successful_ai':
                        trajectory_scale = 0.9
                    elif record.get('trajectory_class') == 'failed_ai':
                        failed_return = float(record.get('n_task_return', record.get('task_reward', 0.0)))
                        failed_safety = float(record.get('n_safety_return', record.get('safety_penalty', 0.0)))
                        trajectory_scale = 0.0 if failed_return <= 0.0 or failed_safety >= 0.25 else 0.02
                        if failed_return <= -0.2 or failed_safety >= 0.5:
                            policy_direction = -1.0
                            trajectory_scale = max(0.06, trajectory_scale)
                    else:
                        trajectory_scale = 0.08
                    safe_scale = max(0.05, 1.0 - 0.55 * float(record['safety_penalty']))
                    policy_weight = policy_direction * bc_weight * actor_weight * trajectory_scale * safe_scale * min(2.0, max(0.5, float(record['priority']) / 2.0))
                    policy_loss, policy_hidden_gradient = _train_factor_policy(np, model, hidden, model['action_factors'][action_id], lr, policy_weight, action_id=action_id, gradients=gradients, probabilities=probabilities[local_index], duration_index=duration_index, action_payload=record.get('action_payload'))
                    previous_action_for_control = int(window[position - 1]['action']) if position > 0 else -1
                    next_action_for_control = int(window[position + 1]['action']) if position + 1 < len(window) else -1
                    control_loss, control_hidden_gradient = _train_control_decision_head(np, model, hidden, previous_action_for_control, action_id, next_action_for_control, bool(record['done']), max(0.1, abs(policy_weight) * 0.25), gradients)
                    hidden_gradients[position] += policy_hidden_gradient + control_hidden_gradient + q_hidden_gradient + value_hidden_gradient + safety_hidden_gradient + world_hidden_gradient
                    policy_loss_total += policy_loss + control_loss
                    q_loss_total += q_loss
                    value_loss_total += value_loss
                    safety_loss_total += safety_loss
                    world_loss_total += world_loss
                    trained += 1
                    updates += 1
                if train_end - first_train >= 5:
                    ordered = _ordered_progress_positions(window, first_train, train_end - 1)
                    if ordered is not None:
                        low_position, high_position, pair_quality = ordered
                        progress_loss, low_gradient, high_gradient = _train_progress_pair(np, model, encoded[low_position][0], encoded[high_position][0], progress_margin, progress_weight * pair_quality, gradients)
                        hidden_gradients[low_position] += low_gradient
                        hidden_gradients[high_position] += high_gradient
                        progress_loss_total += progress_loss
                backpropagate_window(gradients, encoded, hidden_gradients, first_train, train_end)
            apply_gradients(gradients, trained)
        soft_update_target_model(np, target_model, model, 0.18 if epoch == iql_epochs - 1 else 0.05)
    episode_endings: dict[str, dict] = {}
    for record in sorted(records, key=lambda item: (str(item['episode_id']), int(item['step']))):
        raise_if_cancelled(stop_event)
        episode_endings[str(record['episode_id'])] = record
