        _checked_onnx_output(np, stem, (1, 48, 26, 47), '视觉 stem')
        _checked_onnx_output(np, middle, (1, 96, 12, 23), '视觉 middle')
        _checked_onnx_output(np, final, (1, 128, 5, 11), '视觉 final')
