        semantic_embedding, semantic_scores = semantic_session.run(['semantic_embedding', 'semantic_scores'], {'semantic_features': np.zeros((1, 48), dtype=np.float32)})
        _checked_onnx_output(np, text_embedding, (1, 16), '文本 embedding')
        _checked_onnx_output(np, text_logits, (1, 8), '文本 logits')
